ns.AddQuests("c_DRUID", {
    { id = 92485, name = "A Student of Nature", level = 2, minLevel = 2, classes = 1024, giver = "Rorian the Dayseeker", start = { npc = "Rorian the Dayseeker", area = 16593, x = 42, y = 23.4 }, finish = { npc = "Xyton Silverwind", area = 16593, x = 41.6, y = 23.4 }, objective = "Read the Folded Parchment then speak with Xyton Silverwind in Thendal Grove.", desc = "While you were away dealing with our vuldren problem, our resident druid trainer--Xyton Silverwind--left this note for you. Read it as soon as you can, and then seek out Silverwind on the ground floor of this great tree just behind me.\n\nHeed his words and his counsel, he can teach you much." },
    { id = 94006, name = "The Great Ursera Spirit", level = 10, minLevel = 10, giver = "Lotheluum Starbreeze", start = { npc = "Lotheluum Starbreeze", area = 16593, x = 64, y = 75 }, finish = { npc = "Urs'endris", area = 16593, x = 69.8, y = 61.6 }, desc = "Greetings, <name>. You have progressed in your druidic studies far enough that I think it is time for you to meet one of the great spirits that reside here on Zephras. Urs'endris is a wise and noble spirit, who has taught druids how to take on the ursera shape for generations. Unfortunately his domain has begun to wither and fall into the sky like many other areas of Zephras.\n\nTo find him, travel northeast near the waterfall in the shadow of the Shrine of Akir. He should be able to instruct you further." },
    { id = 94638, name = "Strength and Mercy", level = 10, minLevel = 10, giver = "Urs'endris", start = { npc = "Urs'endris", area = 16593, x = 69.8, y = 61.6 }, finish = { npc = "Urs'endris", area = 16593, x = 69.8, y = 61.6 }, steps = { { name = "Ur'endra", area = 16593, x = 53.9, y = 65.3 } }, objective = "Find and kill Ur'endra in the Shen'dar Highlands.", desc = "You have come to me in hopes of learning to take a shape of strength. I have a task for you, though it lays heavy on my heart.\n\nMy mate, Ur'endra, has lost herself to madness and has begun to attack her own kin. Without the winds many creatures have begun to lose themselves, and with Ur'endra's great might she poses a dire threat to the delicate balance. She roams the Shen'dar Highlands to the northwest of here.\n\nShow me you have the fortitude to end her suffering and I shall grant you my blessing." },
    { id = 94911, name = "Child of Nature", level = 10, minLevel = 10, faction = "Horde", giver = "Muln Earthfury", start = { npc = "Muln Earthfury", area = 215, x = 34.9, y = 31.9 }, finish = { npc = "Turak Runetotem", area = 1638, x = 76.4, y = 27.6 }, desc = "Greetings, young <race>. I can see that you have much promise in the druidic arts. There is one who you may want to speak with in the city of Thunder Bluff by the name of Turak Runetotem. He will teach you how to reach the stronghold of the Cenarion Circle on Kalimdor, Moonglade.\n\nYou will be welcomed there, and the druids of the circle will impart their knowledge upon you.\n\nAs your people would say--go with the wind's blessing, young one. I wish you good fortune in your adventures." },
    { id = 94912, name = "Child of Nature", level = 10, minLevel = 10, faction = "Alliance", giver = "Archmage Ansirem Runeweaver", start = { npc = "Archmage Ansirem Runeweaver", area = 36, x = 18.8, y = 78.6 }, finish = { npc = "Sheldras Moontree", area = 1519, x = 35.9, y = 67.3 }, desc = "Greetings, young <class>.\n\nHave you heard of the Cenarion Circle? I'd expect not. They are an ancient order of naturalists and practitioners of the druidic arts, much like yourself. In the city of Stormwind you'll find a night elf by the name of Sheldras Moontree. He will teach you how to reach the stronghold of the Cenarion Circle on Kalimdor, a place called Moonglade.\n\nGo now. You have much to learn if you wish to save your home." },
    { id = 94913, name = "Moonglade", level = 10, minLevel = 10, faction = "Horde", giver = "Turak Runetotem", start = { npc = "Turak Runetotem", area = 1638, x = 76.4, y = 27.6 }, finish = { npc = "Dendrite Starblaze", area = 493, x = 56.2, y = 30.4 }, desc = "All druids are welcomed to the sacred lands of Moonglade.  Keeper Remulos - Moonglade's guardian - keeps watch over all druids who hibernate there. I'll teach you the spell that lets you transport yourself there. Cast it whenever you seek Moonglade's knowledge or solace.\n\nAs for your first lesson here on Azeroth, travel to Moonglade and speak with Dendrite Starblaze in Nighthaven about the path you're now on. Good luck, young druid." },
    { id = 94914, name = "Moonglade", level = 10, minLevel = 10, faction = "Alliance", giver = "Sheldras Moontree", start = { npc = "Sheldras Moontree", area = 1519, x = 35.9, y = 67.3 }, finish = { npc = "Dendrite Starblaze", area = 493, x = 56.2, y = 30.4 }, desc = "All druids are welcomed to the sacred lands of Moonglade.  Keeper Remulos - Moonglade's guardian - keeps watch over all druids who hibernate there. I'll teach you the spell that lets you transport yourself there. Cast it whenever you seek Moonglade's knowledge or solace.\n\nAs for your first lesson here on Azeroth, travel to Moonglade and speak with Dendrite Starblaze in Nighthaven about the path you're now on. Good luck, young druid." },
    { id = 98340, name = "The Great Cat Spirit (1/5)", level = 20, minLevel = 20, faction = "Horde", classes = 1024, giver = "Turak Runetotem", start = { npc = "Turak Runetotem", area = 1638, x = 76.4, y = 27.6 }, finish = { npc = "Dendrite Starblaze", area = 493, x = 56.2, y = 30.4 }, desc = "It would seem that you are ready for the next step in your journey, young druid. Dendrite Starblaze has sent for you, and wishes for you to seek him out in Moonglade once again.\n\nYou have already learned to call upon the magic to take you to Moonglade, so you should be able to embark immediately if you choose. I would suggest you leave soon, if you wish to continue your druidic training." },
    { id = 98341, name = "The Great Windborne Cat Spirit", level = 20, minLevel = 20, giver = "Dendrite Starblaze", start = { npc = "Dendrite Starblaze", area = 493, x = 56.2, y = 30.4 }, finish = { npc = "Avatar of Saeyleenan", area = 493, x = 44, y = 73.4 }, desc = "A spirit of your homeland has recently appeared here and has asked me to guide you to it. This windborne cat spirit has come to tutor and mentor you so that you may take the feline shape of the spirit on Zephras.\n\nAll druids eventually seek this wisdom, though it seems your homeland has a slightly different shape than our traditional one. If you desire to take this spirit's feline form, you will need to undergo our trial.\n\nIt can be found in the southern part of Moonglade, south of the twin bridges." },
    { id = 98342, name = "The Great Cat Spirit (3/5)", level = 20, minLevel = 20, requires = { 98341 }, faction = "Horde", classes = 1024, giver = "Great Cat Spirit", start = { npc = "Great Cat Spirit", area = 493, x = 54.6, y = 75 }, finish = { npc = "Great Cat Spirit", area = 493, x = 54.6, y = 75 }, objective = "Recover the Relic of the Fang, Relic of the Claw, and Relic of the Silent Shadow from the Stormrage Barrow Den, and return them to the Great Cat Spirit.", desc = "To draw upon my spirit, you will need more than a few words. To understand and respect my form you must prove that you can embody cunning, stealth, and if you should be cornered, ferocity.\n\nIn the Barrow Dens just east of here, are three relics of my favor you must acquire. They are guarded by powerful enraged spirits that will attack you on sight. A statue at the entrance will bless you with temporary stealth to get past them.\n\nReturn these relics to me. We will see if you are ready to take my shape." },
    { id = 98362, name = "To Thunder Bluff (5/5)", level = 20, minLevel = 20, requires = { 98739 }, faction = "Horde", classes = 1024, giver = "Dendrite Starblaze", start = { npc = "Dendrite Starblaze", area = 493, x = 56.2, y = 30.4 }, finish = { npc = "Turak Runetotem", area = 1638, x = 76.4, y = 27.6 }, desc = "The time has come for us to part ways once again, young one, as the application of your lessons takes you back to whom that sent you to me. It would seem your instructor, Turak Runetotem, has found a worthy pupil in you. I believe I see one as well. Heed his lessons and you shall soon be able to draw upon the Great Cat Spirit to take its shape.\n\nGo back to whence you came. When the time is right, we will meet again." },
    { id = 98393, name = "The Great Cat Spirit (1/5)", level = 20, minLevel = 20, faction = "Alliance", classes = 1024, giver = "Mathrengyl Bearwalker", start = { npc = "Mathrengyl Bearwalker", area = 1657, x = 35.2, y = 8 }, finish = { npc = "Dendrite Starblaze", area = 493, x = 56.2, y = 30.4 }, desc = "It would seem that you are ready for the next step in your journey, young druid. Dendrite Starblaze has sent for you, and wishes for you to seek him out in Moonglade once again.\n\nYou have already learned to call upon the magic to take you to Moonglade, so you should be able to embark immediately if you choose. I would suggest you leave soon, if you wish to continue your druidic training." },
    { id = 98394, name = "The Great Cat Spirit (2/5)", level = 20, minLevel = 20, requires = { 98393 }, faction = "Alliance", classes = 1024, giver = "Dendrite Starblaze", start = { npc = "Dendrite Starblaze", area = 493, x = 56.2, y = 30.4 }, finish = { npc = "Great Cat Spirit", area = 493, x = 54.6, y = 75 }, desc = "In the southern part of Moonglade, on a hill overlooking the bridge, resides a wise and cunning being we call the Great Cat Spirit.\n\nMuch like the Great Bear Spirit, this spirit has served as a tutor and mentor to druids that desire to take the feline shape. All druids eventually seek its wisdom, and if you desire to take the form of a cat, you will as well.\n\nGo meet with the Great Cat Spirit and learn what it will teach you." },
    { id = 98396, name = "The Great Cat Spirit (3/5)", level = 20, minLevel = 20, requires = { 98394 }, faction = "Alliance", classes = 1024, giver = "Great Cat Spirit", start = { npc = "Great Cat Spirit", area = 493, x = 54.6, y = 75 }, finish = { npc = "Great Cat Spirit", area = 493, x = 54.6, y = 75 }, objective = "Recover the Relic of the Fang, Relic of the Claw, and Relic of the Silent Shadow from the Stormrage Barrow Den, and return them to the Great Cat Spirit.", desc = "To draw upon my spirit, you will need more than a few words. To understand and respect my form you must prove that you can embody cunning, stealth, and if you should be cornered, ferocity.\n\nIn the Barrow Dens just east of here, are three relics of my favor you must acquire. They are guarded by powerful enraged spirits that will attack you on sight. A statue at the entrance will bless you with temporary stealth to get past them.\n\nReturn these relics to me. We will see if you are ready to take my shape." },
    { id = 98397, name = "To Darnassus (5/5)", level = 20, minLevel = 20, requires = { 98731 }, faction = "Alliance", classes = 1024, giver = "Dendrite Starblaze", start = { npc = "Dendrite Starblaze", area = 493, x = 56.2, y = 30.4 }, finish = { npc = "Mathrengyl Bearwalker", area = 1657, x = 35.2, y = 8 }, desc = "The time has come for us to part ways once again, young one, as the application of your lessons takes you back to whom that sent you to me. It would seem your instructor, Mathrengyl Bearwalker, has found a worthy pupil in you. I believe I see one as well. Heed his lessons and you shall soon be able to draw upon the Great Cat Spirit to take its shape.\n\nGo back to whence you came. When the time is right, we will meet again." },
    { id = 98404, name = "The Great Windborne Cat Spirit", level = 20, minLevel = 20, giver = "Avatar of Saeyleenan", start = { npc = "Avatar of Saeyleenan", area = 493, x = 44, y = 73.4 }, finish = { npc = "Avatar of Saeyleenan", area = 493, x = 44, y = 73.4 }, objective = "Recover the Relic of the Fang, Relic of the Claw, and Relic of the Silent Shadow from the Stormrage Barrow Den, and return them to the Avatar of Saeyleenan.", desc = "In order to draw upon my spirit, you will need to undergo a trail. To understand and respect my form you must prove that you can embody cunning, stealth, and if you should be cornered, ferocity.\n\nIn the Barrow Dens just east of here, are three relics you must acquire. They are guarded by powerful enraged spirits that will attack you on sight. A statue at the entrance will bless you with temporary stealth to get past them.\n\nReturn these relics to me to pass the druidic trial of these lands." },
    { id = 98405, name = "The Great Cat Spirit", level = 20, minLevel = 20, faction = "Horde", classes = 1024, giver = "Dendrite Starblaze", start = { npc = "Dendrite Starblaze", area = 493, x = 56.2, y = 30.4 }, finish = { npc = "Great Cat Spirit", area = 493, x = 54.6, y = 75 }, desc = "In the southern part of Moonglade, on a hill overlooking the bridge, resides a wise and cunning being we call the Great Cat Spirit.\n\nMuch like the Great Bear Spirit, this spirit has served as a tutor and mentor to druids that desire to take the feline shape. All druids eventually seek its wisdom, and if you desire to take the form of a cat, you will as well.\n\nGo meet with the Great Cat Spirit and learn what it will teach you." },
    { id = 98731, name = "Blessings of the Great Cat Spirit (4/5)", level = 20, minLevel = 20, requires = { 98396 }, faction = "Alliance", classes = 1024, giver = "Great Cat Spirit", start = { npc = "Great Cat Spirit", area = 493, x = 54.6, y = 75 }, finish = { npc = "Dendrite Starblaze", area = 493, x = 56.2, y = 30.4 }, desc = "Now that you have received my blessing, return to Dendrite. He will instruct you further. I do hope we meet again someday.\n\nMay the shadows forever hide you and your foes easily fall prey to your claws, young one." },
    { id = 98738, name = "Blessings of the Great Windborne Cat Spirit", level = 20, minLevel = 20, requires = { 98404 }, giver = "Avatar of Saeyleenan", start = { npc = "Avatar of Saeyleenan", area = 493, x = 44, y = 73.4 }, finish = { npc = "Dendrite Starblaze", area = 493, x = 56.2, y = 30.4 }, desc = "Now that you have received my blessing, return to Dendrite. He will instruct you further.\n\nUnfortunately I have little left to teach you for the moment. I do hope you come and visit me in Zephras again someday. I sense promise in you, young shen'dorei.\n\nMay the shadows forever hide you, your foes easily fall prey to your claws, and the winds guide your steps." },
    { id = 98739, name = "Blessings of the Great Cat Spirit (4/5)", level = 20, minLevel = 20, requires = { 98342 }, faction = "Horde", classes = 1024, giver = "Great Cat Spirit", start = { npc = "Great Cat Spirit", area = 493, x = 54.6, y = 75 }, finish = { npc = "Dendrite Starblaze", area = 493, x = 56.2, y = 30.4 }, desc = "Now that you have received my blessing, return to Dendrite. He will instruct you further. I do hope we meet again someday.\n\nMay the shadows forever hide you and your foes easily fall prey to your claws, young one." },
})

ns.AddQuests("c_HUNTER", {
    { id = 92482, name = "The Way of the Hunter", level = 2, minLevel = 2, classes = 4, giver = "Rorian the Dayseeker", start = { npc = "Rorian the Dayseeker", area = 16593, x = 42, y = 23.4 }, finish = { npc = "Tai'ree Farsight", area = 16593, x = 42.4, y = 23.6 }, objective = "Read the Scribbled Note and then speak with Tai'ree Farsight in Thendal Grove.", desc = "While you were away dealing with our vuldren problem, our resident hunter trainer--Tai'ree Farsight--left this note for you. You can find her just over yonder near the center of the village. Read the note then seek her out." },
    { id = 94007, name = "Taming the Beast", level = 10, minLevel = 10, giver = "Elayaa Easewind", start = { npc = "Elayaa Easewind", area = 16593, x = 45.2, y = 44.2 }, finish = { npc = "Quel'ana Quickgale", area = 16593, x = 59.6, y = 72.6 }, desc = "Now that you've gained a level of comfort in the wilds of the highlands, I believe it is time for you to seek your very own animal companion.\n\nGo to the port of Valanaar to the southeast, and speak with Quel'ana Quickgale there. He will instruct you in the art of beast taming." },
    { id = 94013, name = "Taming the Beast", level = 10, minLevel = 10, giver = "Quel'ana Quickgale", start = { npc = "Quel'ana Quickgale", area = 16593, x = 59.6, y = 72.6 }, finish = { npc = "Quel'ana Quickgale", area = 16593, x = 59.6, y = 72.6 }, objective = "Use the Taming Rod to tame a Vuldren Alpha in the Gustberry Lowlands. Practice your skills, then return the Taming Rod to Quel'ana Quickgale in Valanaar.", desc = "You've returned triumphant from taming two beasts, it's time now for your last trial. The winds of Zephras whisper of greater challenges ahead.\n\nTake this Taming Rod and journey to the Gustberry Lowlands. There, tame a Vuldren Alpha and prove your mastery.\n\nComplete this lesson and you'll be ready to learn the deeper ways of the hunter." },
    { id = 94050, name = "Training the Beast", level = 10, minLevel = 10, giver = "Quel'ana Quickgale", start = { npc = "Quel'ana Quickgale", area = 16593, x = 59.6, y = 72.6 }, finish = { npc = "Quel'dora Quickgale", area = 16593, x = 59.6, y = 72.6 }, desc = "You now have the power to tame a pet, but you must also gain the skills to train it. For this, there is none better than my sister, Quel'dora. She will give you the ability to train your new pet.\n\nGo with the winds, young <class>." },
    { id = 94792, name = "Taming the Beast (1/4)", level = 10, minLevel = 10, faction = "Alliance", classes = 4, giver = "Josephine Carson", start = { npc = "Josephine Carson", area = 12, x = 41.2, y = 66.2 }, finish = { npc = "Josephine Carson", area = 12, x = 41.2, y = 66.2 }, objective = "Use the Taming Rod to tame a Rockhide Boar. Practice your skills, then return the Taming Rod to Josephine Carson.", desc = "Many hunters prefer to travel with animal companions. With a beast at your side, you will find that you can survive even the most dangerous of circumstances. As they say, everything is easier with a friend. However, obtaining an animal companion is something that must be done with care. The balance of nature is delicate, and must always be respected.\n\nTake this Taming Rod with you to the forest. With it, you will be able to tame a Rockhide Boar and practice your skills as a hunter." },
    { id = 94793, name = "Training the Beast (4/4)", level = 10, minLevel = 10, requires = { 94864 }, faction = "Alliance", classes = 4, giver = "Josephine Carson", start = { npc = "Josephine Carson", area = 12, x = 41.2, y = 66.2 }, finish = { npc = "Isaac Chan", area = 12, x = 41.8, y = 66.4 }, desc = "You now have the power to tame a pet, but you must also gain the skills to train it. For this, there is none better than Isaac Chan, a lifelong woodsman. He will give you the ability to train your new pet.\n\nGo with the winds, young <class>." },
    { id = 94863, name = "Taming the Beast (2/4)", level = 10, minLevel = 10, requires = { 94792 }, faction = "Alliance", classes = 4, giver = "Josephine Carson", start = { npc = "Josephine Carson", area = 12, x = 41.2, y = 66.2 }, finish = { npc = "Josephine Carson", area = 12, x = 41.2, y = 66.2 }, objective = "Use the Taming Rod to tame a Gray Forest Wolf. Practice your skills, then return the Taming Rod to Josephine Carson.", desc = "You've alraedy mastered taming a boar, now it's time for the next lesson. The forest holds fiercer companions, and with care, you can earn their trust.\n\nTake this Taming Rod and seek out a Gray Forest Wolf. Remember, nature's balance must be respected. Prove your skill as a hunter once more." },
    { id = 94864, name = "Taming the Beast (3/4)", level = 10, minLevel = 10, requires = { 94863 }, faction = "Alliance", classes = 4, giver = "Josephine Carson", start = { npc = "Josephine Carson", area = 12, x = 41.2, y = 66.2 }, finish = { npc = "Josephine Carson", area = 12, x = 41.2, y = 66.2 }, objective = "Use the Taming Rod to tame a Young Forest Bear. Practice your skills, then return the Taming Rod to Josephine Carson.", desc = "You've proven yourself by taming a boar and a wolf, now it's time for your final challenge. Elwynn's balance depends on respect and skill. Take this Taming Rod and seek out a Young Forest Bear. Show that you can earn the trust of even the mightiest companion.\n\nCompleting this lesson will deepen your attunement to beasts." },
    { id = 94978, name = "Taming the Beast", level = 10, minLevel = 10, giver = "Quel'ana Quickgale", start = { npc = "Quel'ana Quickgale", area = 16593, x = 59.6, y = 72.6 }, finish = { npc = "Quel'ana Quickgale", area = 16593, x = 59.6, y = 72.6 }, objective = "Use the Taming Rod to tame a Windsong Crawler found near bodies of water.\nPractice your skills, then return the Taming Rod to Quel'ana Quickgale in Valanaar.", desc = "Every hunter begins by learning the bond between beast and master. This is your first challenge. In time, you'll tame creatures from every corner of the world, but for now, start with our rivers and lakes on Zephras.\n\nTake this Taming Rod and seek out a Windsong Crawler.\n\nShow that you can earn its trust, and begin your path toward true mastery." },
    { id = 94979, name = "Taming the Beast", level = 10, minLevel = 10, giver = "Quel'ana Quickgale", start = { npc = "Quel'ana Quickgale", area = 16593, x = 59.6, y = 72.6 }, finish = { npc = "Quel'ana Quickgale", area = 16593, x = 59.6, y = 72.6 }, objective = "Use the Taming Rod to tame an Ornery Galestrider in the Gustberry Lowlands.\nPractice your skills, then return the Taming Rod to Quel'ana Quickgale in Valanaar.", desc = "You've proven you can tame the river's crawler, now it's time to test your skill on open ground. The plains of Zephras echo with the cries of the Galestrider, a proud, winged hunter that runs like the wind.\n\nTake this Taming Rod and seek one out. Travel to the lowlands and earn its trust.\n\nShow you're ready for the trials yet to come." },
})

ns.AddQuests("c_MAGE", {
    { id = 92481, name = "A Student of the Arcane", level = 2, minLevel = 2, faction = "Alliance", classes = 128, giver = "Rorian the Dayseeker", start = { npc = "Rorian the Dayseeker", area = 16593, x = 42, y = 23.4 }, finish = { npc = "Dorii Brightwhisper", area = 16593, x = 41.6, y = 23.6 }, objective = "Examine the Glowing Recall Crystal, then speak with Dorii Brightwhisper in Thendal Grove.", desc = "While you were away dealing with our vuldren problem, our resident mage trainer--Dorii Brightwhisper--left this recall crystal for you. It contains some sort of message for you, so give it a look. Afterwards, you can find Dorii in the structure just behind me." },
    { id = 93791, name = "Speak with Belann", level = 10, minLevel = 10, faction = "Alliance", classes = 128, giver = "Anathamaas Aetherwind", start = { npc = "Anathamaas Aetherwind", area = 16593, x = 65.8, y = 80.4 }, finish = { npc = "Belann Windwood", area = 16593, x = 62.8, y = 77.4 }, desc = "<name>, it is clear your skill with magic is growing and I believe it is time for you to partake in one of the High Order's oldest traditions for young and aspiring mages. It is time for you to craft a spell focus of your own.\n\nSeek out Belann Windwood in Valanaar. He has been crafting staves and wands for the High Order for over a century, so you will be in good hands." },
    { id = 93797, name = "Boughs in the Wind", level = 10, minLevel = 10, requires = { 93791 }, faction = "Alliance", classes = 128, giver = "Belann Windwood", start = { npc = "Belann Windwood", area = 16593, x = 62.8, y = 77.4 }, finish = { npc = "Belann Windwood", area = 16593, x = 62.8, y = 77.4 }, objective = "Bring a Wind-Infused Bough to Belann Windwood in Valanaar.", desc = "It is a time-honored tradition for young mages to create their own spell focus when they have shown a certain degree of magical proficiency. This is typically done by gathering a fallen branch from our oldest trees, as they have some lingering traces of elemental wind.\n\nI have found the most ideal ones to be near the wind shrine, just south of Falaath Village. Go and bring me back a large branch and I will teach you about the traditions as we create your spell focus." },
    { id = 97286, name = "Research Access", level = 20, minLevel = 1, classes = 128, giver = "Garion Wendell", start = { npc = "Garion Wendell", area = 1519, x = 48.9, y = 86.5 }, finish = { npc = "Owen Thadd", area = 1497, x = 73.6, y = 33 } },
    { id = 98576, name = "Glyphic Parchment", level = 1, minLevel = 1, faction = "Horde", classes = 128, giver = "Gornek", start = { npc = "Gornek", area = 14, x = 42, y = 68.4 }, finish = { npc = "Mai'ah", area = 14, x = 42.4, y = 69 }, objective = "Read the Glyphic Parchment and speak with Mai'ah near the entrance to the Den in the Valley of Trials.", desc = "Ah, while you were gone a parchment came for you, <name>.\n\nRead it when you have time. If I'm not mistaken, it came from the mage trainer Mai'ah. She would have words with you when you're ready." },
})

ns.AddQuests("c_PALADIN", {
    { id = 90902, name = "Rediscovering the Light", level = 2, minLevel = 2, requires = { 91282 }, faction = "Horde", classes = 2, giver = "Aramis Hammerhand", start = { npc = "Aramis Hammerhand", area = 85, x = 31, y = 66.2 }, finish = { npc = "Aramis Hammerhand", area = 85, x = 31, y = 66.2 }, steps = { { name = "Injured Deathguard", area = 85, x = 32.2, y = 64.1 } }, objective = "Heal 5 Injured Deathguard with your Holy Light ability.", desc = "I am proud to welcome another newly risen paladin to our ranks. As you begin to reconnect with the light you may notice that certain abilities that were once second nature to you may cause you considerable pain to use now, particularly those involving channeling the light to heal yourself or others.\n\nThe only way around this problem is--unfortunately--to go through it. Like any other muscle that has atrophied, you must push through the pain and exercise the flesh for it to return to full function." },
    { id = 91208, name = "Coming to Terms", level = 4, minLevel = 4, faction = "Horde", classes = 2, giver = "Aramis Hammerhand", start = { npc = "Aramis Hammerhand", area = 85, x = 31, y = 66.2 }, finish = { npc = "Aramis Hammerhand", area = 85, x = 31, y = 66.2 }, steps = { { name = "Frightened Paladin", area = 85, x = 27.6, y = 63.8 } }, objective = "Find the Frightened Paladin in Deathknell.", desc = "Not all of our fellow Paladins who rise again are quick to acclimate to our new reality. Some struggle to reconcile that they are now, in a way, the very thing they spent their lives fighting against.\n\nThese individuals often simply need a kind gesture and a sympathetic ear. Unfortunately, many others are quick to turn violent. Find the frightened paladin who fled into the hills directly west of this chapel. Extend a hand in friendship. Lead them back into the light if you can." },
    { id = 91209, name = "Continue Your Training", level = 4, minLevel = 4, requires = { 91208 }, faction = "Horde", classes = 2, giver = "Aramis Hammerhand", start = { npc = "Aramis Hammerhand", area = 85, x = 31, y = 66.2 }, finish = { npc = "Shari Stilwell", area = 85, x = 60.2, y = 52.6 }, steps = { { name = "Shari Stilwell", area = 85, x = 60.2, y = 52.5 } }, objective = "Follow the road east out of Deathknell to find the town of Brill. Report to Shari Stilwell to continue your training.", desc = "Lordaeron may not be what it used to be, but our home still needs protection from all manner of threats and it's time for you to go out and face the world. Your next stop should be the town of Brill in central Tirisfal Glades. Go and meet with Shari Stilwell there. She can see to your continued training.\n\nOne last bit of advice before you go--take extra care as a paladin traveling through Forsaken lands. There are many in the Dark Lady's service who distrust us and our proximity to the light." },
    { id = 91282, name = "A Second Home", level = 11, minLevel = 8, faction = "Horde", classes = 2, giver = "Shari Stilwell", start = { npc = "Shari Stilwell", area = 85, x = 60.2, y = 52.6 }, finish = { npc = "Breton Samuels", area = 85, x = 21.8, y = 45.2 }, desc = "It is encouraging to see my newly risen brothers and sisters thrive as you have. It is only through community and shared faith that we can truly realize our full potential however, and to that end we've begun to form a new paladin order right here in Tirisfal.\n\nIf you wish to learn more, you should visit our monastery at Northface Rock. It is called Bandarion Keep. It's on the bluffs just northwest of the Solliden Farmstead, and should be hard to miss." },
    { id = 91285, name = "Murlocs at the Gates", level = 11, minLevel = 7, faction = "Horde", classes = 2, giver = "Breton Samuels", start = { npc = "Breton Samuels", area = 85, x = 21.8, y = 45.2 }, finish = { npc = "Breton Samuels", area = 85, x = 21.8, y = 45.2 }, steps = { { name = "Vile Fin Seer", area = 85, x = 16.1, y = 56.1 }, { name = "Vile Fin Attacker", area = 85, x = 16.4, y = 56.6 } }, objective = "Slay 8 Vile Fin Attackers and 8 Vile Fin Seers and report back to Breton Samuels when it is done.", desc = "Normally we'd show our newcomers a bit more hospitality, but we've got a bit of a murloc problem at the moment.\n\nA tribe of murlocs used to use the keep as their spawning grounds. They've been a problem since we moved in and kicked them out, but now it's starting to get out of hand. You look like you've seen some action. Do you think you could help us drive back some of these pests? You'll find them lurking in the bluffs along the road to the east, and in the camps around the lake to the west." },
    { id = 91294, name = "Touring the Grounds", level = 11, minLevel = 8, requires = { 91285 }, faction = "Horde", classes = 2, giver = "Breton Samuels", start = { npc = "Breton Samuels", area = 85, x = 21.8, y = 45.2 }, finish = { npc = "Danitha Morr", area = 85, x = 22, y = 44.6 }, steps = { { name = "Danitha Morr", area = 85, x = 22, y = 44.6 }, { name = "Hilda the Breaker", area = 85, x = 22, y = 47.2 }, { name = "Jorin Croge", area = 85, x = 22.5, y = 44.8 }, { name = "Ander Solliden", area = 85, x = 23.5, y = 49.9 } }, objective = "Speak to the residents of Bandarion Keep.", desc = "Now that the immediate threat of the murloc attacks is under control, I'd encourage you to show yourself around our stronghold. It isn't much yet, but it's home.\n\nWhen you are done exploring, seek out Danitha Morr, our leader. She can help you get settled in.\n\nI'm very glad to have met you, <name>. May the light be your guide." },
    { id = 91316, name = "Making Repairs", level = 11, minLevel = 8, faction = "Horde", classes = 2, giver = "Jorin Croge", start = { npc = "Jorin Croge", area = 85, x = 22.6, y = 44.8 }, finish = { npc = "Jorin Croge", area = 85, x = 22.6, y = 44.8 }, objective = "Collect 12 pieces of Sturdy Lumber from Shadowvale in Tirisfal Glades.", desc = "This far from the Undercity, logistics are challenging and we have a dire shortage of building materials needed to help restore this fortress. I'd like your help with that.\n\nThe ruined village of Shadowvale can be found in the Whispering Forest, just southwest of here. One of the buildings has an old root cellar used to store all sorts of things. There are likely to be usable materials down there. Scavenge what you can and return to us." },
    { id = 91317, name = "The Tarnished", level = 12, minLevel = 9, faction = "Horde", classes = 2, giver = "Danitha Morr", start = { npc = "Danitha Morr", area = 85, x = 22, y = 44.6 }, finish = { npc = "Danitha Morr", area = 85, x = 22, y = 44.6 }, steps = { { name = "Tarnished Zealot slain", area = 85, x = 11.5, y = 64.2 }, { name = "Tarnished Zealot", area = 85, x = 12.7, y = 63.8 }, { name = "Tarnished Drudge", area = 85, x = 12.7, y = 63.6 } }, objective = "Slay 8 Tarnished Drudges, 6 Tarnished Zealots, and collect the head of Commander Rudolph Gelhardt in Tirisfal Glades.", desc = "Not all risen paladins have acclimated well to our new existence, as you may have seen yourself already. Some have carried forward their prejudices from life, and continue to visit violence upon their fellow Forsaken.\n\nAs it stands we are mistrusted by our people who remember well the persecution inflicted by the living in the name of the light, and these attacks do not help. A number of these tarnished have taken up residence at Shadowvale to the southwest. End them and bring me their leader's head." },
    { id = 91858, name = "Diplomatic Incident", level = 22, minLevel = 18, faction = "Horde", classes = 2, giver = "Danitha Morr", start = { npc = "Danitha Morr", area = 85, x = 22, y = 44.6 }, finish = { npc = "Trevan Rol", area = 130, x = 43.4, y = 41 }, desc = "A most unfortunate turn of events in Silverpine has presented a unique opportunity for us to prove our worth in the eyes of the horde.\n\nA pair of dignitaries from the Earthen Ring went missing in Silverpine Forest en route to Tarren Mill. We don't know much else but rumors say that this is becoming quite the diplomatic incident. If we can recover these missing persons, it could help gain us the legitimacy we so dearly need.\n\nWe have a man at The Sepulcher, Trevan Rol. Travel there and speak with him." },
    { id = 91859, name = "A Curious Pair", level = 22, minLevel = 18, faction = "Horde", classes = 2, giver = "Trevan Rol", start = { npc = "Trevan Rol", area = 130, x = 43.4, y = 41 }, finish = { npc = "Deathguard Baldren", area = 130, x = 45.6, y = 41.8 }, desc = "Cutting straight to it, these \"dignitaries\" are no ordinary diplomats. One was a Tauren. Ordinary enough for the Earthen Ring, but the other--and you'll scarcely believe this--was an elf. A *high* elf. They were cloaked, but I've seen quel'dorei before and I'd bet my good pinky finger that's what I saw.\n\nWhy was an elf accompanying a Tauren through horde territory? Well, your guess is as good as mine. That's as much as I know, so I'd suggest speaking with Deathguard Baldren near the entrance to town." },
    { id = 91860, name = "A Grim Fate", level = 22, minLevel = 18, faction = "Horde", classes = 2, giver = "Deathguard Baldren", start = { npc = "Deathguard Baldren", area = 130, x = 45.6, y = 41.8 }, desc = "Out on patrol last night I spotted a group of gnolls dumping a very large body onto a pyre on the shores of Fenris Isle. I didn't see an elf or any smaller corpses, but I'd say this doesn't bode well for them.\n\nIf you are brave or stupid you are welcome to charge into Fenris Isle to learn more, but if you ask me, its a lot of work to find some snooty elf that's probably long dead.\n\nI know you paladins love swearing oaths and taking on lost causes, but this one isn't worth it. Trust me." },
    { id = 91861, name = "Into Fenris Keep", level = 22, minLevel = 18, faction = "Horde", classes = 2, finish = { npc = "Lumina Windsinger", area = 130, x = 65.6, y = 23.2 }, desc = "<The fact that you only found only one body is a hopeful sign. Perhaps the High Elf that Trevan and Hadrec described is still alive somewhere deeper inside the nearby fortress?>" },
    { id = 91862, name = "Lumina Windsinger", level = 22, minLevel = 18, faction = "Horde", classes = 2, giver = "Lumina Windsinger", start = { npc = "Lumina Windsinger", area = 130, x = 65.6, y = 23.2 }, finish = { npc = "Lumina Windsinger", area = 130, x = 65.6, y = 23.2 }, steps = { { name = "Fenris Isle Key", area = 130, x = 65.7, y = 24.3 } }, objective = "Retrieve the Fenris Isle Key from the Rot Hide Gnolls and use it to free Lumina Windsinger.", desc = "Quel'dorei? No, I am no \"quel'dorei\". I am Lumina Windsinger and I am shen'dorei. One of the Windshaper Skyborne.\n\nI came to these lands as a guest of the Earthen Ring. My companion Banon and I were passing through Silverpine to reach the Arathi Highlands so that we could study the elemental convergences there. Clearly, we didn't make it.\n\nWe have no time for this now though. Kill the gnolls nearby. Retrieve the key to this cage and free me. I will tell you the rest once we are safely away." },
    { id = 94427, name = "A Lesson in Divinity", level = 12, minLevel = 12, faction = "Horde", classes = 2, giver = "Danitha Morr", start = { npc = "Danitha Morr", area = 85, x = 22, y = 44.6 }, finish = { npc = "Tanis Alderwood", area = 1497, x = 65.6, y = 37.8 }, desc = "A key tenant of being a paladin is the pursuit of divinity. This is not the pursuit of godhood, but merely the pursuit of good itself, for good's sake. We've all arrived at this place due to tragedy of one form or another, and it would be easy to lose that grace that defined us as paladins in life.\n\nGo to the Undercity and seek out Tanis Alderwood in the Trade Quarter. They are in need, and they could benefit greatly from some grace." },
    { id = 94434, name = "A Lesson in Divinity (1/6)", level = 12, minLevel = 12, faction = "Horde", classes = 2, giver = "Tanis Alderwood", start = { npc = "Tanis Alderwood", area = 1497, x = 65.6, y = 37.8 }, finish = { npc = "Tanis Alderwood", area = 1497, x = 65.6, y = 37.8 }, steps = { { name = "Linen Cloth", area = 1497, x = 66.1, y = 12.4 } }, objective = "Bring 10 Linen Cloth to Tanis Alderwood in the Undercity.", desc = "Wait, you want to... help? Why would a paladin want to help a beggar like me?\n\nWell, I suppose that you could be of some assistance.\n\nIts my wife you see. She, well... she's falling apart. I mean that literally. The apothecaries can stitch her back together right as rain, but they are about the Dark Lady's business and none are available to help. If you could perhaps bring me some fresh cloth then I could at least make her a wrapping to hold her together while we wait for the apothecaries." },
    { id = 94435, name = "A Lesson in Divinity (2/6)", level = 12, minLevel = 12, requires = { 94434 }, faction = "Horde", classes = 2, giver = "Tanis Alderwood", start = { npc = "Tanis Alderwood", area = 1497, x = 65.6, y = 37.8 }, finish = { npc = "Danitha Morr", area = 85, x = 22, y = 44.6 }, desc = "I don't know why you'd go out of your way to help me, but I appreciate it. If someone sent you my way, tell them I appreciate them too. You'll always have a friend in Tanis Alderwood, <class>." },
    { id = 94436, name = "A Lesson in Divinity (3/6)", level = 12, minLevel = 12, requires = { 94435 }, faction = "Horde", classes = 2, giver = "Danitha Morr", start = { npc = "Danitha Morr", area = 85, x = 22, y = 44.6 }, finish = { npc = "Deathguard Billmuth", area = 85, x = 22, y = 44.6 }, objective = "Speak with Deathguard Billmuth at Bandarion Keep.\n\nShould you misplace your Symbol of Life, return to Danitha Morr for a replacement.", desc = "It's time to demonstrate your ability to channel one of the light's greatest gifts.\n\nThe item I just gave you is called the Symbol of Life. Take care, as it may cause you some discomfort to handle a talisman of the light such as this. The light may be anathema to the force that created us, but it is still our guide and ally. The pain reminds us of this.\n\nGo see Deathguard Billmuth downstairs. He just arrived and he has petitioned us for aid. Show him and the Forsaken what a true paladin can do." },
    { id = 94438, name = "A Lesson in Divinity (4/6)", level = 12, minLevel = 12, requires = { 94436 }, faction = "Horde", classes = 2, giver = "Deathguard Billmuth", start = { npc = "Deathguard Billmuth", area = 85, x = 22, y = 44.6 }, finish = { npc = "Deathguard Falgan", area = 85, x = 86.6, y = 47.6 }, objective = "Take the Symbol of Life and use it to resurrect Deathguard Falgan at Venomweb Vale.\n\nShould you misplace your Symbol of Life, return to Danitha Morr for a replacement.", desc = "Falgan and I were sent on a mission to scout out scarlet activity in Venomweb Vale. We managed to sneak close enough to one of their camps to hear about new orders involving an attack on Brill. Before we could decide what to do next, I stepped on a twig and the noise alerted them to us.\n\nFalgan yelled at me to run, so I ran. By the time I realized he wasn't with me, I was halfway to Brill. That brave idiot probably stayed behind to hold them off for me.\n\nPlease, find my friend and help him if you can." },
    { id = 94440, name = "A Lesson in Divinity (5/6)", level = 12, minLevel = 12, requires = { 94438 }, faction = "Horde", classes = 2, giver = "Deathguard Falgan", start = { npc = "Deathguard Falgan", area = 85, x = 86.6, y = 47.6 }, finish = { npc = "Deathguard Billmuth", area = 85, x = 22, y = 44.6 }, steps = { { name = "Scarlet Crusade Attack Plans", area = 85, x = 79.2, y = 55.7 } }, objective = "Retrieve the Scarlet Crusade Attack Plans from the Scarlet Crusaders at Venomweb Vale, and return to Deathguard Billmuth at Tyr's Watch.", desc = "These Scarlet Crusaders often carry satchels with their deployment orders. We know an attack is coming, but if we can recover their orders, we can warn the rest of the Deathguard and prepare an ambush.\n\nYou are clearly an impressive paladin. Kill these scarlet animals and retrieve a copy of their orders and bring them back to Deathguard Billmuth. He'll take it from there." },
    { id = 94441, name = "A Lesson in Divinity (6/6)", level = 12, minLevel = 12, requires = { 94440 }, faction = "Horde", classes = 2, giver = "Deathguard Billmuth", start = { npc = "Deathguard Billmuth", area = 85, x = 22, y = 44.6 }, finish = { npc = "Danitha Morr", area = 85, x = 22, y = 44.6 }, desc = "Please give my thanks to Danitha Morr and tell her that the rest of the Deathguard will hear about the service that the paladins of Tyr's Watch performed for us.\n\nYou have a lot of promise as a paladin, and I am proud to have those like you among the ranks of the Forsaken. Dark Lady watch over you, <name>." },
    { id = 95034, name = "The Debt", level = 24, minLevel = 18, faction = "Horde", classes = 2, giver = "Lumina Windsinger", start = { npc = "Lumina Windsinger", area = 130, x = 43.2, y = 40.8 }, finish = { npc = "Lumina Windsinger", area = 130, x = 43.2, y = 40.8 }, steps = { { name = "Lumina Windsinger", area = 130, x = 43.2, y = 40.8 } }, objective = "Speak with Lumina Windsinger in the Sepulcher.", desc = "I think you should know that it wasn't actually the Gnolls who attacked us on the road.\n\nWe were actually attacked by a giant, wolf-like creature that I now know as a \"worgen\". It dispatched our guards and came for me, but Banon threw himself in its path. I managed to get a spell off which startled the creature, causing it to flee, but Banon was already badly bitten. He insisted I leave him there but I refused.\n\nWe were limping back here when the gnolls found us. What came next was terrifying..." },
    { id = 95036, name = "A Moon-Kissed Blade", level = 25, minLevel = 20, faction = "Horde", classes = 2, giver = "Lumina Windsinger", start = { npc = "Lumina Windsinger", area = 130, x = 43.2, y = 40.8 }, finish = { npc = "Trevan Rol", area = 130, x = 43.4, y = 41 }, objective = "Speak with Trevan Rol in the Sepulcher and bring him the materials he requires.", desc = "Trevan tells me that the worgen are a major threat to the citizens of Silverpine Forest. Despite their strength and resilience they can be killed, but there is one in particular that just doesn't ever seem to stay dead due to unknown magic.\n\nThat's the one that attacked us. He is known as Old Fire-Eye and he is the biggest and meanest of their kind. To put him down, we'll need a special kind of weapon.\n\nSpeak with Trevan and he will supply you with a list of what is needed to forge such a weapon." },
    { id = 95042, name = "Seeking the Kor Gem", level = 25, minLevel = 20, faction = "Horde", classes = 2, giver = "Ulric Frostveil", start = { npc = "Ulric Frostveil", area = 331, x = 11.8, y = 34.4 }, finish = { npc = "Ulric Frostveil", area = 331, x = 11.8, y = 34.4 }, steps = { { name = "Corrupted Kor Gem", area = 331, x = 14.7, y = 10.8 } }, objective = "Bring a Kor Gem to Ulric Frostveil in Ashenvale.", desc = "A Forsaken paladin... here in Ashenvale? Amusing.\n\nSo you seek a Kor Gem? Unsurprising as these are sometimes employed to empower magical weapons and implements by the paladins of the alliance. Why should a fallen paladin like you be any different?\n\nIf you truly desire one of the gems, then you must head north to the ruins known as Blackfathom Deeps. The naga who still use the gems are down below. Do not go alone, <class>." },
    { id = 95111, name = "An Underrated Talent", level = 25, minLevel = 20, faction = "Horde", classes = 2, giver = "Trevan Rol", start = { npc = "Trevan Rol", area = 130, x = 43.4, y = 41 }, finish = { npc = "Ott", area = 267, x = 60.4, y = 26 }, objective = "Speak with Ott and ask him to forge your blade.", desc = "In Tarren Mill there is a weaponsmith known as Ott. By all accounts he is an unremarkable smith, selling simple blades to travelers. I purchased a sword from him myself, and when I took it to the undercity for maintenance some time later, the smiths there were surprised at its quality. They assumed it came from a well known master smith, but no, it was just Ott.\n\nI'd like to give this orc a chance to do something truly special. Take the materials to Ott in Tarren Mill and offer him the commission." },
    { id = 95125, name = "Ott's Masterwork", level = 25, minLevel = 20, faction = "Horde", classes = 2, giver = "Ott", start = { npc = "Ott", area = 267, x = 60.4, y = 26 }, finish = { npc = "Ott", area = 267, x = 60.4, y = 26 }, objective = "Watch as Ott forges your blade.", desc = "These are some truly fine materials, <class>. You honor me by allowing me to forge this blade for you and I only hope that I can live up to your expectations.\n\nPlease, stand back so that I may begin the forging process." },
    { id = 95126, name = "The Moonsilver Blade", level = 25, minLevel = 20, faction = "Horde", classes = 2, giver = "Ott", start = { npc = "Ott", area = 267, x = 60.4, y = 26 }, finish = { npc = "Trevan Rol", area = 130, x = 43.4, y = 41 }, objective = "Bring Ott's Masterwork to Trevan Rol in Silverpine Forest.", desc = "Here's the blade. You said that a paladin named Trevan sent you? Please extend my thanks to him for this opportunity when you next see him. Go with honor, friend." },
    { id = 95140, name = "Old Fire-Eye", level = 26, minLevel = 20, faction = "Horde", classes = 2, giver = "Lumina Windsinger", start = { npc = "Lumina Windsinger", area = 130, x = 43.2, y = 40.8 }, finish = { npc = "Lumina Windsinger", area = 130, x = 43.2, y = 40.8 }, steps = { { name = "Old Fire-Eye", area = 130, x = 49.6, y = 86.7 } }, objective = "Use the Moonsilver Blade to destroy Old-Fire Eye in Silverpine Forest.", desc = "I see that you have your weapon now, <class>. I pray that it will not fail you.\n\nThe locals tell me that Old Fire-Eye hunts in a large area south of here and you can generally find him near the gates to Gilneas. Find him, and use your new blade to end him. When it is done, return and you will have the gratitude of the Windshapers." },
    { id = 95803, name = "A Token of Good Faith", level = 12, minLevel = 9, faction = "Horde", classes = 2, giver = "Danitha Morr", start = { npc = "Danitha Morr", area = 85, x = 22, y = 44.6 }, finish = { npc = "Lady Sylvanas Windrunner", area = 1497, x = 57.8, y = 91.8 }, objective = "Bring the head of Rudolph Gelhardt to Sylvanas Windrunner in the Undercity.", desc = "Now that we've claimed the head of the tarnished commander, I need you to deliver it to the Undercity. Sylvanas Windrunner mistrusts us greatly, and all but openly disparages us.\n\nDeliver Rudolph Gelhardt's head to the Dark Lady. Show her that we tend to our own house and are devoted to the prosperity of the forsaken." },
    { id = 96204, name = "The Windshaper's Wrath", level = 22, minLevel = 18, faction = "Horde", classes = 2, giver = "Lumina Windsinger", start = { npc = "Lumina Windsinger", area = 130, x = 65.6, y = 23.2 }, finish = { npc = "Lumina Windsinger", area = 130, x = 43.2, y = 40.8 }, objective = "Accompany Lumina Windsinger and help her escape Fenris Keep.", desc = "Now that I'm free I'm going to make these vile creatures regret ever laying eyes on a Windshaper.\n\nLet's get out of here, <class>." },
    { id = 98601, name = "A Difficult Path", level = 1, minLevel = 1, faction = "Horde", classes = 2, giver = "Shadow Priest Sarvis", start = { npc = "Shadow Priest Sarvis", area = 85, x = 30.8, y = 66.2 }, finish = { npc = "Aramis Hammerhand", area = 85, x = 31, y = 66.2 }, objective = "Read the Consecrated Scroll and speak to Aramis Hammerhand in the church in Deathknell.", desc = "While you were off dealing with the mindless Scourge, this scroll arrived for you. It reeks of the light, so I imagine its of some importance to a paladin like yourself.\n\nRead it before heading out again. Just please--step away when you do. Paladins make me quite uneasy." },
})

ns.AddQuests("c_PRIEST", {
    { id = 94773, name = "Divine Grace", level = 10, minLevel = 10, faction = "Alliance", classes = 16, giver = "High Priestess Laurena", start = { npc = "High Priestess Laurena", area = 1519, x = 49.7, y = 44.9 }, finish = { npc = "High Priestess Laurena", area = 1519, x = 49.7, y = 44.9 } },
    { id = 94774, name = "Divine Grace", level = 10, minLevel = 10, faction = "Alliance", classes = 16, giver = "Priestess Josetta", start = { npc = "Priestess Josetta", area = 12, x = 43.4, y = 65.6 }, finish = { npc = "High Priestess Laurena", area = 1519, x = 49.7, y = 44.9 }, desc = "You've caught the attention of our superiors, <name>. They've asked you travel to the Cathedral of Light in Stormwind as soon as possible. Apparently they feel you've proven yourself already and are prepared to further your training. When you get there, find High Priestess Laurena. She will be able to guide you further. Good luck, and may the Light be with you." },
    { id = 94775, name = "Divine Grace", level = 10, minLevel = 10, faction = "Alliance", classes = 16, objective = "Speak to High Priestess Laurena in Stormwind.", desc = "Elune bless you, good <race>. I hope your Light finds you and protects you well this day.\n\nOne of your priests was here not long ago looking for you. He mentioned you returning to the Cathedral of Light as soon as possible to speak with High Priestess Laurena. It seems you've done well to garner such attention. I wouldn't spend too much time here--your people have need of you." },
    { id = 94776, name = "Divine Grace", level = 10, minLevel = 10, faction = "Alliance", classes = 16, objective = "Speak to High Priestess Laurena in Stormwind.", desc = "Time's come for you to head to Stormwind, <name>. High Priestess Laurena in the Cathedral of Light wants to speak to you. Gotta be somethin' really good or really bad for the High Priestess to want you there personally, but I'm guessin' you've only done well for yourself and it's a good thing that she wants to speak to ya.\n\nBut don't waste too much time 'round here. I'd head there as soon as you can." },
    { id = 94777, name = "Divine Grace", level = 10, minLevel = 10, faction = "Alliance", classes = 16, objective = "Speak to High Priestess Laurena in Stormwind.", desc = "Just a short time ago, one of your priests was here looking for you, <race>. He said that if I were to see you, I should direct you towards the Cathedral of Light. He said it was very important, but I would not be overly concerned if I were you. His demeanor seemed positive... as though it were good news. I wouldn't take too long in making my way there if I were you.\n\nElune be with you, good <race>." },
    { id = 94778, name = "Divine Grace", level = 10, minLevel = 10, faction = "Alliance", classes = 16, objective = "Speak to High Priestess Laurena in Stormwind.", desc = "You're needed in Stormwind, <name>. The High Priestess there, Laurena, says it's time for you to prove you're worthy of the next level of your training. Don't waste too much time finding your way there. You can find her in the Cathedral of Light in the center of the city. Give her my regards, and prove how worthy you are of such a calling. The Light be with you, <name>." },
    { id = 94779, name = "Divine Grace", level = 10, minLevel = 10, faction = "Alliance", classes = 16, objective = "Speak to High Priestess Laurena in Stormwind.", desc = "Praise be to Elune, and to your Light, <name>.\n\nAbout this time, many of our order learn abilities reflecting their faith in Elune. If knowledge serves me, I believe the same holds true for your order also.\n\nWhen your business in Darnassus is complete, I would seek out one of your High Priestesses for further training." },
    { id = 94817, name = "Confounding Flash", level = 10, minLevel = 10, faction = "Alliance", classes = 16, giver = "High Priestess Mims", start = { npc = "High Priestess Mims", area = 1537, x = 24.8, y = 10 }, finish = { npc = "High Priestess Mims", area = 1537, x = 24.8, y = 10 } },
    { id = 94818, name = "Contingency Plan", level = 20, minLevel = 20, faction = "Alliance", classes = 16, giver = "High Priestess Mims", start = { npc = "High Priestess Mims", area = 1537, x = 24.8, y = 10 }, finish = { npc = "High Priestess Mims", area = 1537, x = 24.8, y = 10 } },
    { id = 94819, name = "Contingency Plan", level = 20, minLevel = 20, faction = "Alliance", classes = 16, giver = "High Priestess Laurena", start = { npc = "High Priestess Laurena", area = 1519, x = 49.7, y = 44.9 }, finish = { npc = "High Priestess Mims", area = 1537, x = 24.8, y = 10 }, desc = "<name>, your High Priestess Mims would have an audience with you in Ironforge. Make haste, my clever friend, your next test quickly approaches. Although I wish I could bear witness to your race's own special rites, my place is here. But may the Light go with you in your travels. Mims should still be in the Mystic Ward once you reach the city. She will be waiting." },
    { id = 94820, name = "Contingency Plan", level = 20, minLevel = 20, faction = "Alliance", classes = 16, objective = "Speak to High Priestess Mims in Ironforge.", desc = "Your race is so very clever, <name>. We are proud to call you allies. And as each day's sun sets, you and your kin grow closer to reclaiming your city, but with the burden of keeping your families safe in exile. That yearning for home must weigh heavily on you.\n\nWord came from Ironforge just recently. It asked that you return there and speak to High Priestess Mims in the Mystic Ward. I would not keep her waiting. May Elune guide your travels." },
    { id = 94821, name = "Confounding Flash", level = 10, minLevel = 10, faction = "Alliance", classes = 16, finish = { npc = "High Priestess Mims", area = 1537, x = 24.8, y = 10 }, desc = "A priest recently visited our halls seeking you out, young <race>. He said that he was on a mission to find you and that you should return to the Hall of Mysteries in Ironforge as soon as possible. When you arrive, seek out High Priestess Mims--she will tell you more.\n\nThe Light be with you, <name>." },
    { id = 94822, name = "Confounding Flash", level = 10, minLevel = 10, faction = "Alliance", classes = 16, finish = { npc = "High Priestess Mims", area = 1537, x = 24.8, y = 10 }, desc = "You've caught the attention of our superiors, <name>. They've asked you travel to the Hall of Mysteries in Ironforge as soon as possible. Apparently they feel you've proven yourself already and are prepared to further your training. When you get there, find High Priestess Mims. She will be able to guide you further. Good luck, and may the Light be with you." },
    { id = 94823, name = "Confounding Flash", level = 10, minLevel = 10, faction = "Alliance", classes = 16, objective = "Speak to High Priestess Mims in Ironforge.", desc = "Elune bless you, good <race>. I hope your Light finds you and protects you well this day.\n\nOne of your priests was here not long ago looking for you. He mentioned you returning to the Hall of Mysteries as soon as possible to speak with High Priestess Mims. It seems you've done well to garner such attention. I wouldn't spend too much time here--your people have need of you." },
    { id = 94824, name = "Confounding Flash", level = 10, minLevel = 10, faction = "Alliance", classes = 16, giver = "Maxan Anvol", start = { npc = "Maxan Anvol", area = 1, x = 47.2, y = 52.2 }, finish = { npc = "High Priestess Mims", area = 1537, x = 24.8, y = 10 }, desc = "Time's come for you to head to Stormwind, <name>. High Priestess Mims in the Hall of Mysteries commands you to come speak with her. Gotta be somethin' really good or really bad for the High Priestess to want you there personally, but I'm guessin' you've only done well for yourself and it's a good thing that she wants to speak to ya.\n\nBut don't waste too much time 'round here. I'd head there as soon as you can." },
    { id = 94825, name = "Confounding Flash", level = 10, minLevel = 10, faction = "Alliance", classes = 16, objective = "Speak to High Priestess Mims in Ironforge.", desc = "Just a short time ago, one of your priests was here looking for you, <race>. He said that if I were to see you, I should direct you towards the Hall of Mysteries. He said it was very important, but I would not be overly concerned if I were you. His demeanor seemed positive... as though it were good news. I wouldn't take too long in making my way there if I were you.\n\nElune be with you, good <race>." },
    { id = 94826, name = "Confounding Flash", level = 10, minLevel = 10, faction = "Alliance", classes = 16, objective = "Speak to High Priestess Mims in Ironforge.", desc = "Praise be to Elune, and to your Light, <name>.\n\nAbout this time, many of our order learn abilities reflecting their faith in Elune. If knowledge serves me, I believe the same holds true for your order also.\n\nWhen your business in Darnassus is complete, I would seek out your High Priestess for further training." },
    { id = 98574, name = "Hallowed Memorandum", level = 1, minLevel = 1, faction = "Alliance", classes = 16, giver = "Sten Stoutarm", start = { npc = "Sten Stoutarm", area = 1, x = 29.8, y = 71.2 }, finish = { npc = "Branstock Khalder", area = 1, x = 28.6, y = 66.4 }, objective = "Read the Hallowed Memorandum and speak to Branstock Khalder in Anvilmar.", desc = "While you were helping me out, this memorandum was given to me to pass on to you. Take some time to read it when you have a chance. I'm thinkin' it came from the priest trainer Branstock. Take a gander at it and go find him inside Anvilmar when you've a chance." },
})

ns.AddQuests("c_ROGUE", {
    { id = 92483, name = "At Home in the Shadows", level = 2, minLevel = 2, classes = 8, giver = "Rorian the Dayseeker", start = { npc = "Rorian the Dayseeker", area = 16593, x = 42, y = 23.4 }, finish = { npc = "Akeri Duskblade", area = 16593, x = 43.6, y = 24.2 }, objective = "Read the Simple Note then speak with Akeri Duskblade within the watchtower in Thendal Grove.", desc = "While you were away dealing with our vuldren problem, our resident rogue trainer--Akeri Duskblade--has requested to speak with you. He left this note, so read that first, then seek him out inside the watchtower, here in the village.\n\nHe's a shady fellow, but then again, so are you. I think you'll get along well." },
})

ns.AddQuests("c_SHAMAN", {
    { id = 92484, name = "Embracing the Elements", level = 2, minLevel = 2, faction = "Horde", classes = 64, giver = "Rorian the Dayseeker", start = { npc = "Rorian the Dayseeker", area = 16593, x = 42, y = 23.4 }, finish = { npc = "Windshaper Boro", area = 16593, x = 42.8, y = 23.6 }, objective = "Examine the Humming Recall Crystal then speak with Windshaper Boro in Thendal Grove.", desc = "While you were away dealing with our vuldren problem, our resident Shaman trainer--Windshaper Boro--left this recall crystal for you. Please examine it, then speak with Boro just over yonder near the center of the village." },
    { id = 94373, name = "Call of Earth (2/4)", level = 4, minLevel = 4, requires = { 96243 }, faction = "Alliance", classes = 64, giver = "Teo Hammerstorm", start = { npc = "Teo Hammerstorm", area = 1, x = 28.7, y = 66.1 }, finish = { npc = "Teo Hammerstorm", area = 1, x = 28.7, y = 66.1 }, steps = { { name = "Iceclaw Bear Pendant", area = 1, x = 26.7, y = 79.5 } }, objective = "Bring 2 Frostmane Bear Pendants to Teo Hammerstorm in Anvilmar.", desc = "Aye, the time's come, young shaman. Ye've grown stout and sturdy, like the stone beneath our boots. Takin' up the shaman's path shows ye've got the wisdom o' the mountain, even before ye've proven yerself.. Ye've the grit of stone to walk the earth's path.\n\nBut to earn its favor, ye must face it proper. South o' here, the Frostmane trolls live in a cave.\n\nBring me two of their necklaces they wear--crafted from the Iceclaw bears. Then we'll speak more of yer future." },
    { id = 94374, name = "Call of Earth (3/4)", level = 4, minLevel = 4, requires = { 94373 }, faction = "Alliance", classes = 64, giver = "Teo Hammerstorm", start = { npc = "Teo Hammerstorm", area = 1, x = 28.7, y = 66.1 }, finish = { npc = "Minor Manifestation of Earth", area = 14, x = 44, y = 76 }, objective = "Find the Spirit Stone and drink the Earth Sapta.\n\nProvided item:", desc = "Aye, sapta's a brew forged with magic, bindin' our spirit to the elements. Only a few shaman know the recipe, and it's nae for the weak-willed. Drink it, and ye will see what others can't. Hold true--it's only to be drunk in a sacred place.\n\nHead north to the Spirit Stone, tucked at the end of a hidden path up the mountain. Drink it there... see what the earth has to show ye." },
    { id = 94375, name = "Call of Earth (4/4)", level = 4, minLevel = 4, requires = { 94374 }, faction = "Alliance", classes = 64, giver = "Minor Manifestation of Earth", start = { npc = "Minor Manifestation of Earth", area = 14, x = 44, y = 76 }, finish = { npc = "Teo Hammerstorm", area = 1, x = 28.7, y = 66.1 }, objective = "Bring the Rough Quartz to Teo Hammerstorm in Anvilmar.", desc = "Take this rough quartz from me and bring it to Teo Hammerstorm as proof o' our meeting. He will craft a totem for ye, and this pebble will be the heart o' it. As small as it may seem, ye will come to find that size does not matter, and that even the smallest o' things can outlast many others.\n\nBe patient, <name>. Remain strong. And seek wisdom. This is what earth asks o' ye. In the end, ye shall become one with the earth--respect it as it shall respect ye." },
    { id = 94449, name = "Call of Fire (1/5)", level = 10, minLevel = 10, faction = "Alliance", classes = 64, giver = "Eldrun Stormbreaker", start = { npc = "Ingrid Dunwald", area = 1, x = 47.4, y = 52 }, finish = { npc = "Bruegs Kindleborn", area = 1, x = 87.6, y = 43.6 }, desc = "It's been long since ye were last tested, <name>. Ye've shown patience, aye -- but now it's time ye learned of chaos... of destruction. Fire's call is loud, and if ye're ready to pay its price, it'll speak to ye.\n\nSeek out Bruegs Kindleborn, far east in the mountains. He dwells in a cave above South Gate Outpost. He'll know if ye're truly ready." },
    { id = 94465, name = "Call of Fire (2/5)", level = 11, minLevel = 10, requires = { 94449 }, faction = "Alliance", classes = 64, giver = "Bruegs Kindleborn", start = { npc = "Bruegs Kindleborn", area = 1, x = 87.6, y = 43.6 }, finish = { npc = "Braldir Ashmantle", area = 38, x = 32, y = 66 }, objective = "Bring the Torch of the Dormant Flame to Braldir Ashmantle in Loch Modan.", desc = "Aye, ye've the strength to bear the totem o' fire, lad--but strength alone won't make ye ready.\n\nBeyond the Valley o' Kings, in the crags of Loch Modan, lies a hidden path to one o' our sacred peaks. There, Braldir Ashmantle guards the Shrine o' the Dormant Flame.\n\nTake this torch to him--it shows yer intent. Return it burnin' by the shrine's brazier, and I'll see ye earn the totem proper." },
    { id = 94466, name = "Call of Fire (3/5)", level = 14, minLevel = 10, requires = { 94465 }, faction = "Alliance", classes = 64, giver = "Braldir Ashmantle", start = { npc = "Braldir Ashmantle", area = 38, x = 32, y = 66 }, finish = { npc = "Braldir Ashmantle", area = 38, x = 32, y = 66 }, steps = { { name = "Fire Tar", area = 38, x = 35.6, y = 23.5 }, { name = "Reagent Pouch", area = 38, x = 33.2, y = 84.9 } }, objective = "Bring 1 Fire Tar and 1 Reagent Pouch to Braldir Ashmantle in Loch Modan.", desc = "Bah, ye didn't trek all this way for tales, did ye, <name>? Ye seek the Eternal Flame and the fire totem.\n\nFirst, ye'll need a sapta to bind yer spirit to the flame.\n\nI'll craft it--but I'll need two things: fire tar from Tunnel Rat Geomancers in the kobold caves up north, and a reagent pouch from a Stonesplinter Seer lurkin' in the southern hills. Dangerous work, but worthy of the flame." },
    { id = 94467, name = "Call of Fire (4/5)", level = 14, minLevel = 10, requires = { 94466 }, faction = "Alliance", classes = 64, giver = "Braldir Ashmantle", start = { npc = "Braldir Ashmantle", area = 38, x = 32, y = 66 }, finish = { npc = "Brazier of the Dormant Flame", area = 14, x = 38.9, y = 58.2 }, objective = "Defeat the Minor Manifestation of Fire, and place the Glowing Ember in the brazier atop the Shrine of Eternal Flame.", desc = "The fire sapta's ready, <name>. Now ye face the flame. Use it at the shrine, then climb to the peak. There, ye'll see the spirit--he'll not strike 'til ye do, but he'll know ye see him.\n\nStrike fast, lad. The longer ye wait, the stronger he burns. When he falls, take his glowing embers and place 'em in the brazier. Light the torch and earn the fire's favor." },
    { id = 94468, name = "Call of Fire (5/5)", level = 14, minLevel = 10, requires = { 94467 }, faction = "Alliance", classes = 64, giver = "Brazier of the Dormant Flame", start = { npc = "Brazier of the Dormant Flame", area = 14, x = 38.9, y = 58.2 }, finish = { npc = "Bruegs Kindleborn", area = 1, x = 87.6, y = 43.6 }, objective = "Bring the Torch of Eternal Flame to Bruegs Kindleborn in Dun Morogh.", desc = "Torch firmly in hand, you turn away from the brazier and look out over Loch Modan. You feel an excitement tugging at your spirit as the wind picks up and forces the flame to dance violently.\n\nYou start off down the path back to Dun Morogh in search of Bruegs Kindleborn." },
    { id = 94472, name = "Earth Sapta", level = 4, minLevel = 4, faction = "Alliance", classes = 64, giver = "Teo Hammerstorm", start = { npc = "Teo Hammerstorm", area = 1, x = 28.7, y = 66.1 }, finish = { npc = "Teo Hammerstorm", area = 1, x = 28.7, y = 66.1 } },
    { id = 94473, name = "Fire Sapta", level = 13, minLevel = 10, faction = "Alliance", classes = 64, giver = "Braldir Ashmantle", start = { npc = "Braldir Ashmantle", area = 38, x = 32, y = 66 }, finish = { npc = "Braldir Ashmantle", area = 38, x = 32, y = 66 } },
    { id = 94494, name = "Call of Water", level = 20, minLevel = 20, faction = "Alliance", classes = 64, giver = "Eldrun Stormbreaker", start = { npc = "Eldrun Stormbreaker", area = 1537, x = 47.4, y = 13.6 }, finish = { npc = "Norric Lochthane", area = 38, x = 41.8, y = 19 }, desc = "Long has it been since ye were last tested, <name>. Ye have shown patience thus far in yer studies, but the time has come for ye to learn about the purity of water.\n\nSeek out Norric Lochthane in Loch Modan. He is along the north western edge o' the lake, south of Stonewrought Dam. Ye  will find him there at his burrow hut. Good luck to ye, <name>." },
    { id = 94495, name = "Call of Water (1/8)", level = 22, minLevel = 20, faction = "Alliance", classes = 64, giver = "Norric Lochthane", start = { npc = "Norric Lochthane", area = 38, x = 41.8, y = 19 }, finish = { npc = "Hervdana Saegrund", area = 11, x = 65.6, y = 76.4 }, desc = "If there's one truth ye need to learn about water, it's this: water means rebirth. It carves stone, cleanses filth, and heals the weary -- but only when it's pure. Taint it, and it'll ruin all it touches.\n\nIf ye seek the water sapta, find Hervdana Saegrund in the Wetlands. Her family dwells in a cave beneath the southern falls.\n\nGo on then, don't let the river outrun ye." },
    { id = 94497, name = "Call of Water (2/8)", level = 22, minLevel = 20, requires = { 94495 }, faction = "Alliance", classes = 64, giver = "Hervdana Saegrund", start = { npc = "Hervdana Saegrund", area = 11, x = 65.6, y = 76.4 }, finish = { npc = "Hervdana Saegrund", area = 11, x = 65.6, y = 76.4 }, objective = "Fill the Empty Brown Waterskin at the bottom of the waterfalls below Hervdana's cave and return it to her in the Wetlands.", desc = "Ah, so ye've come seekin' the sapta, have ye? Well then, listen close, love. To find understandin' and earn the sapta, ye must seek water in its various forms. As ye gather the samples, keep yer eyes open. Watch the beasts that guard it, the land it nourishes, and how it changes lives.\n\nWe'll start simple: fill this skin at the base o' the falls, where the fresh meets the brackish. Go on now, and mind the marsh." },
    { id = 94499, name = "Call of Water (3/8)", level = 22, minLevel = 20, requires = { 94497 }, faction = "Alliance", classes = 64, giver = "Hervdana Saegrund", start = { npc = "Hervdana Saegrund", area = 11, x = 65.6, y = 76.4 }, finish = { npc = "Hervdana Saegrund", area = 11, x = 65.6, y = 76.4 }, objective = "Fill the Empty Red Waterskin at Stonewatch Falls near the Nightcrawler Murlocs and return to Hervdana Saegrund in the Wetlands.", desc = "Aye, Redridge drinks deep from Lake Everstill, but by the time the waters tumble down Stonewatch Falls, somethin' has seeped in. The murlocs down there are big, twisted brutes. Not like the ones ye find here or in the Loch. Lucky for the townsfolk they keep to the base o' the falls.\n\nBring a sampling to me. I've a mind to find out if it's magic, venom, or somethin' worse that's taintin' the waters near that old fort." },
    { id = 94500, name = "Call of Water (4/8)", level = 23, minLevel = 20, requires = { 94499 }, faction = "Alliance", classes = 64, giver = "Hervdana Saegrund", start = { npc = "Hervdana Saegrund", area = 11, x = 65.6, y = 76.4 }, finish = { npc = "Hervdana Saegrund", area = 11, x = 65.6, y = 76.4 }, objective = "Fill the Unfilled Blue Waterskin at the waters of Astranaar in Ashenvale and return to Hervdana Saegrund in the Wetlands.", desc = "Take this waterskin and journey deep into the emerald shade o' Ashenvale. Astranaar rests cradled by waters untouched by corruption. Ruins litter the bed o' the lake, hinting at a bygone era. Bring back a sample from the lake. Pure, ancient, and possibly enchanted water.\n\nIt's the last liquid I need before I send ye back to Norric.\n\nBoard the boat in Menethil to Auberdine, it stops in Southshore on the way over.\n\nAnd mind yerself... the forest's got eyes, and they don't blink." },
    { id = 94501, name = "Call of Water (5/8)", level = 23, minLevel = 20, requires = { 94500 }, faction = "Alliance", classes = 64, giver = "Hervdana Saegrund", start = { npc = "Hervdana Saegrund", area = 11, x = 65.6, y = 76.4 }, finish = { npc = "Norric Lochthane", area = 38, x = 41.8, y = 19 }, objective = "Bring the Vial of Purest Water to Norric Lochthane in Loch Modan.", desc = "Norric will have one more task for ye before rewarding ye with the water totem rites. The vial of water I've given ye is necessary for whatever that task is. Go now and find him. We shall meet again some day." },
    { id = 94502, name = "Call of Water (6/8)", level = 23, minLevel = 20, requires = { 94501 }, faction = "Alliance", classes = 64, giver = "Norric Lochthane", start = { npc = "Norric Lochthane", area = 38, x = 41.8, y = 19 }, objective = "Cleanse the corruption at Stendel's Pond in Westfall.\nReturn to Norric in Loch Modan when finished.", desc = "In Westfall, outside o' Moonbrook lies Stendel's Pond. Once a pure spring, now touched by dark forces. The spirits there 'ave gone silent.\n\nYe must face the corruption that fouls the waters. Take its bracers and the last drops o' Hervdana's potion, then place 'em on the shrine. That'll call forth a spirit, cleansed and true. Speak with it, learn what ye can.\n\nBring me proof the deed's done, and I'll grant ye the totem." },
    { id = 94503, name = "Call of Water (7/8)", level = 23, minLevel = 20, requires = { 94502 }, faction = "Alliance", classes = 64, finish = { npc = "Minor Manifestation of Water", area = 130, x = 38.6, y = 44.6 }, desc = "Light erupts as the final word leaves your lips. The hiss of water turning to mist fades into silence, and your senses reel as the corrupt spirits around you unravel, their essence scattered like ash in the wind." },
    { id = 94505, name = "Call of Water (8/8)", level = 23, minLevel = 20, requires = { 94503 }, faction = "Alliance", classes = 64, giver = "Minor Manifestation of Water", start = { npc = "Minor Manifestation of Water", area = 130, x = 38.6, y = 44.6 }, finish = { npc = "Norric Lochthane", area = 38, x = 41.8, y = 19 }, objective = "Bring the Shard of Water to Norric Lochthane in Loch Modan.", desc = "Take shard. Take shard and give life.\n\nGive life and understand. Understand water is life... corruption stops life.\n\nYou protect and give life with water's power." },
    { id = 94616, name = "Water Sapta", level = 20, minLevel = 20, faction = "Alliance", classes = 64, giver = "Norric Lochthane", start = { npc = "Norric Lochthane", area = 38, x = 41.8, y = 19 }, finish = { npc = "Norric Lochthane", area = 38, x = 41.8, y = 19 } },
    { id = 96243, name = "Call of Earth (1/4)", level = 10, minLevel = 10, faction = "Alliance", classes = 64, objective = "Find Teo Hammerstorm in Dun Morogh.", desc = "It's past time ye heeded the earth, brave Shaman. The elements already prickle in yer skin, but once ye speak with the stone, the ground itself'll set firm 'neath yer soles--and in yer soul.\n\nSeek out Teo Hammerstorm, in Coldridge Valley. Ye'll find him within Anvilmar, a holdfast forged by hammer, fire, and will." },
    { id = 97243, name = "Call of Fire", level = 10, minLevel = 10, faction = "Horde", giver = "Sessaria Skystride", start = { npc = "Sessaria Skystride", area = 16593, x = 58.2, y = 78.4 }, finish = { npc = "Olariaan Swiftburn", area = 16593, x = 51.2, y = 86 }, objective = "Bring the Torch of Dormant Flame to Olariaan Swiftburn at the Shrine of Flames in the Gustberry Lowlands.", desc = "Even though we are in the realm of skywall, this is still the elemental plane. The spirits of all four elements speak to us, if we deign to listen. One among us Windshapers is in particular attunement with the element of fire. A shen'dorei by the name of Olariaan Swiftburn.\n\nBring this to him at the Shrine of Flames in the Gustberry Lowlands. You'll find it tucked away along the edge of the island, west of Valanaar." },
    { id = 97244, name = "Call of Fire", level = 10, minLevel = 10, faction = "Horde", giver = "Olariaan Swiftburn", start = { npc = "Olariaan Swiftburn", area = 16593, x = 51.2, y = 86 }, finish = { npc = "Olariaan Swiftburn", area = 16593, x = 51.2, y = 86 }, steps = { { name = "Faladiel's Heart", area = 16593, x = 64.6, y = 63.9 } }, objective = "Slay Skypriest Faladiel in the Gustberry Lowlands and collect Faladiel's Heart.", desc = "There is an Al'Aketh Skypriest called Faladiel. He was once a caller of the flame and a stalwart Windshaper. Like so many Al'Aketh, he mortgaged his loyalty for power and his hands are now stained with the blood of  his former brothers and sisters.\n\nYou will find Skypriest Faladiel at the farm to the northeast past Valanaar, just to the south of the Shrine of Akir. Kill the betrayer. Bring me his heart. It is a gruesome task, but it is needed for the ritual we are to perform." },
    { id = 97245, name = "Call of Fire (1/2)", level = 10, minLevel = 10, faction = "Horde", giver = "Olariaan Swiftburn", start = { npc = "Olariaan Swiftburn", area = 16593, x = 51.2, y = 86 }, finish = { npc = "Olariaan Swiftburn", area = 16593, x = 51.2, y = 86 }, steps = { { name = "Kuramaa's Mask", area = 16593, x = 42.6, y = 69.3 } }, objective = "Find the home of Kuramaa in the Shen'dar Highlands, and defeat the spirit in combat. Bring Kuramaa's Mask to Olariaan Swiftburn in the Gustberry Lowlands when you are victorious.", desc = "The residents of the Shen'dar Highlands speak of an ancient forest sprite called Kuramaa. They say it lives inside of a twisted stump at the summit of a hill near the highlands Anchor Pylon.\n\nGo to the highlands and find this stump. Rap your fist upon the bark and Kuramaa will appear. Best the spirit in combat, and bring me its wooden mask.\n\nBe warned however, this entity will be exceptionally resistant to much of your magic. Only the touch of flame will lay low the spirit." },
    { id = 97257, name = "Call of Fire (2/2)", level = 10, minLevel = 10, requires = { 97245 }, faction = "Horde", giver = "Olariaan Swiftburn", start = { npc = "Olariaan Swiftburn", area = 16593, x = 51.2, y = 86 }, finish = { npc = "Sessaria Skystride", area = 16593, x = 58.2, y = 78.4 }, steps = { { name = "Brazier of Eternal Flame", area = 16593, x = 58.4, y = 78.8 } }, objective = "Wait for Olariaan to begin the ritual at the Brazier of Offering and follow his instructions.\n\nYou must deliver the Eternal Flame to Valanaar before the timer runs out.", desc = "Now we will perform the ritual.\n\nI will place the materials onto the altar and call forth the spirits of flame. If the offering is accepted, they will appear and light the Eternal Flame. You will then hold your torch forth and capture the flame.\n\nCarry the lit torch to Valanaar and place it in the Brazier of Eternal Flames. You must do so quickly, for the flames of the Firelands are quick to dissipate here in Skywall." },
    { id = 98517, name = "Call of Fire", level = 10, minLevel = 10, faction = "Horde", objective = "Report to Sessaria Skystride or Aarnor Galestrike on Zephras Isle to continue your training as a Shaman.\n\nYou can return to Zephras via the skycutter transport that docks in Mulgore at Skywatcher Plateau, northwest of Thunder Bluff.", desc = "Greetings, young Skyborne. The spirits have spoken of you, and tell me that you are ready to heed the call of fire. However, I shall not be the one to start you on that Path. Return to your home in the elemental plane, seek your mentors there. They will tell you what must be done." },
    { id = 98581, name = "Archaic Rune", level = 1, minLevel = 1, faction = "Alliance", classes = 64, giver = "Sten Stoutarm", start = { npc = "Sten Stoutarm", area = 1, x = 29.8, y = 71.2 }, finish = { npc = "Teo Hammerstorm", area = 1, x = 28.7, y = 66.1 }, objective = "Read the Archaic Rune and speak to Teo Hammerstorm in Anvilmar.", desc = "While you were helping me out, this rune was given to me to pass on to you. Take some time to read it when you have a chance. Based on the Wildhammer style to these inscriptions, I'm guessin' this came from the shaman trainer Teo Hammerstorm. Take a gander at it and go find him inside Anvilmar when you've a chance." },
})

ns.AddQuests("c_WARLOCK", {
    { id = 98575, name = "Tainted Tablet", level = 1, minLevel = 1, faction = "Horde", classes = 256, giver = "Gornek", start = { npc = "Gornek", area = 14, x = 42, y = 68.4 }, finish = { npc = "Nartok", area = 14, x = 40.6, y = 68.4 }, objective = "Read the Tainted Tablet and speak to Nartok inside the Den in the Valley of Trials.", desc = "Ah, while you were gone a tablet came for you, <name>.\n\nI usually avoid dealing with warlocks if I can help it, but I think you should read it when you have time. If I'm not mistaken, it came from your newly-appointed trainer, Nartok. He would have words with you when you're ready." },
})

ns.AddQuests("c_WARRIOR", {
    { id = 92479, name = "A Scribbled Letter", level = 1, minLevel = 1, faction = "Alliance", classes = 1, giver = "Marshal McBride", start = { npc = "Marshal McBride", area = 12, x = 48.8, y = 41.6 }, finish = { npc = "Tordrin Sternblade", area = 12, x = 51.2, y = 40.8 }, objective = "Read the Scribbled Letter and speak to Tordrin Stemblade in Northshire Abbey.", desc = "I was asked to bring this to your attention as soon as you returned from the kobold camps, <name>. It appears to be a letter sealed with the mark of Tordrin Stemblade, our local hunter trainer. Take a moment to read it before you go about any other business here in the Abbey." },
    { id = 92532, name = "The Warrior's Path", level = 2, minLevel = 2, classes = 1, giver = "Rorian the Dayseeker", start = { npc = "Rorian the Dayseeker", area = 16593, x = 42, y = 23.4 }, finish = { npc = "Blademaster Ren", area = 16593, x = 43.6, y = 24.2 }, objective = "Read the Crumpled Note you've been given, then seek out Blademaster Ren inside the Thendal Village watchtower.", desc = "While you were gone our warrior trainer--Blademaster Ren--requested that we send you their way when you returned. She dropped this note off for you as well.\n\nGive it a read, then find Blademaster Ren inside the village watchtower." },
    { id = 94003, name = "The Skybreaker Bulwark", level = 10, minLevel = 10, giver = "Seena Skybreaker", start = { npc = "Seena Skybreaker", area = 16593, x = 59.8, y = 72.8 }, finish = { npc = "Seena Skybreaker", area = 16593, x = 59.8, y = 72.8 }, steps = { { name = "Skybreaker Bulwark", area = 16593, x = 56.6, y = 50.4 } }, objective = "Reclaim the Skybreaker Bulwark from Zaal Stormshield at the Shrine of Akir.", desc = "I am all that remains of the line of Skybreakers here on Zephras Isle. The rest were murdered by the Al'Aketh.\n\nThe only thing that outweighs my sorrow is my shame. My family's ancestral shield--the Skybreaker Bulwark--is now in the hands of a cultist named Zaal Stormshield. Family lore holds no harm may befall a worthy wielder of this shield.\n\nZaal is not worthy, of that I am sure. Find this man at the Shrine of Akir and reclaim my shield from him. Do this and I will teach you the Skybreaker Defense." },
})

ns.AddQuests("p_356", {
    { id = 97065, name = "Tip the Scales - Keefer's Angelfish", level = 60, minLevel = 1 },
    { id = 97066, name = "Tip the Scales - Brownell's Blue Striped Racer", level = 60, minLevel = 1 },
    { id = 97067, name = "Tip the Scales - Dezian Queenfish", level = 60, minLevel = 1 },
})

ns.AddQuests("p_camping", {
    { id = 95998, name = "The Great Outdoors", level = 6, minLevel = 4, faction = "Alliance", giver = "Sam Sarsaparilla", start = { npc = "Sam Sarsaparilla", area = 12, x = 44.8, y = 63.2 }, finish = { npc = "Sam Sarsaparilla", area = 12, x = 44.8, y = 63.2 }, objective = "Sit near Sam's Basic Campfire by typing /sit in the chat window and wait until you receive the Boosted Rest buff.", desc = "Well howdy there, <class>. I can see you've got the look of an adventurer about you. Good for you. The world needs more of us restless souls, seeking fortune and glory.\n\nIt's a big wide world out there and you'll need to learn to thrive in the wilds to be successful. Not sure how your outdoorsman skills are but I reckon I could teach you a thing or two, if you'd be apt to learn.\n\nHave a seat near the fire, get comfy. I'll walk you through it." },
    { id = 96031, name = "Camping 101: Leatherworking", level = 6, minLevel = 4, faction = "Alliance", giver = "Eric Brighthammer", start = { npc = "Eric Brighthammer", area = 1, x = 46.6, y = 53.8 }, finish = { npc = "Gretta Finespindle", area = 1537, x = 39, y = 32.8 }, objective = "Speak with Gretta Finespindle in Ironforge to learn to craft a camping item for your profession once you have shown proficiency in your skill.", desc = "You've become a leatherworker. Good for you, <class>. I reckon I know someone that can teach you how to make yourself a tent that will keep you cool on hot days, and dry on rainy days.\n\nWith a good tent over your head, you'll ensure that you get all the rest you need to stay sharp on your travels." },
    { id = 96044, name = "Camping 101: Blacksmithing", level = 6, minLevel = 4, faction = "Alliance", giver = "Eric Brighthammer", start = { npc = "Eric Brighthammer", area = 1, x = 46.6, y = 53.8 }, finish = { npc = "Tognus Flintfire", area = 1, x = 45.2, y = 52 }, objective = "Speak with Tognus Flintfire in Kharanos to learn to craft a camping item for your profession once you have shown proficiency in your skill.", desc = "So, you've become a Blacksmith. That's a great choice if you want to make sure your blades never dull.\n\nI reckon I know someone that can help with that by teaching you how to craft a Sharpening Wheel. Bring one of these out at your camp and all the warriors and rogues in the area will be lining up to hone their weapons." },
    { id = 96045, name = "Camping 101: Alchemy", level = 6, minLevel = 4, faction = "Alliance", giver = "Vosur Brakthel", start = { npc = "Vosur Brakthel", area = 1537, x = 66.4, y = 55.2 }, finish = { npc = "Vosur Brakthel", area = 1537, x = 66.4, y = 55.2 }, objective = "Speak with Vosur Brakthel in Ironforge to learn to craft a camping item for your profession once you have shown proficiency in your skill.", desc = "Now that you've taken up Alchemy, I can also teach you how to craft a Mana Well for your camp once you've learned a bit. Build one of these and all of the healers and spellcaster types will come running to get a refreshing taste." },
    { id = 96046, name = "Camping 101: Mining", level = 6, minLevel = 4, faction = "Alliance", giver = "Eric Brighthammer", start = { npc = "Eric Brighthammer", area = 1, x = 46.6, y = 53.8 }, finish = { npc = "Yarr Hammerstone", area = 1, x = 50, y = 50.4 }, objective = "Speak with Yarr Hammerstone in Kharanos to learn to craft a camping item for your profession once you have shown proficiency in your skill.", desc = "Mining isn't the most glamorous, but it's good honest work and a fine profession for you to explore.\n\nI reckon I know someone that can teach you how to craft a Lodestone for your camp. Build one of these and everyone who wants to swing a sword will be eager to gather round your fire and soak up the extra \"oomph\" it can provide to increase their combat prowess." },
    { id = 96047, name = "Camping 101: First Aid", level = 6, minLevel = 4, faction = "Alliance", giver = "Eric Brighthammer", start = { npc = "Eric Brighthammer", area = 1, x = 46.6, y = 53.8 }, finish = { npc = "Thamner Pol", area = 1, x = 47.2, y = 52.6 }, objective = "Speak with Thamner Pol in Kharanos to learn to craft a camping item for your profession once you have shown proficiency in your skill.", desc = "So you've taken up First Aid? That's an honorable... and pragmatic pursuit as a <class>.\n\nI reckon I know someone that can teach you how to craft a First Aid Kit for your camp. Injuries are a reality in the world of adventuring and offering some much-needed healing at your camp could even save lives." },
    { id = 96050, name = "Camping 101: Fishing", level = 6, minLevel = 4, faction = "Alliance", giver = "Eric Brighthammer", start = { npc = "Eric Brighthammer", area = 1, x = 46.6, y = 53.8 }, finish = { npc = "Paxton Ganter", area = 1, x = 35.4, y = 40.2 }, objective = "Speak with Paxton Ganter near Iceflow Lake in Dun Morogh to learn to craft a camping item for your profession once you have shown proficiency in your skill.", desc = "You might not think so, but your skill as a fisherman can actually come in handy at camp.\n\nI reckon I know someone that can teach you how to craft a Fish Bowl for your camp. You can use this fixture to help provide a bit of joy to yourself and your fellow adventurers. A happy adventurer is a strong adventurer and I'm sure your combat capabilities will reflect that." },
    { id = 96055, name = "Camping 101: Herbalism", level = 6, minLevel = 4, faction = "Alliance", giver = "Eric Brighthammer", start = { npc = "Eric Brighthammer", area = 1, x = 46.6, y = 53.8 }, finish = { npc = "Reyna Stonebranch", area = 1537, x = 55.6, y = 58.8 }, objective = "Speak with Reyna Stonebranch in Ironforge to learn to craft a camping item for your profession once you have shown proficiency in your skill.", desc = "Looks to me like you've gained some skill in herbalism. Picking flowers isn't just for dilly-dallying, you know. It can be useful... and profitable.\n\nI reckon I know someone that can teach you how to craft an Incense Candle for your camp. High spirits are a key component to keeping healers and spellcasters in the fight, and an Incense Candle can provide a boost that magic users will surely appreciate." },
    { id = 96056, name = "Camping 101: Skinning", level = 6, minLevel = 4, faction = "Alliance", giver = "Eric Brighthammer", start = { npc = "Eric Brighthammer", area = 1, x = 46.6, y = 53.8 }, finish = { npc = "Balthus Stoneflayer", area = 1537, x = 39.6, y = 32.4 }, objective = "Speak with Balthus Stoneflayer in Ironforge to learn to craft a camping item for your profession once you have shown proficiency in your skill.", desc = "Being able to skillfully harvest the skins and hides of fallen beasts is one of the more valuable skills an adventurer can possess.\n\nI reckon I know someone that can teach you how to craft a Camp Chair for your camp. Sometimes it's important to just take a load off, and you can use some of those hides you've gathered to make a comfy chair to sit in. A bit of relaxation can help ensure that you are at your peak condition and can strike where it counts the next time you find yourself in a dust-up." },
    { id = 96057, name = "Camping 101: Tailoring", level = 6, minLevel = 4, faction = "Alliance", giver = "Eric Brighthammer", start = { npc = "Eric Brighthammer", area = 1, x = 46.6, y = 53.8 }, finish = { npc = "Uthrar Threx", area = 1537, x = 43.6, y = 28.2 }, objective = "Speak with Uthrar Threx in Ironforge to learn to craft a camping item for your profession once you have shown proficiency in your skill.", desc = "Tailoring is a surprisingly potent tradeskill to invest in, and I'm sure it'll serve you well.\n\nI know someone that can teach you how to craft a Faction Banner for your camp, provided you have the skill for it. Inspiration and morale are a key part of success on any battlefield, and an inspirational banner can go a long way to keeping you energized." },
    { id = 96058, name = "Camping 101: Engineering", level = 6, minLevel = 4, faction = "Alliance", giver = "Eric Brighthammer", start = { npc = "Eric Brighthammer", area = 1, x = 46.6, y = 53.8 }, finish = { npc = "Bronk Guzzlegear", area = 1, x = 50.2, y = 50.4 }, objective = "Speak with Bronk Guzzlegear in Kharanos to learn to craft a camping item for your profession once you have shown proficiency in your skill.", desc = "Engineers like yourself can cook up all sorts of bits, bots, and bombs for fun and profit.\n\nI reckon I know someone that can teach you how to craft a Reagent Bot for your camp. This helpful automaton can help keep you well-supplied so that you and your allies never run out of the materials needed to fuel your spells." },
    { id = 96059, name = "Camping 101: Enchanting", level = 6, minLevel = 4, faction = "Alliance", giver = "Thonys Pillarstone", start = { npc = "Thonys Pillarstone", area = 1537, x = 60.4, y = 45 }, finish = { npc = "Thonys Pillarstone", area = 1537, x = 60.4, y = 45 }, objective = "Speak with Thonys Pillarstone in Ironforge to learn to craft a camping item for your profession once you have shown proficiency in your skill.", desc = "Now that you've begun your journey into being an enchanter, I reckon I can teach you how to craft an Enchanted Lute for your camp once you've learned the ropes.\n\nIt's so important to find entertainment during your downtime, and this bit of magic can help ensure you are ready to weather all sorts of challenges when you hit the old dusty trail once again." },
    { id = 96101, name = "The Great Outdoors", level = 6, minLevel = 4, requires = { 96638 }, giver = "Raan Wildwind", start = { npc = "Raan Wildwind", area = 16593, x = 41.6, y = 44.8 }, finish = { npc = "Raan Wildwind", area = 16593, x = 41.6, y = 44.8 }, objective = "Sit near Raan's Basic Campfire by typing /sit in the chat window and wait until you receive the Boosted Rest buff.", desc = "Greetings, <class>. I can see you've got the look of an adventurer about you. This is good. The world needs more of us restless souls, seeking fortune and glory.\n\nYou'll need to learn to thrive in the wilds to be successful in this line of work. Not sure how your outdoor skills are but I can probably teach you a thing or two, if you'd be apt to learn.\n\nHave a seat near the fire and get comfortable. I'll walk you through it." },
    { id = 96102, name = "Camping 101: Tailoring", level = 6, minLevel = 4, faction = "Horde", giver = "Brakk", start = { npc = "Brakk", area = 14, x = 52, y = 47.4 }, finish = { npc = "Snang", area = 1637, x = 62.8, y = 49.4 }, objective = "Speak with Snang in Orgrimmar to learn to craft a camping item for your profession once you have shown proficiency in your skill.", desc = "Tailoring is a surprisingly potent tradeskill to invest in, and I'm sure it'll serve you well.\n\nI know someone that can teach you how to craft a Faction Banner for your camp, provided you have the skill for it. Inspiration and morale are a key part of success on any battlefield, and an inspirational banner can go a long way to keeping you energized." },
    { id = 96604, name = "The Great Outdoors", level = 6, minLevel = 4, faction = "Horde", giver = "Brakk", start = { npc = "Brakk", area = 14, x = 52, y = 47.4 }, finish = { npc = "Brakk", area = 14, x = 52, y = 47.4 }, objective = "Sit near Brakk's Basic Campfire by typing /sit in the chat window and wait until you receive the Boosted Rest buff.", desc = "Greetings, <class>. I can see you've got the look of an adventurer about you. This is good. The world needs more of us restless souls, seeking fortune and glory.\n\nYou'll need to learn to thrive in the wilds to be successful in this line of work. Not sure how your outdoor skills are but I can probably teach you a thing or two, if you'd be apt to learn.\n\nHave a seat near the fire and get comfortable. I'll walk you through it." },
    { id = 96605, name = "The Great Outdoors", level = 6, minLevel = 4, faction = "Horde", giver = "Kaga Wildhoof", start = { npc = "Kaga Wildhoof", area = 215, x = 45.6, y = 69.3 }, finish = { npc = "Kaga Wildhoof", area = 215, x = 45.6, y = 69.3 }, objective = "Sit near Kaga's Basic Campfire by typing /sit in the chat window and wait until you receive the Boosted Rest buff.", desc = "Greetings, <class>. I can see you've got the look of an adventurer about you. This is good. The world needs more of us restless souls, seeking fortune and glory.\n\nYou'll need to learn to thrive in the wilds to be successful in this line of work. Not sure how your outdoor skills are but I can probably teach you a thing or two, if you'd be apt to learn.\n\nHave a seat near the fire and get comfortable. I'll walk you through it." },
    { id = 96606, name = "The Great Outdoors", level = 6, minLevel = 4, faction = "Alliance", giver = "Lyreena Duskblade", start = { npc = "Lyreena Duskblade", area = 141, x = 57.6, y = 56.6 }, finish = { npc = "Lyreena Duskblade", area = 141, x = 57.6, y = 56.6 }, objective = "Sit near Lyreena's Basic Campfire by typing /sit in the chat window and wait until you receive the Boosted Rest buff.", desc = "Greetings, <class>. I can see you've got the look of an adventurer about you. This is good. The world needs more of us restless souls, seeking fortune and glory.\n\nYou'll need to learn to thrive in the wilds to be successful in this line of work. Not sure how your outdoor skills are but I can probably teach you a thing or two, if you'd be apt to learn.\n\nHave a seat near the fire and get comfortable. I'll walk you through it." },
    { id = 96607, name = "The Great Outdoors", level = 6, minLevel = 4, faction = "Horde", giver = "Eleanor Shackleton", start = { npc = "Eleanor Shackleton", area = 85, x = 57.2, y = 55.4 }, finish = { npc = "Eleanor Shackleton", area = 85, x = 57.2, y = 55.4 }, objective = "Sit near Eleanor's Basic Campfire by typing /sit in the chat window and wait until you receive the Boosted Rest buff.", desc = "Greetings, <class>. I can see you've got the look of an adventurer about you. This is good. The world needs more of us restless souls, seeking fortune and glory.\n\nYou'll need to learn to thrive in the wilds to be successful in this line of work. Not sure how your outdoor skills are but I can probably teach you a thing or two, if you'd be apt to learn.\n\nHave a seat near the fire and get comfortable. I'll walk you through it." },
    { id = 96608, name = "The Great Outdoors", level = 6, minLevel = 4, faction = "Alliance", giver = "Eric Brighthammer", start = { npc = "Eric Brighthammer", area = 1, x = 46.6, y = 53.8 }, finish = { npc = "Eric Brighthammer", area = 1, x = 46.6, y = 53.8 }, objective = "Sit near Eric's Basic Campfire by typing /sit in the chat window and wait until you receive the Boosted Rest buff.", desc = "Greetings, <class>. I can see you've got the look of an adventurer about you. This is good. The world needs more of us restless souls, seeking fortune and glory.\n\nYou'll need to learn to thrive in the wilds to be successful in this line of work. Not sure how your outdoor skills are but I can probably teach you a thing or two, if you'd be apt to learn.\n\nHave a seat near the fire and get comfortable. I'll walk you through it." },
    { id = 96626, name = "Camping 101: Cooking", level = 6, minLevel = 4, faction = "Alliance", giver = "Sam Sarsaparilla", start = { npc = "Sam Sarsaparilla", area = 12, x = 44.8, y = 63.2 }, finish = { npc = "Tomas", area = 12, x = 44.2, y = 66 }, objective = "Speak with Tomas in Goldshire to learn to become a cook.", desc = "So you want to learn more about camping, huh? Good for you, <class>. The first step any adventurer needs to take is to become a cook and learn how to make a campfire.\n\nCooking's not just about making tasty foods. It's also the foundation for your camp." },
    { id = 96627, name = "The Adventurer", level = 6, minLevel = 4, faction = "Alliance", giver = "Marshal McBride", start = { npc = "Marshal McBride", area = 12, x = 48.8, y = 41.6 }, finish = { npc = "Sam Sarsaparilla", area = 12, x = 44.8, y = 63.2 }, desc = "<name>, you have proven your competence as a protector thus far. That is why I am now entrusting you with an unusual task.\n\nI've heard of a new adventurer down the road by Goldshire. Go and see what he's doing." },
    { id = 96628, name = "The Adventurer", level = 6, minLevel = 4, faction = "Alliance", giver = "Mountaineer Thalos", start = { npc = "Mountaineer Thalos", area = 1, x = 33.4, y = 71.8 }, finish = { npc = "Eric Brighthammer", area = 1, x = 46.6, y = 53.8 }, objective = "Deliver the Supply Bundle to Eric Brighthammer near Kharanos.", desc = "Wait, <name>. I have another ask of you, before you brave that tunnel.\n\nMy mountaineers have reported an adventurer that's shown up just outside of Kharanos. Could you deliver these supplies to him?" },
    { id = 96629, name = "Camping 101: Cooking", level = 6, minLevel = 4, faction = "Alliance", giver = "Eric Brighthammer", start = { npc = "Eric Brighthammer", area = 1, x = 46.6, y = 53.8 }, finish = { npc = "Gremlock Pilsnor", area = 1, x = 47.6, y = 52.4 }, objective = "Speak with Gremlock Pilsnor in Kharanos to learn to become a cook.", desc = "So you want to learn more about camping, huh? Good for you, <class>. The first step any adventurer needs to take is to become a cook and learn how to make a campfire.\n\nCooking's not just about making tasty foods. It's also the foundation for your camp." },
    { id = 96630, name = "The Adventurer", level = 6, minLevel = 4, faction = "Alliance", finish = { npc = "Lyreena Duskblade", area = 141, x = 57.6, y = 56.6 }, objective = "Bring the journal to Lyreena Duskblade near Dolanaar.", desc = "<The journal appears to be quite plain, detailing the life and adventures of someone you've never heard of.\n\nThere are multiple entries mentioning camping. It seems to be quite... fun.>" },
    { id = 96634, name = "Camping 101: Cooking", level = 6, minLevel = 4, faction = "Alliance", giver = "Lyreena Duskblade", start = { npc = "Lyreena Duskblade", area = 141, x = 57.6, y = 56.6 }, finish = { npc = "Zarrin", area = 141, x = 57, y = 61.2 }, objective = "Speak with Zarrin in Dolanaar to learn to become a cook.", desc = "So you want to learn more about camping, huh? Good for you, <class>. The first step any adventurer needs to take is to become a cook and learn how to make a campfire.\n\nCooking's not just about making tasty foods. It's also the foundation for your camp." },
    { id = 96638, name = "The Adventurer", level = 6, minLevel = 4, giver = "Aetheen of the Gales", start = { npc = "Aetheen of the Gales", area = 16593, x = 42.6, y = 23.6 }, finish = { npc = "Raan Wildwind", area = 16593, x = 41.6, y = 44.8 }, desc = "More and more adventurers like yourself have been seeking glory and fortune outside of the safety of Thendal Grove. There's one such adventurer who has made a camp outside of Shen'dar Village, along the road leading southwest out of Thendal Grove.\n\nSeek him out and see what you can learn from him that may help you in your own travels." },
    { id = 96646, name = "Camping 101: Cooking", level = 6, minLevel = 4, giver = "Raan Wildwind", start = { npc = "Raan Wildwind", area = 16593, x = 41.6, y = 44.8 }, finish = { npc = "Zerril Softbreeze", area = 16593, x = 43.8, y = 43.8 }, objective = "Speak with Zerril Softbreeze in Shen'dar Village to learn to become a cook.", desc = "So you want to learn more about camping, huh? Good for you, <class>. The first step any adventurer needs to take is to become a cook and learn how to make a campfire.\n\nCooking's not just about making tasty foods. It's also the foundation for your camp." },
    { id = 96652, name = "The Adventurer", level = 6, minLevel = 4, faction = "Horde", finish = { npc = "Brakk", area = 14, x = 52, y = 47.4 }, objective = "Bring the journal to Brakk near Razor Hill.", desc = "<The journal appears to be quite plain, detailing the life and adventures of someone you've never heard of.\n\nThere are multiple entries mentioning camping. It seems to be quite... fun.>" },
    { id = 96655, name = "Camping 101: Cooking", level = 6, minLevel = 4, faction = "Horde", giver = "Brakk", start = { npc = "Brakk", area = 14, x = 52, y = 47.4 }, finish = { npc = "Cook Torka", area = 14, x = 51.2, y = 42.4 }, objective = "Speak with Cook Torka in Razor Hill to learn to become a cook.", desc = "So you want to learn more about camping, huh? Good for you, <class>. The first step any adventurer needs to take is to become a cook and learn how to make a campfire.\n\nCooking's not just about making tasty foods. It's also the foundation for your camp." },
    { id = 96656, name = "The Adventurer", level = 6, minLevel = 4, faction = "Horde", giver = "Executor Arren", start = { npc = "Executor Arren", area = 85, x = 32, y = 66 }, finish = { npc = "Eleanor Shackleton", area = 85, x = 57.2, y = 55.4 }, desc = "<name>, you have proven yourself trustworthy in your endeavors against the Scarlet Crusade so far. That is why I am now entrusting you with an unusual task.\n\nI've heard of a new adventurer down the road by Brill. Go and see what she's doing." },
    { id = 96658, name = "Camping 101: Cooking", level = 6, minLevel = 4, faction = "Horde", giver = "Eleanor Shackleton", start = { npc = "Eleanor Shackleton", area = 85, x = 57.2, y = 55.4 }, finish = { npc = "William Pickman", area = 85, x = 61.8, y = 51.4 }, objective = "Speak with William Pickman in Brill to learn to become a cook.", desc = "So you want to learn more about camping, huh? Good for you, <class>. The first step any adventurer needs to take is to become a cook and learn how to make a campfire.\n\nCooking's not just about making tasty foods. It's also the foundation for your camp." },
    { id = 96659, name = "The Adventurer", level = 6, minLevel = 4, faction = "Horde", giver = "Chief Hawkwind", start = { npc = "Chief Hawkwind", area = 215, x = 43.9, y = 76.6 }, finish = { npc = "Kaga Wildhoof", area = 215, x = 45.6, y = 69.3 }, objective = "Deliver the Supply Bundle to Kaga Wildhoof near Bloodhoof Village.", desc = "Wait, <name>. I have another ask of you, before you leave us.\n\nThere is an adventurer by the name of Kaga Wildhoof who has made camp just outside of Bloodhoof Village. She has greatly helped me in the past, and now I see my chance to repay her. Could you deliver these supplies to her?" },
    { id = 96661, name = "Camping 101: Cooking", level = 6, minLevel = 4, faction = "Horde", giver = "Kaga Wildhoof", start = { npc = "Kaga Wildhoof", area = 215, x = 45.6, y = 69.3 }, finish = { npc = "Pyall Silentstride", area = 215, x = 44.9, y = 61.6 }, objective = "Speak with Pyall Silentstride in Bloodhoof Village to learn to become a cook.", desc = "So you want to learn more about camping, huh? Good for you, <class>. The first step any adventurer needs to take is to become a cook and learn how to make a campfire.\n\nCooking's not just about making tasty foods. It's also the foundation for your camp." },
    { id = 97899, name = "Camping 101: Alchemy", level = 6, minLevel = 4, faction = "Horde", giver = "Brakk", start = { npc = "Brakk", area = 14, x = 52, y = 47.4 }, finish = { npc = "Whuut", area = 1637, x = 55.8, y = 33.2 }, objective = "Speak with Whuut in Orgrimmar to learn to craft a camping item for your profession once you have shown proficiency in your skill.", desc = "So, you chose to cook up brews and potions as an Alchemist. I'm sure that'll come in handy in your travels.\n\nI reckon I know someone that can teach you how to craft a Mana Well for your camp. Build one of these and all of the healers and spellcaster types will come running to get a refreshing taste." },
    { id = 97900, name = "Camping 101: Blacksmithing", level = 6, minLevel = 4, faction = "Horde", giver = "Brakk", start = { npc = "Brakk", area = 14, x = 52, y = 47.4 }, finish = { npc = "Dwukk", area = 14, x = 52, y = 40.6 }, objective = "Speak with Dwukk in Razor Hill to learn to craft a camping item for your profession once you have shown proficiency in your skill.", desc = "So, you've become a Blacksmith. That's a great choice if you want to make sure your blades never dull.\n\nI reckon I know someone that can help with that by teaching you how to craft a Sharpening Wheel. Bring one of these out at your camp and all the warriors and rogues in the area will be lining up to hone their weapons." },
    { id = 97901, name = "Camping 101: Enchanting", level = 6, minLevel = 4, faction = "Horde", giver = "Brakk", start = { npc = "Brakk", area = 14, x = 52, y = 47.4 }, finish = { npc = "Jhag", area = 1637, x = 53.6, y = 38.2 }, objective = "Speak with Jhag in Orgrimmar to learn to craft a camping item for your profession once you have shown proficiency in your skill.", desc = "Enchanters make everything better and are always welcome at any camp out in the wilds.\n\nI reckon I know someone that can teach you how to craft an Enchanted Lute for your camp. It's so important to find entertainment during your downtime, and this bit of magic can help ensure you are ready to weather all sorts of challenges when you hit the old dusty trail once again." },
    { id = 97902, name = "Camping 101: Engineering", level = 6, minLevel = 4, faction = "Horde", giver = "Brakk", start = { npc = "Brakk", area = 14, x = 52, y = 47.4 }, finish = { npc = "Mukdrak", area = 14, x = 52.2, y = 40.8 }, objective = "Speak with Mukdrak in Razor Hill to learn to craft a camping item for your profession once you have shown proficiency in your skill.", desc = "Engineers like yourself can cook up all sorts of bits, bots, and bombs for fun and profit.\n\nI reckon I know someone that can teach you how to craft a Reagent Bot for your camp. This helpful automaton can help keep you well-supplied so that you and your allies never run out of the materials needed to fuel your spells." },
    { id = 97903, name = "Camping 101: First Aid", level = 6, minLevel = 4, faction = "Horde", giver = "Brakk", start = { npc = "Brakk", area = 14, x = 52, y = 47.4 }, finish = { npc = "Rawrk", area = 14, x = 54, y = 42 }, objective = "Speak with Rawrk in Razor Hill to learn to craft a camping item for your profession once you have shown proficiency in your skill.", desc = "So you've taken up First Aid? That's an honorable... and pragmatic pursuit as a <class>.\n\nI reckon I know someone that can teach you how to craft a First Aid Kit for your camp. Injuries are a reality in the world of adventuring and offering some much-needed healing at your camp could even save lives." },
    { id = 97904, name = "Camping 101: Fishing", level = 6, minLevel = 4, faction = "Horde", giver = "Brakk", start = { npc = "Brakk", area = 14, x = 52, y = 47.4 }, finish = { npc = "Lau'Tiki", area = 14, x = 53.2, y = 81.4 }, objective = "Speak with Lau'Tiki near Sen'jin Village to learn to craft a camping item for your profession once you have shown proficiency in your skill.", desc = "You might not think so, but your skill as a fisherman can actually come in handy at camp.\n\nI reckon I know someone that can teach you how to craft a Fish Bowl for your camp. You can use this fixture to help provide a bit of joy to yourself and your fellow adventurers. A happy adventurer is a strong adventurer and I'm sure your combat capabilities will reflect that." },
    { id = 97905, name = "Camping 101: Herbalism", level = 6, minLevel = 4, faction = "Horde", giver = "Brakk", start = { npc = "Brakk", area = 14, x = 52, y = 47.4 }, finish = { npc = "Jandi", area = 1637, x = 55.4, y = 39.6 }, objective = "Speak with Jandi in Orgrimmar to learn to craft a camping item for your profession once you have shown proficiency in your skill.", desc = "Looks to me like you've gained some skill in herbalism. Picking flowers isn't just for dilly-dallying, you know. It can be useful... and profitable.\n\nI reckon I know someone that can teach you how to craft an Incense Candle for your camp. High spirits are a key component to keeping healers and spellcasters in the fight, and an Incense Candle can provide a boost that magic users will surely appreciate." },
    { id = 97906, name = "Camping 101: Leatherworking", level = 6, minLevel = 4, faction = "Horde", giver = "Brakk", start = { npc = "Brakk", area = 14, x = 52, y = 47.4 }, finish = { npc = "Karolek", area = 1637, x = 62.8, y = 44.4 }, objective = "Speak with Karolek in Orgrimmar to learn to craft a camping item for your profession once you have shown proficiency in your skill.", desc = "You've become a leatherworker. Good for you, <class>. I reckon I know someone that can teach you how to make yourself a tent that will keep you cool on hot days, and dry on rainy days.\n\nWith a good tent over your head, you'll ensure that you get all the rest you need to stay sharp on your travels." },
    { id = 97907, name = "Camping 101: Mining", level = 6, minLevel = 4, faction = "Horde", giver = "Brakk", start = { npc = "Brakk", area = 14, x = 52, y = 47.4 }, finish = { npc = "Krunn", area = 14, x = 51.8, y = 40.8 }, objective = "Speak with Krunn in Razor Hill to learn to craft a camping item for your profession once you have shown proficiency in your skill.", desc = "Mining isn't the most glamorous, but it's good honest work and a fine profession for you to explore.\n\nI reckon I know someone that can teach you how to craft a Lodestone for your camp. Build one of these and everyone who wants to swing a sword will be eager to gather round your fire and soak up the extra \"oomph\" it can provide to increase their combat prowess." },
    { id = 97908, name = "Camping 101: Skinning", level = 6, minLevel = 4, faction = "Horde", giver = "Brakk", start = { npc = "Brakk", area = 14, x = 52, y = 47.4 }, finish = { npc = "Thuwd", area = 1637, x = 63.2, y = 45.2 }, objective = "Speak with Thuwd in Orgrimmar to learn to craft a camping item for your profession once you have shown proficiency in your skill.", desc = "Being able to skillfully harvest the skins and hides of fallen beasts is one of the more valuable skills an adventurer can possess.\n\nI reckon I know someone that can teach you how to craft a Camp Chair for your camp. Sometimes it's important to just take a load off, and you can use some of those hides you've gathered to make a comfy chair to sit in. A bit of relaxation can help ensure that you are at your peak condition and can strike where it counts the next time you find yourself in a dust-up." },
    { id = 97915, name = "Camping 101: Alchemy", level = 6, minLevel = 4, faction = "Alliance", giver = "Sam Sarsaparilla", start = { npc = "Sam Sarsaparilla", area = 12, x = 44.8, y = 63.2 }, finish = { npc = "Alchemist Mallory", area = 12, x = 39.8, y = 48.4 }, objective = "Speak with Alchemist Mallory in Elwynn Forest near Stormwind to learn to craft a camping item for your profession once you have shown proficiency in your skill.", desc = "So, you chose to cook up brews and potions as an Alchemist. I'm sure that'll come in handy in your travels.\n\nI reckon I know someone that can teach you how to craft a Mana Well for your camp. Build one of these and all of the healers and spellcaster types will come running to get a refreshing taste." },
    { id = 97916, name = "Camping 101: Blacksmithing", level = 6, minLevel = 4, faction = "Alliance", giver = "Sam Sarsaparilla", start = { npc = "Sam Sarsaparilla", area = 12, x = 44.8, y = 63.2 }, finish = { npc = "Smith Argus", area = 12, x = 41.6, y = 65.6 }, objective = "Speak with Smith Argus in Goldshire to learn to craft a camping item for your profession once you have shown proficiency in your skill.", desc = "So, you've become a Blacksmith. That's a great choice if you want to make sure your blades never dull.\n\nI reckon I know someone that can help with that by teaching you how to craft a Sharpening Wheel. Bring one of these out at your camp and all the warriors and rogues in the area will be lining up to hone their weapons." },
    { id = 97917, name = "Camping 101: Enchanting", level = 6, minLevel = 4, faction = "Alliance", giver = "Sam Sarsaparilla", start = { npc = "Sam Sarsaparilla", area = 12, x = 44.8, y = 63.2 }, finish = { npc = "Betty Quin", area = 1519, x = 53.1, y = 73.8 }, objective = "Speak with Betty Quin in Stormwind to learn to craft a camping item for your profession once you have shown proficiency in your skill.", desc = "Enchanters make everything better and are always welcome at any camp out in the wilds.\n\nI reckon I know someone that can teach you how to craft an Enchanted Lute for your camp. It's so important to find entertainment during your downtime, and this bit of magic can help ensure you are ready to weather all sorts of challenges when you hit the old dusty trail once again." },
