    { id = 97920, name = "Camping 101: Fishing", level = 6, minLevel = 4, faction = "Alliance", giver = "Sam Sarsaparilla", start = { npc = "Sam Sarsaparilla", area = 12, x = 44.8, y = 63.2 }, finish = { npc = "Lee Brown", area = 12, x = 47.4, y = 62.2 }, objective = "Speak with Lee Brown near Goldshire to learn to craft a camping item for your profession once you have shown proficiency in your skill.", desc = "You might not think so, but your skill as a fisherman can actually come in handy at camp.\n\nI reckon I know someone that can teach you how to craft a Fish Bowl for your camp. You can use this fixture to help provide a bit of joy to yourself and your fellow adventurers. A happy adventurer is a strong adventurer and I'm sure your combat capabilities will reflect that." },
    { id = 97921, name = "Camping 101: Herbalism", level = 6, minLevel = 4, faction = "Alliance", giver = "Sam Sarsaparilla", start = { npc = "Sam Sarsaparilla", area = 12, x = 44.8, y = 63.2 }, finish = { npc = "Herbalist Pomeroy", area = 12, x = 39.8, y = 48.4 }, objective = "Speak with Herbalist Pomeroy in Elwynn Forest to learn to craft a camping item for your profession once you have shown proficiency in your skill.", desc = "Looks to me like you've gained some skill in herbalism. Picking flowers isn't just for dilly-dallying, you know. It can be useful... and profitable.\n\nI reckon I know someone that can teach you how to craft an Incense Candle for your camp. High spirits are a key component to keeping healers and spellcasters in the fight, and an Incense Candle can provide a boost that magic users will surely appreciate." },
