    { id = 97923, name = "Camping 101: Mining", level = 6, minLevel = 4, faction = "Alliance", giver = "Sam Sarsaparilla", start = { npc = "Sam Sarsaparilla", area = 12, x = 44.8, y = 63.2 }, finish = { npc = "Gelman Stonehand", area = 1519, x = 59.1, y = 37.7 }, objective = "Speak with Gelman Stonehand in Stormwind to learn to craft a camping item for your profession once you have shown proficiency in your skill.", desc = "Mining isn't the most glamorous, but it's good honest work and a fine profession for you to explore.\n\nI reckon I know someone that can teach you how to craft a Lodestone for your camp. Build one of these and everyone who wants to swing a sword will be eager to gather round your fire and soak up the extra \"oomph\" it can provide to increase their combat prowess." },
    { id = 97924, name = "Camping 101: Skinning", level = 6, minLevel = 4, faction = "Alliance", giver = "Sam Sarsaparilla", start = { npc = "Sam Sarsaparilla", area = 12, x = 44.8, y = 63.2 }, finish = { npc = "Helene Peltskinner", area = 12, x = 46.2, y = 62.2 }, objective = "Speak with Helene Peltskinner in Goldshire to learn to craft a camping item for your profession once you have shown proficiency in your skill.", desc = "Being able to skillfully harvest the skins and hides of fallen beasts is one of the more valuable skills an adventurer can possess.\n\nI reckon I know someone that can teach you how to craft a Camp Chair for your camp. Sometimes it's important to just take a load off, and you can use some of those hides you've gathered to make a comfy chair to sit in. A bit of relaxation can help ensure that you are at your peak condition and can strike where it counts the next time you find yourself in a dust-up." },
    { id = 97925, name = "Camping 101: Tailoring", level = 6, minLevel = 4, faction = "Alliance", giver = "Sam Sarsaparilla", start = { npc = "Sam Sarsaparilla", area = 12, x = 44.8, y = 63.2 }, finish = { npc = "Eldrin", area = 12, x = 79.2, y = 69 }, objective = "Speak with Eldrin in the Eastvale Logging Camp in Elwynn Forest to learn to craft a camping item for your profession once you have shown proficiency in your skill.", desc = "Tailoring is a surprisingly potent tradeskill to invest in, and I'm sure it'll serve you well.\n\nI know someone that can teach you how to craft a Faction Banner for your camp, provided you have the skill for it. Inspiration and morale are a key part of success on any battlefield, and an inspirational banner can go a long way to keeping you energized." },
    { id = 97927, name = "Camping 101: Alchemy", level = 6, minLevel = 4, faction = "Horde", giver = "Kaga Wildhoof", start = { npc = "Kaga Wildhoof", area = 215, x = 45.6, y = 69.3 }, finish = { npc = "Kray", area = 1638, x = 46.8, y = 34.2 }, objective = "Speak with Kray in Thunder Bluff to learn to craft a camping item for your profession once you have shown proficiency in your skill.", desc = "So, you chose to cook up brews and potions as an Alchemist. I'm sure that'll come in handy in your travels.\n\nI reckon I know someone that can teach you how to craft a Mana Well for your camp. Build one of these and all of the healers and spellcaster types will come running to get a refreshing taste." },
