    { id = 97935, name = "Camping 101: Mining", level = 6, minLevel = 4, faction = "Horde", giver = "Kaga Wildhoof", start = { npc = "Kaga Wildhoof", area = 215, x = 45.6, y = 69.3 }, finish = { npc = "Brek Stonehoof", area = 1638, x = 34.6, y = 57.6 }, objective = "Speak with Brek Stonehoof in Thunder Bluff to learn to craft a camping item for your profession once you have shown proficiency in your skill.", desc = "Mining isn't the most glamorous, but it's good honest work and a fine profession for you to explore.\n\nI reckon I know someone that can teach you how to craft a Lodestone for your camp. Build one of these and everyone who wants to swing a sword will be eager to gather round your fire and soak up the extra \"oomph\" it can provide to increase their combat prowess." },
    { id = 97936, name = "Camping 101: Skinning", level = 6, minLevel = 4, faction = "Horde", giver = "Kaga Wildhoof", start = { npc = "Kaga Wildhoof", area = 215, x = 45.6, y = 69.3 }, finish = { npc = "Yonn Deepcut", area = 215, x = 44.9, y = 61.4 }, objective = "Speak with Yonn Deepcut in Bloodhoof Village to learn to craft a camping item for your profession once you have shown proficiency in your skill.", desc = "Being able to skillfully harvest the skins and hides of fallen beasts is one of the more valuable skills an adventurer can possess.\n\nI reckon I know someone that can teach you how to craft a Camp Chair for your camp. Sometimes it's important to just take a load off, and you can use some of those hides you've gathered to make a comfy chair to sit in. A bit of relaxation can help ensure that you are at your peak condition and can strike where it counts the next time you find yourself in a dust-up." },
    { id = 97937, name = "Camping 101: Tailoring", level = 6, minLevel = 4, faction = "Horde", giver = "Kaga Wildhoof", start = { npc = "Kaga Wildhoof", area = 215, x = 45.6, y = 69.3 }, objective = "Speak with Vhan in Thunder Bluff to learn to craft a camping item for your profession once you have shown proficiency in your skill.", desc = "Tailoring is a surprisingly potent tradeskill to invest in, and I'm sure it'll serve you well.\n\nI know someone that can teach you how to craft a Faction Banner for your camp, provided you have the skill for it. Inspiration and morale are a key part of success on any battlefield, and an inspirational banner can go a long way to keeping you energized." },
    { id = 97938, name = "Camping 101: Alchemy", level = 6, minLevel = 4, faction = "Alliance", giver = "Lyreena Duskblade", start = { npc = "Lyreena Duskblade", area = 141, x = 57.6, y = 56.6 }, finish = { npc = "Cyndra Kindwhisper", area = 141, x = 57.6, y = 60.6 }, objective = "Speak with Cyndra Kindwhisper in Dolanaar to learn to craft a camping item for your profession once you have shown proficiency in your skill.", desc = "So, you chose to cook up brews and potions as an Alchemist. I'm sure that'll come in handy in your travels.\n\nI reckon I know someone that can teach you how to craft a Mana Well for your camp. Build one of these and all of the healers and spellcaster types will come running to get a refreshing taste." },
    { id = 97939, name = "Camping 101: Blacksmithing", level = 6, minLevel = 4, faction = "Alliance", giver = "Lyreena Duskblade", start = { npc = "Lyreena Duskblade", area = 141, x = 57.6, y = 56.6 }, objective = "Speak with Elisa Steelhand in Auberdine in Darkshore to learn to craft a camping item for your profession once you have shown proficiency in your skill.", desc = "So, you've become a Blacksmith. That's a great choice if you want to make sure your blades never dull.\n\nI reckon I know someone that can help with that by teaching you how to craft a Sharpening Wheel. Bring one of these out at your camp and all the warriors and rogues in the area will be lining up to hone their weapons." },
    { id = 97940, name = "Camping 101: Enchanting", level = 6, minLevel = 4, faction = "Alliance", giver = "Lyreena Duskblade", start = { npc = "Lyreena Duskblade", area = 141, x = 57.6, y = 56.6 }, finish = { npc = "Alanna Raveneye", area = 141, x = 36.8, y = 34.2 }, objective = "Speak with Alanna Raveneye in the Oracle Glade in Teldrassil to learn to craft a camping item for your profession once you have shown proficiency in your skill.", desc = "Enchanters make everything better and are always welcome at any camp out in the wilds.\n\nI reckon I know someone that can teach you how to craft an Enchanted Lute for your camp. It's so important to find entertainment during your downtime, and this bit of magic can help ensure you are ready to weather all sorts of challenges when you hit the old dusty trail once again." },
    { id = 97941, name = "Camping 101: Engineering", level = 6, minLevel = 4, faction = "Alliance", giver = "Lyreena Duskblade", start = { npc = "Lyreena Duskblade", area = 141, x = 57.6, y = 56.6 }, finish = { npc = "Jenna Lemkenilli", area = 148, x = 38.2, y = 41 }, objective = "Speak with Jenna Lemkenilli in Auberdine in Darkshore to learn to craft a camping item for your profession once you have shown proficiency in your skill.", desc = "Engineers like yourself can cook up all sorts of bits, bots, and bombs for fun and profit.\n\nI reckon I know someone that can teach you how to craft a Reagent Bot for your camp. This helpful automaton can help keep you well-supplied so that you and your allies never run out of the materials needed to fuel your spells." },
    { id = 97942, name = "Camping 101: First Aid", level = 6, minLevel = 4, faction = "Alliance", giver = "Lyreena Duskblade", start = { npc = "Lyreena Duskblade", area = 141, x = 57.6, y = 56.6 }, finish = { npc = "Byancie", area = 141, x = 55.2, y = 56.8 }, objective = "Speak with Byancie in Dolanaar to learn to craft a camping item for your profession once you have shown proficiency in your skill.", desc = "So you've taken up First Aid? That's an honorable... and pragmatic pursuit as a <class>.\n\nI reckon I know someone that can teach you how to craft a First Aid Kit for your camp. Injuries are a reality in the world of adventuring and offering some much-needed healing at your camp could even save lives." },
    { id = 97943, name = "Camping 101: Fishing", level = 6, minLevel = 4, faction = "Alliance", giver = "Lyreena Duskblade", start = { npc = "Lyreena Duskblade", area = 141, x = 57.6, y = 56.6 }, finish = { npc = "Astaia", area = 1657, x = 47.6, y = 56.6 }, objective = "Speak with Astaia in Darnassus to learn to craft a camping item for your profession once you have shown proficiency in your skill.", desc = "You might not think so, but your skill as a fisherman can actually come in handy at camp.\n\nI reckon I know someone that can teach you how to craft a Fish Bowl for your camp. You can use this fixture to help provide a bit of joy to yourself and your fellow adventurers. A happy adventurer is a strong adventurer and I'm sure your combat capabilities will reflect that." },
    { id = 97944, name = "Camping 101: Herbalism", level = 6, minLevel = 4, faction = "Alliance", giver = "Lyreena Duskblade", start = { npc = "Lyreena Duskblade", area = 141, x = 57.6, y = 56.6 }, finish = { npc = "Malorne Bladeleaf", area = 141, x = 57.6, y = 60.6 }, objective = "Speak with Malorne Bladeleaf in Dolanaar to learn to craft a camping item for your profession once you have shown proficiency in your skill.", desc = "Looks to me like you've gained some skill in herbalism. Picking flowers isn't just for dilly-dallying, you know. It can be useful... and profitable.\n\nI reckon I know someone that can teach you how to craft an Incense Candle for your camp. High spirits are a key component to keeping healers and spellcasters in the fight, and an Incense Candle can provide a boost that magic users will surely appreciate." },
    { id = 97946, name = "Camping 101: Leatherworking", level = 6, minLevel = 4, faction = "Alliance", giver = "Lyreena Duskblade", start = { npc = "Lyreena Duskblade", area = 141, x = 57.6, y = 56.6 }, finish = { npc = "Nadyia Maneweaver", area = 141, x = 41.8, y = 49.4 }, objective = "Speak with Nadyia Maneweaver on the road to Darnassus from Dolanaar to learn to craft a camping item for your profession once you have shown proficiency in your skill.", desc = "You've become a leatherworker. Good for you, <class>. I reckon I know someone that can teach you how to make yourself a tent that will keep you cool on hot days, and dry on rainy days.\n\nWith a good tent over your head, you'll ensure that you get all the rest you need to stay sharp on your travels." },
    { id = 97948, name = "Camping 101: Mining", level = 6, minLevel = 4, faction = "Alliance", giver = "Lyreena Duskblade", start = { npc = "Lyreena Duskblade", area = 141, x = 57.6, y = 56.6 }, finish = { npc = "Kurdram Stonehammer", area = 148, x = 38.2, y = 41 }, objective = "Speak with Kurdram Stonehammer in Auberdine to learn to craft a camping item for your profession once you have shown proficiency in your skill.", desc = "Mining isn't the most glamorous, but it's good honest work and a fine profession for you to explore.\n\nI reckon I know someone that can teach you how to craft a Lodestone for your camp. Build one of these and everyone who wants to swing a sword will be eager to gather round your fire and soak up the extra \"oomph\" it can provide to increase their combat prowess." },
