    { id = 98285, name = "Camping 101: Engineering", level = 6, minLevel = 4, giver = "Strange Hermit", start = { npc = "Strange Hermit", area = 16593, x = 54, y = 39 }, finish = { npc = "Strange Hermit", area = 16593, x = 54, y = 39 }, objective = "Speak with the Strange Hermit in Shadowgale Forest to learn to craft a camping item for your profession once you have shown proficiency in your skill.", desc = "An engineer is ever-resourceful, and if you are in the wilds alone, it's always good to be able to put your trade to use. No good camp is complete without a few helpful constructs!\n\nYes, come back and see me when you've gained a little bit of experience as an engineer and I can show you how to make something special!" },
    { id = 98286, name = "Camping 101: Enchanting", level = 6, minLevel = 4, faction = "Alliance", giver = "Raan Wildwind", start = { npc = "Raan Wildwind", area = 16593, x = 41.6, y = 44.8 }, finish = { npc = "Nasalanna Windsinger", area = 16593, x = 43.2, y = 43.2 }, objective = "Speak with Nasalanna Windsinger in Shen'dar Village to learn to craft a camping item for your profession once you have shown proficiency in your skill.", desc = "Enchanters make everything better and are always welcome at any camp out in the wilds.\n\nI reckon I know someone that can teach you how to craft an Enchanted Lute for your camp. It's so important to find entertainment during your downtime, and this bit of magic can help ensure you are ready to weather all sorts of challenges when you hit the old dusty trail once again." },
    { id = 98287, name = "Camping 101: Engineering", level = 6, minLevel = 4, faction = "Alliance", objective = "Speak with Sprite Jumpsprocket in Stormwind to learn to craft a camping item for your profession once you have shown proficiency in your skill.", desc = "Engineers like yourself can cook up all sorts of bits, bots, and bombs for fun and profit.\n\nI reckon I know someone that can teach you how to craft a Reagent Bot for your camp. This helpful automaton can help keep you well-supplied so that you and your allies never run out of the materials needed to fuel your spells." },
})

