ns.AddQuests("z1", {
    { id = 95041, name = "Data Hoarders", level = 10, minLevel = 7, faction = "Alliance", giver = "Jemma Quikswitch", start = { npc = "Jemma Quikswitch", area = 1537, x = 67.8, y = 43.8 }, finish = { npc = "Jemma Quikswitch", area = 1537, x = 67.8, y = 43.8 }, objective = "Collect 7 Gnomeregan Archival Data cards from around Gnomeregan, then deliver them to Jemma Quikswitch in Ironforge.", desc = "Before we fled Gnomeregan, I made a hard copy of my family's archives. Arcanotechnical field equations, Second War submarine hull designs, Grandma Quikswitch's chili recipe... our greatest accomplishments are in those files.\n\nIt wasn't until we reached Ironforge that I found a hole in my pack! Several punch cards are gone, and without them the data's too scrambled to recover.\n\nThe cards must be buried in the snow, somewhere outside Gnomeregan. Could you find them? I know it's a long shot..." },
    { id = 95212, name = "Never Saddle on Quality", level = 10, minLevel = 7, faction = "Alliance", giver = "Rudra Amberstill", start = { npc = "Rudra Amberstill", area = 1, x = 63, y = 49.8 }, finish = { npc = "Rudra Amberstill", area = 1, x = 63, y = 49.8 }, steps = { { name = "Pristine Leopard Pelt", area = 1, x = 75.5, y = 56.8 } }, objective = "Collect 6 Pristine Leopard Pelts and deliver them to Amberstill Ranch.", desc = "We're getting ready to send a team of rams to reinforce the Alterac expedition, but we've run out of material to make their saddles.\n\nCollect pelts from the largest, fiercest leopards to the east and bring them to me. It's biting cold up there and our forces deserve nothing but the finest pelts to keep them warm!" },
    { id = 95213, name = "Stolen Blasting Powder", level = 10, minLevel = 7, faction = "Alliance", finish = { npc = "Quarrymaster Thesten", area = 1, x = 69, y = 54.8 }, steps = { { name = "Empty Powder Keg", area = 1, x = 75.6, y = 55.5 } }, objective = "Bring the Empty Powder Keg to Quarrymaster Thesten at Gol'Bolar Quarry.", desc = "The keg is stamped:\n\nBLASTING POWDER - DANGER - DO NOT HANDLE - DANGER - QUARRYMASTER AUTHORIZATION ONLY - DANGER\n\nYou get a sinking feeling that the troggs shouldn't have this. It would be best to report this to the quarry sooner rather than later." },
    { id = 95214, name = "Stolen Blasting Powder", level = 10, minLevel = 7, faction = "Alliance", giver = "Quarrymaster Thesten", start = { npc = "Quarrymaster Thesten", area = 1, x = 69, y = 54.8 }, finish = { npc = "Quarrymaster Thesten", area = 1, x = 69, y = 54.8 }, steps = { { name = "Stolen Blasting Powder", area = 1, x = 75.6, y = 55.5 } }, objective = "Recover 16 Stolen Blasting Powder from the troggs east of Gol'Bolar Quarry, then return to Quarrymaster Thesten.", desc = "This keg held enough powder to turn King Magni's throne room into an open air courtyard. We've got to get it back from the troggs before they work out how to ignite it." },
    { id = 95217, name = "The Quarry's Smith", level = 10, minLevel = 7, faction = "Alliance", giver = "Frast Dokner", start = { npc = "Frast Dokner", area = 1, x = 68.8, y = 55.8 }, finish = { npc = "Frast Dokner", area = 1, x = 68.8, y = 55.8 }, steps = { { name = "Copper Bar", area = 40, x = 31.7, y = 38 }, { name = "Toughened Boar Hide", area = 1, x = 80.3, y = 46.6 } }, objective = "Collect 12 Copper Bars and 4 Toughened Boar Hides and deliver them to Frast Dokner.", desc = "So you're looking to learn the blacksmith's trade? Maybe we can help each other.\n\nThe supply shipment's late, and I need materials for some repairs around the camp. If you get me what I need, I'll teach you some of my techniques. Sound fair?" },
    { id = 96390, name = "Nip 'Em in the Bud", level = 13, minLevel = 9, requires = { 96392 }, faction = "Alliance", giver = "Earthseer Farsen", start = { npc = "Earthseer Farsen", area = 1, x = 64.8, y = 58.4 }, finish = { npc = "Earthseer Farsen", area = 1, x = 64.8, y = 58.4 }, steps = { { name = "Dark Iron Spy", area = 1, x = 77.5, y = 60.8 } }, objective = "Slay 10 Dark Iron Spies in Dun Morogh.", desc = "Dark Iron spies have infiltrated Dun Morogh. To what end I canna' not sure, but this is a problem we need to nip in the bud before it is allowed to grow.\n\nHead eastward to Ironband's Compound and kill the Dark Iron spies that you find there." },
    { id = 96392, name = "Farsen's Watch", level = 13, minLevel = 9, requires = { 96408 }, faction = "Alliance", giver = "Earthseer Farsen", start = { npc = "Earthseer Farsen", area = 1, x = 64.8, y = 58.4 }, finish = { npc = "Earthseer Farsen", area = 1, x = 64.8, y = 58.4 }, steps = { { name = "Earthseer Farsen", area = 1, x = 64.8, y = 58.4 } }, objective = "Speak with Earthseer Farsen's and ask him to lend you his farsight to observe the Dark Iron threat.", desc = "Greetings to ye, friend. My name is Earthseer Farsen and I'm visiting Dun Morogh from Aerie Peak. As I was travelin', I couldn't help but notice that we have, well... a bit o' a Dark Iron Dwarf problem.\n\nIf ye have a moment, I can show ye what I mean. I've got a bit o' magic that should do the trick." },
    { id = 96408, name = "A Visitor to Dun Morogh", level = 13, minLevel = 9, faction = "Alliance", giver = "Beldin Steelgrill", start = { npc = "Beldin Steelgrill", area = 1, x = 50.4, y = 49 }, finish = { npc = "Earthseer Farsen", area = 1, x = 64.8, y = 58.4 }, desc = "Last night one of our mountaineers spotted a campfire on a hillside to the east. It looks to be pretty high up, overlooking  the Gol'Bolar Quarry.\n\nIt's probably nothing, but I'd like you to go check on that camp. If they are friendly, no harm done. If they aren't friendly... well, you know what to do." },
    { id = 97277, name = "Grund and Gozwin", level = 6, minLevel = 4, faction = "Alliance", giver = "Grund Drokda", start = { npc = "Grund Drokda", area = 1, x = 28.6, y = 67.4 }, finish = { npc = "Grund Drokda", area = 1, x = 28.6, y = 67.4 }, steps = { { name = "Snow Leopard Prowler", area = 1, x = 27.4, y = 63 } }, objective = "Find Grund and Gozwin's camp in the hills to the northwest. Recover Gozwin's Mechanic's Log and kill the Snow Leopard Prowler.", desc = "Oi, had me back turned gettin' the boar roast ready when I heard me pal Gozwin screamin' fer his life!\n\nWicked fangs and a blur are all I saw when I turned. Such huge paws! A snow leopard was draggin' its gnomish catch away. I grabbed me shotgun and fired above the beast. It dropped him and sprinted off.\n\nLuckily, it hadn't done more than give ol' Goz some deep scratches.\n\nHead back to camp in the northwestern hills and retrieve Gozwin's Mechanic's Log. Kill that snow leopard too if you see it!" },
    { id = 98319, name = "Secure the Mountain (2/3)", level = 8, minLevel = 4, requires = { 98322 }, faction = "Alliance", giver = "Mountaineer Gretchen", start = { npc = "Mountaineer Gretchen", area = 1, x = 44, y = 57 }, finish = { npc = "Mountaineer Gretchen", area = 1, x = 44, y = 57 }, desc = "It's bad enough havin' a troll problem, but the mountains are filled tae the brim with wendigos! They normally keep to their own caves, but they seem tae be spreadin' like bunnies. Now they've filled the Grizzled Den north of here.\n\nIf we want Whitebeard's report, we're gonna need to find my partner Cornelius. The blockhead got a little too excited and charged in head first. Brave, but stupid.\n\nHead into the cave and see where he is. And feel free to take out some the beasts while yer at it." },
    { id = 98321, name = "Flintfire's Shipment", level = 7, minLevel = 4, faction = "Alliance", giver = "Tognus Flintfire", start = { npc = "Tognus Flintfire", area = 1, x = 45.2, y = 52 }, finish = { npc = "Tognus Flintfire", area = 1, x = 45.2, y = 52 }, objective = "Collect 8 Flintfire Shipments from the Grizzled Den for Tongus Flintfire in Kharanos.", desc = "Hoha! Good to see a <race> who's not afraid to get their hands dirty.\n\nIf yer lookin' fer work, I'm afraid I'm a little short on supplies at the moment. Our most reliable source of ore has been overrun by wendigo and now the cave has been abandoned. The miners had to drop everything when they fled!\n\nSay, why don't ye poke yer head around the Grizzled Den to the west and see if you can find some of our missing shipments. It would save us a great deal o' trouble." },
    { id = 98322, name = "Secure the Mountain (1/3)", level = 8, minLevel = 4, faction = "Alliance", giver = "Senir Whitebeard", start = { npc = "Senir Whitebeard", area = 1, x = 46.6, y = 53.8 }, finish = { npc = "Mountaineer Gretchen", area = 1, x = 44, y = 57 }, desc = "Spelunking dark caves is adventurer business. My job's just to make reports and send them over to Ironforge.\n\nTrouble is, one of my reports hasn't... well, reported back. I asked a few mountaineers to learn more about the wendigo problem we have out here, but I haven't heard from them.\n\nIf you're already going to be out and about, what say you don't check in with Mountaineer Gretchen just west of town. I'm late enough as it is!" },
    { id = 98323, name = "Secure the Mountain (3/3)", level = 8, minLevel = 4, requires = { 98319 }, faction = "Alliance", giver = "Mountaineer Gretchen", start = { npc = "Mountaineer Gretchen", area = 1, x = 44, y = 57 }, finish = { npc = "Senir Whitebeard", area = 1, x = 46.6, y = 53.8 }, objective = "Deliver Mountaineer Gretchen's Report back to Senir Whitebeard in Kharanos.", desc = "Hopefully ye put down a fair number of the mongrels while you were in there. Shame about Cornelius, though.\n\nFrom what you described, there's not much to report other than the cave is a lost cause. Whitebeard's not gonna like that answer, but I'm not darin' sendin' anybody else into that death trap.\n\nFeel free tae pass along the message, <name>. I'm not leavin' this spot till the mountain's secure." },
    { id = 98326, name = "Frosthowl", level = 9, minLevel = 5, faction = "Alliance", giver = "Gretta Ganter", start = { npc = "Gretta Ganter", area = 1, x = 31.4, y = 44.6 }, finish = { npc = "Gretta Ganter", area = 1, x = 31.4, y = 44.6 }, steps = { { name = "Sack of Fish", area = 1, x = 39.6, y = 48.6 } }, objective = "Slay Frosthowl and collect the Sack of Fish for Gretta Ganter in Brewnall Village", desc = "Do ye know how hard it is to fish on a frozen lake? My poor husband, Paxton, has been out in the middle of it for days and we barely have a single sack to show fer it.\n\nWell, we DID have a sack to show fer it. Until the thrice-damned wendigo attacked me and made off with our haul. It'll take us weeks to fish all that back up! If that loudmouth Frosthowl didn't scare 'em all off, anyway.\n\nDo us a favor and get it back, aye? Drooling brute is hiding somewhere deep in the Grizzled Den to the southeast." },
    { id = 98423, name = "The Treaty of Understanding", level = 16, minLevel = 9, faction = "Alliance", finish = { npc = "King Magni Bronzebeard", area = 1537, x = 39.4, y = 55.8 }, objective = "Deliver the Treaty of Understanding to Magni Bronzebeard in Ironforge.", desc = "Inside of the vault you find a tablet detailing the terms of a peace treaty between the Bronzebeard and Wildhammer dwarf clans. It appears to date back to time period just after of the War of the Three Hammers, and is very likely a notable piece of dwarven history. The king of Ironforge would no doubt be interested in this artifact." },
    { id = 99158, name = "Dawn in the Mountains", level = 8, minLevel = 5, faction = "Alliance", giver = "Maxan Anvol", start = { npc = "Maxan Anvol", area = 1, x = 47.2, y = 52.2 }, finish = { npc = "Father Gavin", area = 1, x = 57.6, y = 44.8 }, objective = "Bring the crate of candles to Father Gavin.", desc = "There's a priest out in the mountains that belongs to an organization called the Argent Dawn. They're a holy group that is dedicated to finding and destroying the unholy and unnatural.\n\nFather Gavin though, he's mostly the type that seeks to help and heal everyone rather than grab a weapon. He's fixed up an old building to serve as a rest spot for travelers. I've got a shipment of holy candles that I need to get him. Could you bring them to him if your going that way?" },
    { id = 99159, name = "Finding Warmth", level = 8, minLevel = 5, faction = "Alliance", giver = "Father Gavin", start = { npc = "Father Gavin", area = 1, x = 57.6, y = 44.8 }, finish = { npc = "Father Gavin", area = 1, x = 57.6, y = 44.8 }, objective = "Collect 14 pieces of firewood.", desc = "My hearth is open to warm any soul, but I'd like to ask you to help me if you could.\n\nI simply need more firewood. It is something I would normally do myself, but I have been preoccupied by other tasks." },
    { id = 99160, name = "Rime's Wrath", level = 8, minLevel = 5, faction = "Alliance", giver = "Father Gavin", start = { npc = "Father Gavin", area = 1, x = 57.6, y = 44.8 }, finish = { npc = "Father Gavin", area = 1, x = 57.6, y = 44.8 }, steps = { { name = "Minor Ice Elemental", area = 1, x = 55.1, y = 45.3 } }, objective = "Destroy 10 minor ice elementals.", desc = "You may have noticed the elementals nearby. A shelf of rock and ice fell from the mountain peaks a few days ago and riled them up.\n\nThese frozen mountains are already treacherous for the average dwarf or human without the elements taking form. I am not one for fighting anymore--so any of the spirits you can kill would help make the road safer." },
    { id = 99161, name = "Rime's Wrath", level = 8, minLevel = 5, faction = "Alliance", giver = "Father Gavin", start = { npc = "Father Gavin", area = 1, x = 57.6, y = 44.8 }, finish = { npc = "Father Gavin", area = 1, x = 57.6, y = 44.8 }, steps = { { name = "Avala's Core", area = 1, x = 57.6, y = 42.7 } }, objective = "Kill Avala and retrieve its core.", desc = "I noticed that the first elemental that appeared after the rockslide was larger than its peers. And from what I can tell, it has been the source of occasionally weather changes and other minor slides.\n\nI've been calling it 'Avala', if you could kill it and retrieve the core as proof, I will reward you." },
    { id = 99162, name = "Treacherous Cold", level = 8, minLevel = 5, faction = "Alliance", giver = "Father Gavin", start = { npc = "Father Gavin", area = 1, x = 57.6, y = 44.8 }, finish = { npc = "Father Gavin", area = 1, x = 57.6, y = 44.8 }, objective = "Collect the rifles of fallen mountaineers.", desc = "Even mountaineers from Ironforge have to keep their wits about them when traversing through the peaks of Dun Morogh. Falling snow and ice often spells the end of some more novice members' lives.\n\nAfter a slide, I usually try to find any sign of survivors or victims--while praying to the Light that there's nothing to be found. But with the elements acting up, I've held off wandering too far. If you could look for some lost mountaineers and bring me their rifles, I will return them to Ironforge." },
})

ns.AddQuests("z10", {
    { id = 96137, name = "Ira's Dagger", level = 24, minLevel = 18, faction = "Alliance", steps = { { name = "Black Ravager", area = 10, x = 66.9, y = 30.7 }, { name = "Young Black Ravager", area = 10, x = 50.8, y = 67.3 } }, objective = "Defeat 10 Young Black Ravagers and 7 Black Ravagers then return to Sirra Von'Indi in Darkshire for more information.", desc = "A small dagger belonging to the self-appointed ranger, Ira, who kept the forests safe by preventing the beasts within from attacking travelers.\n\nWith Ira's spirit still wandering the woods, perhaps her unfinished business was to clear out the worg that continue to claim victims throughout the forest." },
    { id = 96138, name = "Merrick's Bow", level = 28, minLevel = 18, faction = "Alliance", steps = { { name = "Splinter Fist Warrior", area = 10, x = 35.1, y = 77.1 }, { name = "Splinter Fist Taskmaster", area = 10, x = 35.7, y = 72.2 } }, objective = "Defeat 8 Splint Fist Warriors and 4 Splint Fist Taskmasters then return to Sirra Von'Indi in Darkshire for more information.", desc = "A bow left by the spirit of Merrick Valor, famed Watcher who prided himself on keeping the roads safe from encroaching enemies.\n\nWith Merrick's spirit still wandering the roads, perhaps his unfinished business was to clear out invaders near his home in Raven Hill. The ogres south of town may be what's troubling his spirit." },
    { id = 96139, name = "The Valor Family", level = 22, minLevel = 18, faction = "Alliance", giver = "Sirra Von'Indi", start = { npc = "Sirra Von'Indi", area = 10, x = 72.6, y = 47.6 }, finish = { npc = "Sirra Von'Indi", area = 10, x = 72.6, y = 47.6 }, objective = "Search Raven Hill for anything of interest and return to Sirra Von'Indi in Darkshire.", desc = "In dark times like these, it's important we remember our heroes as much as our foes. Darkshire would not still be standing if it weren't for the bravery of folk like the good Lady Althea or those who lost their lives at Raven Hill.\n\nHave you read much on Raven Hill? No, of course not. Its history was wiped out along with its people. My library, impressive as it is, has little on the subject.\n\nIf you happen to find anything, I would appreciate bringing it here. Those folk deserve to be remembered." },
    { id = 98372, name = "An Unfortunate End", level = 60, minLevel = 1, giver = "Night Watch Guard", start = { npc = "Night Watch Guard", area = 10, x = 17, y = 54.8 }, finish = { npc = "Night Watch Guard", area = 10, x = 17, y = 54.8 } },
    { id = 98447, name = "The Valor Family", level = 27, minLevel = 18, steps = { { name = "Ol' Sandy", area = 10, x = 17.7, y = 53.6 } }, objective = "Find the cause of the Valor family ghosts in Raven Hill for Sirra Von'Indi in Darkshire.", desc = "Despite you putting down the Valor family ghosts, the reports of attacks have not ceased. It was a good gamble, but perhaps we did not settle their unfinished business after all.\n\nFrom my research, it sounds like this family all went missing at the same time. Whatever trauma caused their spirits to be chained to this realm must have happened all at once.\n\nOur only clue is where you found the book. Return to Raven Hill and see what you can find. Maybe bringing their weapons will spark something." },
})

ns.AddQuests("z11", {
    { id = 98072, name = "Crocs of the Sky", level = 27, minLevel = 19, steps = { { name = "Pristine Crimson Scale", area = 11, x = 63.8, y = 45.2 } }, objective = "Collect 10 Pristine Crimson Scales and bring them to James Halloran in Menethil Harbor.", desc = "You're quite the go-getter! I have just one more favor to ask, if you're up for something a bit more dangerous.\n\nThe crocolisk trade is steady money, but they're small fish compared to what whelp scales will bring. Folks will pay top dollar for a sack of those.\n\nCrocs of the sky, I call 'em! There's no way my apprentice could get them--but it seems right up your alley!\n\nYou'll find whelps far to the east, along the Green Belt. But be careful, there's nasty orcs in those hills!" },
    { id = 98189, name = "Return the Statuette (6/8)", level = 25, minLevel = 20, requires = { 286 }, faction = "Alliance", objective = "Bring the Menethil Statuette to Captain Stoutfist in Menethil Keep.", desc = "My goodness, it's--it's beautiful!\n\nThe Blind Princess was to deliver this to Menethil Harbor before tragedy struck. We were so close!\n\nI believe it was to be signed for by Captain Stoutfist in Menethil Keep just behind us. Why don't you do the honors of finishing the job?" },
    { id = 98197, name = "Spoils of War", level = 22, minLevel = 18, faction = "Alliance", giver = "Valstag Ironjaw", start = { npc = "Valstag Ironjaw", area = 11, x = 10, y = 56.8 }, finish = { npc = "Valstag Ironjaw", area = 11, x = 10, y = 56.8 }, objective = "Recover 6 Khaz Modan Timber and 30 Khaz Modan Iron from Menethil Harbor for Valstag Ironjaw.", desc = "This harbor was first built by the Old Horde as a staging ground for their naval invasion of Hillsbrad. Completely circumvented Lordaeron's defenses!\n\nSo many lives lost...\n\nWhat's worse is that fleet was built with the very resources they stole from Khaz Modan!\n\nPlenty of it remains in the harbor after Admiral Proudmoore routed the brutes and built this place for the Alliance. We'll need it to bolster the town's defenses with the Dragonmaw on the move." },
    { id = 98208, name = "Bloom of the Heavens", level = 29, minLevel = 22, objective = "Recover Nord'el for Sylessa Duskwhisper in Menethil Harbor.", desc = "I came to Menethil Harbor from Auberdine, from the great tree Teldrassil, to recover a bloom of great import to my people.\n\nMy people's ship the Flying Osprey crashed here many moons ago, joined with the Kul Tiran Third Fleet. Among its cargo was the flower known as Nord'el--Bloom of the Heavens in your tongue--bloomed under a full moon at the peak of Mount Hyjal, our former home.\n\nPlease help me retrieve it! The wreckage is just south of the city, but it is inhabited by fierce murloc raiders!" },
    { id = 98240, name = "Crimson Crate Delivery", level = 29, minLevel = 19, requires = { 98072 }, faction = "Alliance", objective = "Bring the Crimson Crate to Howin Kindfeather off the road to the east of Menethil Harbor.", desc = "Word is officially out on those whelps, <name>. We already have an order in!\n\nI'll package 'em up all nice for you, then you take it out to the customer. I know, I know; it's just one last favor, I promise!\n\nThese will be for one \"Howin Kindfeather\". Sent his gryphon into town of all things with a letter for the order! Says he's just off the road to the east, a bit past Whelgar's Excavation Site, if you're familiar." },
    { id = 98245, name = "Razormaw Needling", level = 29, minLevel = 21, requires = { 98240 }, faction = "Alliance", steps = { { name = "Razormaw Incisor", area = 11, x = 68.4, y = 31.8 } }, objective = "Collect 10 Razormaw Incisors for Howin Kindfeather.", desc = "I don't know who I hate more: the bloody Dark Irons, the Dragonmaw, or the drakes they rode.\n\n<Howin spits.>\n\nI aim tae make things right. But we're gonna need some supplies.\n\nThese whelp scales will protect against dragonfire a good bit, but they're a pain in the arse tae weave together.\n\nThe Razormaw raptors up in Raptor Ridge to the northeast and Saltspray Glen to the northwest are so named for their pointy chompers--they oughta break through the scales.\n\nBring me a handful of the incisors." },
    { id = 98246, name = "Trying Times", level = 29, minLevel = 21, faction = "Alliance", objective = "Gather 12 Perfect Razormaw Eggs for Howin Kindfeather.", desc = "I'll need some eggs if my plan is going tae work. Bassbeak needs a nice an' full belly--I ain't in the business of hoppin' on the back of a surly gryphon.\n\nThey need to be perfect--no cracks or anything.\n\nTake some from the Razormaw raptors--they're known for having yolks the size of a gnome's noggin. You can find 'em in Raptor Ridge to the northeast and Saltspray Glen to the northwest.\n\nLet's make it a nice even dozen, just to be safe." },
    { id = 98282, name = "Alchemical Hazards", level = 22, minLevel = 20, faction = "Alliance", giver = "Caitlin Grassman", start = { npc = "Caitlin Grassman", area = 11, x = 11.8, y = 58.6 }, steps = { { name = "Unruptured Stalker Gland", area = 11, x = 50, y = 61.8 } }, objective = "Collect an Unruptured Stalker Gland from Thelgen Rock for Caitlin Grassman in Menethil Harbor.", desc = "Certain alchemical recipes require ingredients sourced from, well, very dangerous places. And those are often just the base herbs! The other ingredients are even worse!\n\nI need to make more antivenom before I can leave again. I swear everything in this marsh is venomous. It's like it runs through the land itself!\n\nCan you help me? I'll need a venom gland from the spiders in Thelgen Rock to the far southeast. But it has to be unruptured, or too much venom will spill out before you can get here. Sorry!" },
    { id = 98293, name = "Forced Disarmament", level = 30, minLevel = 22, faction = "Alliance", objective = "Collect 30 Dragonmaw Armaments in Dragonmaw Retreat, then bring them to Captain Stoutfist in Menethil Keep.", desc = "The Dragonmaw are stockpiling all manner of weaponry. It would be wise to relieve them of these before more soldiers can be armed.\n\nCaptain Stoutfist in Menethil Keep would surely be interested in these." },
    { id = 98459, name = "A Lack of Virtue", level = 21, minLevel = 18, faction = "Alliance", giver = "Tom \\\"Half-fish\\\" Wilson", start = { npc = "Tom \"Half-fish\" Wilson", area = 267, x = 51.2, y = 66.4 }, finish = { npc = "Bart Tidewater", area = 11, x = 8.8, y = 59.8 }, objective = "Deliver Tom's Gift to Bart Tidewater in Menethil Harbor in the Wetlands.", desc = "Bart Tidewater's a no-good cheapskate, I tell ya!\n\n\"Captain of the Maiden's Virtue\" he calls himself. That ship's sailed as far as a rock in Tanaris! He's no captain, he's an actor who won enough hands of poker to buy the Virtue in the first place!\n\nIf you ever find yourself in Menethil Harbor over in the Wetlands, give this to him and let him know it's from ol' Half-fish.\n\nThere's a boat from here that can take you right to the harbor, by the way. It'll be the second stop!\n\nAnd he cheats at poker!" },
    { id = 98461, name = "Unrequited Love", level = 21, minLevel = 18, faction = "Alliance", giver = "Archaeologist Hollee", start = { npc = "Archaeologist Hollee", area = 148, x = 37.4, y = 41.8 }, finish = { npc = "Tarrel Rockweaver", area = 11, x = 11.4, y = 52.2 }, objective = "Deliver Hollee's Note to Tarrel Rockweaver near Menethil Harbor in the Wetlands.", desc = "If you're heading out of Auberdine, I could use your help!\n\nMy dear friend Tarrel and I were classmates in school. Oh, he was such a quickfire on all things excavation! We got split up after graduation--him to Wetlands, and me to here in Darkshore.\n\n<Hollee sighs, then her brow furrows slightly.>\n\nSorry, and his wife... Merrin.\n\nIt doesn't matter. If you go to the Wetlands, could you make sure he's alright? And maybe give him this? He's probably near Menethil Harbor. There's a boat straight there." },
})

ns.AddQuests("z12", {
    { id = 91723, name = "Delicate Instruments", level = 10, minLevel = 7, faction = "Alliance", giver = "Hamish Bergwort", start = { npc = "Hamish Bergwort", area = 12, x = 65, y = 69.8 }, finish = { npc = "Hamish Bergwort", area = 12, x = 65, y = 69.8 }, steps = { { name = "Kobold Geomancer", area = 12, x = 62.4, y = 54.9 } }, objective = "Kill 8 Kobold Geomancers in Jasperlode Mine, then return to Hamish Bergwort in the Tower of Azora.", desc = "Blast it! Every time I try to calibrate these sensitive arcane instruments, they get thrown off again by a surge of energy.\nThe surges seem to be coming from the north, where those primitive Kobolds have been practicing their crude magic. Could you clear some of them out, so I can continue my work?" },
    { id = 91724, name = "Delicate Instruments", level = 10, minLevel = 7, faction = "Alliance", giver = "Hamish Bergwort", start = { npc = "Hamish Bergwort", area = 12, x = 65, y = 69.8 }, finish = { npc = "Hamish Bergwort", area = 12, x = 65, y = 69.8 }, steps = { { name = "Defias Rogue Wizard", area = 12, x = 74.2, y = 51.4 } }, objective = "Kill 6 Defias Rogue Wizards at Stone Cairn Lake, then return to Hamish Bergwort in the Tower of Azora.", desc = "Almost there, and... By the Nether! Something is still disrupting my instruments.\nThis is most frustrating, <name>. I have heard rumors that the local bandits have been practicing spells near Stone Cairn Lake. Maybe if you stop them, these disruptions will finally cease and I can get some work done?" },
    { id = 91725, name = "Stolen Enchanting Supplies", level = 10, minLevel = 7, faction = "Alliance", giver = "Blixie Fitzwink", start = { npc = "Blixie Fitzwink", area = 12, x = 63.2, y = 72.6 }, finish = { npc = "Blixie Fitzwink", area = 12, x = 63.2, y = 72.6 }, objective = "Collect 5 Stolen Enchanting Supplies from gnoll camps around Stone Cairn Lake, then return to Blixie Fitzwink near the Tower of Azora.", desc = "I was sent by Master Theocritus to pick up some enchanting supplies from the trading post, but on the way back I was ambushed by a pack of gnolls!\n\nI dropped the package and escaped, but if I return without it, I'll be cleaning up after the polymorph experiments for weeks as punishment! Do you think you could find the supplies for me?" },
    { id = 91732, name = "Good Steel", level = 10, minLevel = 7, faction = "Alliance", giver = "Hagar Lowe", start = { npc = "Hagar Lowe", area = 12, x = 82.4, y = 63.8 }, finish = { npc = "Hagar Lowe", area = 12, x = 82.4, y = 63.8 }, objective = "Collect 4 Mining Tools from Jasperlode Mine, then return to Hagar Lowe in Eastvale Logging Camp.", desc = "Good steel is in short supply after the war, and our tools have suffered for it. The Jasperlode miners used finely-crafted picks, and I imagine some of them are still there in the depths of the mine. Could you retrieve some for me, and I'll see if I can repurpose the steel?" },
    { id = 91733, name = "Downstream", level = 10, minLevel = 7, faction = "Alliance", giver = "Ormin Pelford", start = { npc = "Ormin Pelford", area = 12, x = 76.4, y = 72 }, finish = { npc = "Ormin Pelford", area = 12, x = 76.4, y = 72 }, objective = "Collect the Waterlogged Axe, Waterlogged Saw, and Waterlogged Toolbox that have washed downstream from Eastvale Logging Camp, then return to Ormin Pelford.", desc = "I was bringing back a supply shipment from the trading post, but my wagon tipped over and the supplies fell in the river! Before I could catch them, they had already washed downstream.\nBetween the murlocs and wolves down there, I don't stand a chance of retrieving the supplies on my own. You seem like the hardy sort - do you think you could find them for me?" },
    { id = 91736, name = "Applejack Still", faction = "Alliance" },
    { id = 91738, name = "An Apple Treat", level = 10, minLevel = 7, faction = "Alliance", giver = "Sergeant De Vries", start = { npc = "Sergeant De Vries", area = 12, x = 24, y = 73 }, finish = { npc = "Sergeant De Vries", area = 12, x = 24, y = 73 } },
    { id = 91740, name = "Croaky's Head", level = 10, minLevel = 7, faction = "Alliance", finish = { npc = "Merell Ross", area = 12, x = 84.6, y = 79.2 }, objective = "Deliver Croaky's Head to Merell Ross at Ridgepoint Tower.", desc = "This murloc has no doubt been terrorizing the local roads for some time. You suspect the nearby watch guards will want to know of its demise." },
    { id = 91741, name = "Nibbled-On Book", level = 2, minLevel = 1, faction = "Alliance", finish = { npc = "Brother Paxton", area = 12, x = 49.4, y = 40.4 }, objective = "Return the book to Brother Paxton.", desc = "<One of the kobolds dropped this book. It looks like the kobold might have tried to eat it.\n\nBrother Paxton inside the abbey has a small library he maintains. The book must have come from there.>" },
    { id = 91743, name = "Rascally Rodents", level = 2, minLevel = 1, requires = { 91741 }, faction = "Alliance", giver = "Brother Paxton", start = { npc = "Brother Paxton", area = 12, x = 49.4, y = 40.4 }, finish = { npc = "Brother Paxton", area = 12, x = 49.4, y = 40.4 }, steps = { { name = "Stolen Book", area = 12, x = 48.9, y = 34 } }, objective = "Retrieve 8 Stolen Books from kobolds in Northshire Valley and return them to Brother Paxton.", desc = "Those awful kobolds are eating my books! You have to get them back before they devour my whole library." },
    { id = 91745, name = "Mining Consultant", level = 3, minLevel = 1, requires = { 91743 }, faction = "Alliance", giver = "Brother Paxton", start = { npc = "Brother Paxton", area = 12, x = 49.4, y = 40.4 }, finish = { npc = "Kelsey Fargo", area = 12, x = 47.2, y = 32.2 }, desc = "Go talk to the new mining apprentice, Kelsey Fargo. She works right outside the mine and has probably seen what the kobolds are up to. Maybe she can teach you a thing or two about mining while you're at it." },
    { id = 91746, name = "Elmpaw's Head", level = 10, minLevel = 7, faction = "Alliance", finish = { npc = "Helene Peltskinner", area = 12, x = 46.2, y = 62.2 }, objective = "Deliver Elmpaw's Head to Helene Peltskinner near Goldshire.", desc = "The trophy serves as an impressive reminder of your victory over Elmpaw. A local hunter or skinner might be interested to hear the story." },
    { id = 91751, name = "Rough Wolf Pelts", level = 7, minLevel = 5, faction = "Alliance", giver = "Helene Peltskinner", start = { npc = "Helene Peltskinner", area = 12, x = 46.2, y = 62.2 }, finish = { npc = "Helene Peltskinner", area = 12, x = 46.2, y = 62.2 }, steps = { { name = "Rough Wolf Pelt", area = 12, x = 69.9, y = 66.2 } }, objective = "Skin wolves around Elwynn Forest to obtain 7 Rough Wolf Pelts, then deliver them to Helene Peltskinner near Goldshire.", desc = "Are you looking for an opportunity to practice skinning? My husband usually helps with hunting wolves, but he's busy up by the abbey. I could use a hand collecting more pelts to finish the orders I'm working on." },
    { id = 91752, name = "The Big Picture", level = 3, minLevel = 1, requires = { 91745 }, faction = "Alliance", giver = "Kelsey Fargo", start = { npc = "Kelsey Fargo", area = 12, x = 47.2, y = 32.2 }, finish = { npc = "Marshal McBride", area = 12, x = 48.8, y = 41.6 }, steps = { { name = "Sack of \"Picture\" Books", area = 12, x = 49.1, y = 28.4 } }, objective = "Retrieve a Sack of \"Picture\" Books from Shinyfinder Narf. Bring the sack to Marshal McBride just inside Northshire's Abbey.", desc = "Every once in a while, a kobold comes through yelling \"Picture for Narf!\" I don't know who Narf is. Maybe one of the head kobolds at the back of the mine? I bet he has a whole sack of books by now.\n\nGo get those books and bring them to our local law enforcement, Marshal McBride. You should find a friend to help. Those kobolds inside the mine are a lot meaner." },
    { id = 91753, name = "An Enchanting Lesson", level = 7, minLevel = 5, faction = "Alliance", giver = "Kitta Firewind", start = { npc = "Kitta Firewind", area = 12, x = 64.8, y = 70.6 }, finish = { npc = "Kitta Firewind", area = 12, x = 64.8, y = 70.6 }, objective = "Kitta Firewind in the Tower of Azora wants you to collect 3 Luminous Residue.\n\nLuminous Residue can be obtained by disenchanting Crude Wax Effigies dropped by Kobold Geomancers.", desc = "Academic rigor is of course essential to the enchanter's craft, but a practical foundation can pay dividends. Consider, as an example, the lowly Kobold. Lacking formal education, they nevertheless demonstrate a sort of innate aptitude for simple cantrips and enchantments.\n\nObtain some of their wax effigies and deconstruct the enchantments bound within them. You may find it elucidating." },
    { id = 91758, name = "Follow That Kobold!", level = 4, minLevel = 1, requires = { 91752 }, faction = "Alliance", giver = "Marshal McBride", start = { npc = "Marshal McBride", area = 12, x = 48.8, y = 41.6 }, finish = { npc = "Tordrin Sternblade", area = 12, x = 51.2, y = 40.8 }, desc = "You're not done with those kobolds yet. We just got word from Kelsey that a kobold left the mine carrying a large sack of books. I need you to track down this kobold so we can retrieve the books for Brother Paxton.\n\nGo talk to Tordrin Sternblade. He's the new Hunter trainer that just arrived from Ironforge. You can find him behind the abbey, near the stable. He can help you track this kobold thief." },
    { id = 91772, name = "Shhh! We're Hunting Kobolds", level = 4, minLevel = 1, requires = { 91758 }, faction = "Alliance", giver = "Tordrin Sternblade", start = { npc = "Tordrin Sternblade", area = 12, x = 51.2, y = 40.8 }, finish = { npc = "Marshal Dughan", area = 12, x = 42.2, y = 65.8 }, objective = "Follow the kobold tracks and report to Marshal Dughan in Goldshire with your findings and the Kobold Tracking Kit.", desc = "Alright. Take this kobold tracking kit. It'll let ye' track the kobold that Marshal McBride is concerned with.\n\nFollow the tracks and bring what ye' find to Marshal Dughan in Goldshire.\n\nI have a feelin' these varmints are up to somethin' outside Northshire. So ye'll be needin' Dughan's help." },
    { id = 91775, name = "Book Return", level = 6, minLevel = 1, requires = { 91772 }, faction = "Alliance", giver = "Marshal Dughan", start = { npc = "Marshal Dughan", area = 12, x = 42.2, y = 65.8 }, finish = { npc = "Marshal Dughan", area = 12, x = 42.2, y = 65.8 }, steps = { { name = "Picture Book: Fun with Elementals", area = 12, x = 39.8, y = 80.7 }, { name = "Lost Book", area = 12, x = 39.6, y = 81.2 } }, objective = "Find 6 Lost Books and \"Fun with Elementals\" and return them to Marshal Dughan.", desc = "While you're investigating the Fargodeep Mine, see if you can find any of Brother Paxton's books to return. In particular, Paxton is very concerned about a book titled, \"Fun with Elementals\". He thinks even a kobold could use it to summon an elemental servant. Be warned, the depths of the mine are fairly dangerous. You should bring friends.\n\nTake this book bag to protect the books when you find them!" },
    { id = 91777, name = "Rare Books", level = 7, minLevel = 1, requires = { 91775 }, faction = "Alliance", giver = "Marshal Dughan", start = { npc = "Marshal Dughan", area = 12, x = 42.2, y = 65.8 }, finish = { npc = "Brother Paxton", area = 12, x = 49.4, y = 40.4 }, steps = { { name = "Geomancy for Curious Young Wizards", area = 12, x = 61, y = 49 }, { name = "Arcane Explainer: Magical Stuff in Simple Words", area = 12, x = 61.3, y = 47.7 } }, objective = "Recover \"Geomancy for Curious Young Wizards\" and \"Arcane Explainer: Magical Stuff in Simple Words\" and return them to Brother Paxton inside Northshire's Abbey.", desc = "There's just two books left missing on Brother Paxton's list: \"Geomancy for Curious Young Wizards\" and \"Arcane Explainer: Magical Stuff in Simple Words\".\n\nThe kobolds must have taken them to the Jasperlode Mine. Please track down those two books and bring them back to Brother Paxton.\n\nBut I'm afraid it will be quite dangerous. If the \"apprentice\" kobold was summoning an elemental, who knows what the master can do. I'd bring some friends if I were you." },
    { id = 92124, name = "Book Inventory", level = 2, minLevel = 1, faction = "Alliance", giver = "Brother Paxton", start = { npc = "Brother Paxton", area = 12, x = 49.4, y = 40.4 }, finish = { npc = "Daniel", area = 12, x = 49.4, y = 40.6 }, desc = "We need to take stock of how many books are missing!\n\nGo talk to my useless assistant, Daniel. He can do a quick inventory and let us know how serious the problem is.\n\nHe's obsessed with the various trade professions in Elwynn Forest. The boy keeps focusing on those instead of his important work helping me.\n\nDon't let him prattle on about tradeskills, and find out what's happened to my books!" },
    { id = 95771, name = "A Taste of Darkness", level = 10, minLevel = 6 },
    { id = 99127, name = "A Net Disaster", level = 7, minLevel = 4, faction = "Alliance", giver = "Jason Mathers", start = { npc = "Jason Mathers", area = 12, x = 47.4, y = 62.2 }, finish = { npc = "Jason Mathers", area = 12, x = 47.4, y = 62.2 }, objective = "Check the fishing nets in Crystal Lake.", desc = "The fish just ain't biting today, and there's something wrong going on with them. It's not just empty hooks. I haven't seen a single minnow up in the water at all.\n\nLee here set up some traps overnight, go check to see if we've at least got some stock there. If you find anything weird, make sure to show me." },
    { id = 99128, name = "Slimy Menace", level = 7, minLevel = 4, faction = "Alliance", giver = "Jason Mathers", start = { npc = "Jason Mathers", area = 12, x = 47.4, y = 62.2 }, finish = { npc = "Jason Mathers", area = 12, x = 47.4, y = 62.2 }, steps = { { name = "Murloc", area = 12, x = 53.2, y = 66.7 }, { name = "Murloc Streamrunner", area = 12, x = 53.9, y = 65.9 } }, objective = "Kill the murlocs at Crystal Lake.", desc = "This can only be the work of those murlocs on the other side of the lake. They're disgusting little things, with a vicious temper and teeth to match.\n\nIf we let this continue, there won't be any fish to speak of anywhere in this lake. If you could clear them out a bit, it would help me a ton." },
    { id = 99129, name = "A Man About a Murloc", level = 7, minLevel = 4, faction = "Alliance", giver = "Jason Mathers", start = { npc = "Jason Mathers", area = 12, x = 47.4, y = 62.2 }, finish = { npc = "Remy \"Two Times\"", area = 12, x = 42.2, y = 67.2 }, desc = "Remy mentioned murlocs the other day... I'm pretty sure he hates the little buggers as much as I do.\n\nHe might have some ideas on how to keep them away from my fish in the future. I'd like to ask you to go chat with him and see if there's anything he can think of." },
    { id = 99130, name = "An Enticing Offer", level = 7, minLevel = 4, faction = "Alliance", giver = "Remy \\\"Two Times\\\"", start = { npc = "Remy \"Two Times\"", area = 12, x = 42.2, y = 67.2 }, finish = { npc = "Remy \"Two Times\"", area = 12, x = 42.2, y = 67.2 }, steps = { { name = "Vial of Animal Blood", area = 12, x = 35.1, y = 84.6 } }, objective = "Collect ingredients for murloc bait.", desc = "I've got a few ideas on how to deal with murlocs. And one of those also helps some others in the process.\n\nThere's a weed often found on farms in the area called duskweed, and in large quantities the petals are toxic to most animals. If we make some murloc bait with the plant, hopefully that can train those creatures to stay away.\n\nAnd some farmers get their fields cleared in the process. Truly a win-win... truly a win-win." },
    { id = 99131, name = "Baited for Success", level = 7, minLevel = 4, faction = "Alliance", giver = "Remy \\\"Two Times\\\"", start = { npc = "Remy \"Two Times\"", area = 12, x = 42.2, y = 67.2 }, finish = { npc = "Jason Mathers", area = 12, x = 47.4, y = 62.2 }, desc = "Tell Mathers he can come pick up the bait later today. I'll give him the rundown on the proper usage.\n\nHopefully he'll be able to sell his fish again soon. And we'll have less murlocs in this world." },
    { id = 99143, name = "Bottles and Baubles", level = 7, minLevel = 4, faction = "Alliance", giver = "Lee Brown", start = { npc = "Lee Brown", area = 12, x = 47.4, y = 62.2 }, finish = { npc = "Lee Brown", area = 12, x = 47.4, y = 62.2 }, objective = "Collect 6 pieces of shiny junk from the nearby Murloc camp.", desc = "Those fish men must think like actual fish, right? Which means anything they like, fish will like!\n\nIf you rummage through some of their junk and return to me with anything that seems like it would make good bait, I'll reward you." },
})

ns.AddQuests("z130", {
    { id = 91920, name = "Wild Eyes", level = 11, minLevel = 10, requires = { 430 }, faction = "Horde", giver = "Quinn Yorick", start = { npc = "Quinn Yorick", area = 130, x = 53.4, y = 12.6 }, finish = { npc = "Apothecary Renferrel", area = 130, x = 42.8, y = 40.8 }, steps = { { name = "Murloc Eye", area = 130, x = 60.7, y = 19.5 } }, objective = "Gather 3 murloc eyes and bring them to Apothecary Renferrel at the Sepulcher.", desc = "I wouldn't dare to question the effectiveness of Apothecary Renferrel's formulae, however I would be lying if I said that the potion made any noticeable difference.\n\nAlong the shore of Lake Lordamere are a swarm of murlocs, and of note, murlocs have eyes. I suspect the apothecary's willingness to try new things is suppressed by his recent obsession with hearts. Bring him a few.\n\nIf my choice is to inevitably die a second death or have Renferrel kill me for questioning his methods, I choose the latter." },
    { id = 91921, name = "Return to Quinn (Again)", level = 11, minLevel = 10, requires = { 91920 }, faction = "Horde", giver = "Apothecary Renferrel", start = { npc = "Apothecary Renferrel", area = 130, x = 42.8, y = 40.8 }, finish = { npc = "Quinn Yorick", area = 130, x = 53.4, y = 12.6 }, objective = "Bring Quinn's potion to Quinn Yorick at the Ivar Patch, north of the Sepulcher.", desc = "Here is the new potion to aid in Quinn's recovery, made with love extracted from six whole hearts.\n\nNow, please excuse me before your presence necessitates more paperwork." },
    { id = 95883, name = "The Tortured Soul", level = 23, minLevel = 20, requires = { 95884 }, faction = "Horde", steps = { { name = "Tortured Soul", area = 130, x = 59.2, y = 71.7 } }, objective = "Collect a Tortured Soul from the nearby undead in Beren's Peril in Silverpine Forest.", desc = "<The preparations for a hastily-assembled ritual are gathered unceremoniously on the altar. According to the scrap of note, everything has been gathered. All that's missing are the offering of blood and the Tortured Soul.\n\nThe undead around you look tortured enough. They may have what you seek.>" },
    { id = 95884, name = "The Offering Stone", level = 23, minLevel = 20, faction = "Horde", steps = { { name = "Note Scrap", area = 130, x = 59.2, y = 71.7 } }, objective = "Find the Offering Stone in Beren's Peril in Silverpine Forest.", desc = "<The scrap of note is mostly illegible. What is still readable, however, are notes about preparations for an offering.\n\nAn offering stone is mentioned, as well as a ritual.\n\nPerhaps you can find this offering stone nearby.>" },
    { id = 95885, name = "The Offering of Blood", level = 23, minLevel = 20, requires = { 95883 }, faction = "Horde", steps = { { name = "Tortured Soul", area = 130, x = 59.7, y = 72.5 } }, objective = "Use the Tortured Soul to give an offering of blood at the Offering Stone in Beren's Peril.", desc = "<All that's left now is the offering of blood.\n\nThe note scrap mentioned a 'willing sacrifice.'\n\nAn intense sense of dread washes over you.>" },
    { id = 95981, name = "Watching the Roads", level = 20, minLevel = 10, faction = "Horde", giver = "Shadow Priest Allister", start = { npc = "Shadow Priest Allister", area = 130, x = 44, y = 41 }, finish = { npc = "Shadow Priest Allister", area = 130, x = 44, y = 41 }, steps = { { name = "Dalaran Watcher", area = 130, x = 60.7, y = 77 }, { name = "Dalaran Wizard", area = 130, x = 62.3, y = 75.9 } }, objective = "Slay 8 Dalaran Wizards and 8 Dalaran Watchers for Shadow Priest Allister in the Sepulcher.", desc = "Taking away their pendants is just the first step. If the Kirin Tor really are shipping a steady supply of relics from Dalaran, we must stop them at the source.\n\nSearch the roads around Ambermill for Dalaran's wizards and watchers. Their presence has allowed free access across our borders for too long. If we can cull their numbers, that should put a stop to these pendants making it into Silverpine Forest in the first place." },
    { id = 98298, name = "Arugal's Folly (6/6)", level = 16, minLevel = 9, requires = { 99 }, faction = "Horde", giver = "Dalar Dawnweaver", start = { npc = "Dalar Dawnweaver", area = 130, x = 44.2, y = 39.8 }, finish = { npc = "Dalar Dawnweaver", area = 130, x = 44.2, y = 39.8 }, steps = { { name = "Worgen Bits", area = 130, x = 50.1, y = 78.8 } }, objective = "Bring 6 Worgen Bits to Dalar Dawnweaver in The Sepulcher.", desc = "Ah, it's all become so embarrassingly clear! Arugal hardly had any magic at all, let alone enough to create the worgen. 'Arugal's Curse.' Pah! Barely potent enough to last a few seconds.\n\nThese shackles prove he can bind the beasts, not create them. The worgen clearly spread their curse a different way. I would know how.\n\nGo to the Greymane Wall to the south. The worgen seem to be spreading to the humans nearby. Tear the beasts apart and bring me whatever you find. This requires a more direct approach." },
    { id = 98299, name = "Stop the Spread", level = 20, minLevel = 9, faction = "Horde", giver = "Dalar Dawnweaver", start = { npc = "Dalar Dawnweaver", area = 130, x = 44.2, y = 39.8 }, finish = { npc = "Dalar Dawnweaver", area = 130, x = 44.2, y = 39.8 }, steps = { { name = "Haggard Refugee", area = 130, x = 46.1, y = 84.4 }, { name = "Sickly Refugee", area = 130, x = 46, y = 84.3 } }, objective = "Slay 5 Sickly Refugees and 5 Haggard Refugees for Dalar Dawnweaver in The Sepulcher.", desc = "If there is one thing we do know, it is that Arugal is responsible for worgen within Silverpine--be it his own machinations or otherwise. What we don't know is how it spreads.\n\nWhile I research a way to stop the curse, our first priority is to contain it. It appears this affliction cannot infect forsaken, but a large group of humans have gathered by the Greymane Wall.\n\nGo to the wall and put down these refugees before they have a chance to become servants for Arugal. And try not to get bit, <race>." },
})

ns.AddQuests("z14", {
    { id = 96821, name = "Legging It", level = 6, minLevel = 1, faction = "Horde", giver = "Vel'rin Fang", start = { npc = "Vel'rin Fang", area = 14, x = 55.8, y = 74 }, finish = { npc = "Gar'Thok", area = 14, x = 52, y = 43.4 }, steps = { { name = "Ridgeshade Lurker", area = 14, x = 51.5, y = 57.5 }, { name = "Ridgeshade Creeper", area = 14, x = 51.3, y = 57.2 } }, objective = "Kill 6 Ridgeshade Creepers and 6 Ridgeshade Lurkers in southern Durotar, then report to Gar'thok in Razor Hill.", desc = "We be seein' fewer and fewer travelers from Razor Hill. The scorpids were never much fun, but now I be hearin' there be spiders makin' their nest along the road.\n\nIf your travels be takin' you up north, kill some of the spiders on your way. Then, let Razor Hill know the path's a bit safer for them." },
    { id = 96822, name = "For Honor", level = 6, minLevel = 3, faction = "Horde", giver = "Turroc", start = { npc = "Turroc", area = 14, x = 54, y = 42.6 }, finish = { npc = "Turroc", area = 14, x = 54, y = 42.6 }, objective = "Collect the Raider's Battleaxe, Raider's Bow, and Raider's Shield from the Tiragarde Keep outskirts, then return them to Turroc in Razor Hill.", desc = "We lost many brave warriors of the Horde when we sacked Tiragarde Keep. Now that the humans have reinforced the ruins, we cannot collect their remains to properly honor their deaths.\n\nGo to the ruins surrounding the keep, and search for the weapons left by our fallen kin. We will display them in a place of honor." },
    { id = 96825, name = "This Fruit Could Bite Back", level = 6, minLevel = 3, faction = "Horde", giver = "Cook Torka", start = { npc = "Cook Torka", area = 14, x = 51.2, y = 42.4 }, finish = { npc = "Cook Torka", area = 14, x = 51.2, y = 42.4 }, objective = "Cook Torka in Razor Hill wants you to collect 8 Prickly Pear Fruit from the Razormane Grounds west of town.", desc = "Our hunters and fishers bring back plenty of savory food for our troops - but it's rare that they get a sweet treat.\n\nI've seen a cactus that produces a prickly, tasty fruit. But it only grows in the hills to the west, where the wretched quilboars make their camps. Make your way past the quilboars and bring me some of those fruits. And be careful - the fruits are as spiny as the quilboars!" },
    { id = 96873, name = "A Pain in the Neck", level = 8, minLevel = 5, faction = "Horde", giver = "Pa'zula", start = { npc = "Pa'zula", area = 14, x = 56.6, y = 73.6 }, finish = { npc = "Pa'zula", area = 14, x = 56.6, y = 73.6 }, objective = "Pa'zula in Sen'jin Village wants you to collect 3 Luminous Residue. Luminous Residue can be obtained by disenchanting Hexed Pendants dropped by trolls in the Echo Isles.", desc = "The trolls east of here have lost their will to the witchdoctor, Zalazane. He uses many cruel magics to keep hold of his prisoners' minds, but one of his favorite tricks is to make them wear pendants wrapped in evil binding spells.\n\nPractice your enchanting skills by stripping the magic from these pendants, and bring me the results. And don't accidentally put one around your neck, if you value your freedom!" },
    { id = 96874, name = "This Is Spinal Axe", level = 10, minLevel = 6, faction = "Horde", giver = "Ug'thok", start = { npc = "Ug'thok", area = 1637, x = 80.6, y = 23.4 }, finish = { npc = "Ug'thok", area = 1637, x = 80.6, y = 23.4 }, steps = { { name = "Weathered Spine", area = 14, x = 40.4, y = 26.2 } }, objective = "Ug'thok in Orgrimmar wants you to collect 5 Weathered Spines from beasts in Thunder Ridge, along with 5 Rough Grinding Stones.", desc = "Have you seen the huge beasts of Thunder Ridge? I keep thinking the spines on their backs would be perfect for crafting the head of a mighty axe. Saru laughed when I told him... but what does he know!?\n\nAs part of your smithing lessons, you can help me out! Bring me some of those spines, along with grinding stones to sharpen them." },
    { id = 96875, name = "Beasts of Thunder Ridge", level = 10, minLevel = 6, faction = "Horde", giver = "Kamari", start = { npc = "Kamari", area = 1637, x = 63, y = 45 }, finish = { npc = "Kamari", area = 1637, x = 63, y = 45 }, steps = { { name = "Rough Lizard Hide", area = 14, x = 40.4, y = 26.2 } }, objective = "Kamari in Orgrimmar wants you to collect 5 Rough Lizard Hide from beasts in Thunder Ridge, along with 2 Cured Light Hides.", desc = "Orgrimmar is always expanding, <class>. And when the peons need hides to line the walls and roofs of our new buildings, they come to me!\n\nThe hides of the lizards in Thunder Ridge are typically too thick for armor, but they make excellent building material. Bring me some of their hides, along with a few lighter cured hides. Let's see your skill with leather!" },
    { id = 96876, name = "Ukor's Lost Pack", level = 8, minLevel = 5, faction = "Horde", finish = { npc = "Ukor", area = 14, x = 52, y = 68.2 }, objective = "Return the pack to Ukor in southern Durotar.", desc = "The pack has the name \"Ukor\" crudely stitched along the flap." },
    { id = 96877, name = "Halikor's Hoof", level = 12, minLevel = 6, faction = "Horde", finish = { npc = "Kamari", area = 1637, x = 63, y = 45 }, objective = "Deliver Halikor's Hoof to Orgrimmar.", desc = "The enormous hoof serves as proof of your victory over the mighty lizard." },
    { id = 97223, name = "Bloodtalon Matriarch", level = 8, minLevel = 5, faction = "Horde", giver = "Xar'Ti", start = { npc = "Xar'Ti", area = 14, x = 55.2, y = 75.4 }, finish = { npc = "Xar'Ti", area = 14, x = 55.2, y = 75.4 }, steps = { { name = "Bloodtalon Martriarch Eggs", area = 14, x = 68.6, y = 71.7 } }, objective = "Bring Eggs of the Bloodtalon Matriarch to Xar'Ti in Sen'jin Village.", desc = "All of the raptors you see before you are ones I have trained myself. They come from all over Kalimdor, but some of the finest come from the Bloodtalon raptors on the isles off our coast.\n\nOne raptor amongst them, the Bloodtalon Matriarch, is particularly savage and has killed many from our village and has become too dangerous to leave at our borders. If you can strike her down, return with her eggs so that we can raise the hatchlings as allies instead of enemies." },
    { id = 97225, name = "Forgotten Loa Idols", level = 9, minLevel = 4, faction = "Horde", giver = "Master Vornal", start = { npc = "Master Vornal", area = 14, x = 55.8, y = 74.4 }, finish = { npc = "Master Gadrin", area = 14, x = 56, y = 74.6 }, objective = "Collect 8 Forgotten Loa Idols from the Echo Isles. Bring them to Master Gadrin in Sen'jin Village.", desc = "When we fled the isles that Zalazane and his ilk now inhabit, we left behind many precious idols that help us commune with spirits we worship: our loa. They are of grave importance to our tribe.\n\nThe followers of Zalazane show no reverence for our loa and have scattered these idols across the largest of the isles.\n\nThis is an action that will not go unnoticed if we are not able to collect these idols, and offending a loa is a grave matter.\n\nGo, find as many loa idols as you can and return them to me." },
    { id = 97279, name = "Wayward Weapons", level = 2, minLevel = 1, faction = "Horde", giver = "Gornek", start = { npc = "Gornek", area = 14, x = 42, y = 68.4 }, finish = { npc = "Kzan Thornslash", area = 14, x = 40.4, y = 68 }, objective = "Collect 6 Abandoned Training Weapons, then return to Kzan Thornslash in the Den.", desc = "With an influx of new recruits like yourself, it's been hard to keep our weapons supplied. Our weaponsmith, Kzan, is running low on training weapons and I'd like to see what kinds of skills you possess to get an idea of what I have to work with. Luckily for you, I have a solution to both.\n\nWhile you're out there cutting your teeth on boars, salvage six abandoned training weapons. Our failed recruits left them laying on the ground. Once you do, return them to our weaponsmith Kzan behind me in the Den." },
    { id = 97281, name = "A Simmering Storm", level = 11, minLevel = 7, faction = "Horde", finish = { npc = "Rezlak", area = 14, x = 46.4, y = 23 }, desc = "<Before you is a strange orb and with a dull surface. When picked up a small electrical current seems to vibrate from within. Upon closer inspection, it looks as if a dark mist swirls within and every so often a small electrical spark can be seen.\n\nIt is clear the harpy was using it for some purpose. Perhaps Rezlak would be interested in this object?>" },
    { id = 97282, name = "Stormy Potential", level = 11, minLevel = 7, requires = { 97281 }, faction = "Horde", giver = "Rezlak", start = { npc = "Rezlak", area = 14, x = 46.4, y = 23 }, finish = { npc = "Rezlak", area = 14, x = 46.4, y = 23 }, steps = { { name = "Charged Thunder Lizard Organ", area = 14, x = 40.4, y = 26.2 } }, objective = "Bring 5 Charged Thunder Lizard Organs to Rezlak near Drygulch Ravine.", desc = "\"Rezlack, when an opportunity come's knocking make sure you're ready to seize it.\" That's another gem Gazlowe taught me and that's exactly what I intend to do.\n\nThis orb doesn't seem damaged, it just looks like it's out of juice, but I've the idea to supercharge it back to full strength!\n\nThere are a bunch of thunder lizards in a gorge west of here. They have organs that hold a strong electrical charge that would be perfect for this.\n\nGo harvest some and bring them back to me!" },
    { id = 99048, name = "A Missing Hand", level = 11, minLevel = 9, faction = "Horde", giver = "Orgnil Soulscar", start = { npc = "Orgnil Soulscar", area = 14, x = 52.2, y = 43.2 }, finish = { npc = "Heglan Shadeeye", area = 14, x = 58.6, y = 45.6 }, desc = "A member of the Shattered Hand, a group of more... subtle fighters, was watching Tiragarde Keep from a distance. Her reports suddenly stopped coming in.\n\nI doubt the humans would have caught her, so I'm concerned something more dangerous is at play. See if you can find her. Hopefully the messages are just delayed." },
    { id = 99049, name = "Threat from Below", level = 11, minLevel = 9, faction = "Horde", giver = "Heglan Shadeeye", start = { npc = "Heglan Shadeeye", area = 14, x = 58.6, y = 45.6 }, finish = { npc = "Orgnil Soulscar", area = 14, x = 52.2, y = 43.2 }, objective = "Find signs of what attacked Heglan Shadeeye.", desc = "<The nearby area is destroyed with obvious signs of a skirmish. Whatever ambushed Heglan didn't make it out unscathed. There's probably signs nearby of what happened.\n\nOrgnil will probably want to see any evidence left by the attackers.>" },
    { id = 99051, name = "Threat from Below", level = 11, minLevel = 9, faction = "Horde", giver = "Orgnil Soulscar", start = { npc = "Orgnil Soulscar", area = 14, x = 52.2, y = 43.2 }, finish = { npc = "Orgnil Soulscar", area = 14, x = 52.2, y = 43.2 }, steps = { { name = "Naga Spinefin", area = 14, x = 58.5, y = 26.1 } }, objective = "Collect 9 Naga Spinefins.", desc = "It wouldn't be the first time those snakes bothered us. They need to be taught that their presence is not tolerated here.\n\nFind where their scouts are setting up camp and slaughter them. Bring me back their fins as proof. We need to act fast to make sure they understand." },
    { id = 99052, name = "Threat from Below", level = 12, minLevel = 10, faction = "Horde", giver = "Orgnil Soulscar", start = { npc = "Orgnil Soulscar", area = 14, x = 52.2, y = 43.2 }, finish = { npc = "Orgnil Soulscar", area = 14, x = 52.2, y = 43.2 }, steps = { { name = "Aggor's Belt", area = 14, x = 58.9, y = 16.9 } }, objective = "Kill the sea giant along Durotar's north coast and bring back proof of your accomplishment.", desc = "One of my scouts has reported a sea giant followed those naga down here. Not sure if they brought him intentionally or what, but he's dangerous in any case.\n\nIt's a young one, but it could still rip an orc in half in a heartbeat if they were caught off guard. I need him gone. But I'd suggest you find some help to deal with it." },
    { id = 99123, name = "Lost in the Shadows", level = 8, minLevel = 4, faction = "Horde", giver = "Pal'juh", start = { npc = "Pal'juh", area = 14, x = 46.2, y = 78.6 }, finish = { npc = "Master Vornal", area = 14, x = 55.8, y = 74.4 }, objective = "Help Pal'juh escape Kolkar Crag and bring news of your success to Master Vornal in Sen'jin Village.", desc = "I decided to do a bit of scouting in the crag on my own. Unfortunately my magic ran out at the wrong time and I've been stuck hiding here since.\n\nIf you could help me escape, I would appreciate it." },
})

ns.AddQuests("z141", {
    { id = 87288, name = "Soft Saber Pelts", level = 7, minLevel = 4, faction = "Alliance", giver = "Aldia", start = { npc = "Aldia", area = 141, x = 55.4, y = 57.2 }, finish = { npc = "Aldia", area = 141, x = 55.4, y = 57.2 }, steps = { { name = "Soft Nightsaber Pelt", area = 141, x = 56.1, y = 58.3 } }, objective = "Bring 6 Soft Nightsaber Pelts to Aldria.", desc = "Hello, traveler! I hope you are enjoying your visit to our village. I like Dolanaar because it is small and rustic and everyone is friendly.\n\nI'm a local trader, and I bring in all sorts of tools and trinkets that might be useful to you in your travels. Indeed, if you are interested in a trade, I find myself in need of some nightsaber pelts. While these majestic creatures are beautiful, the local ones are rather aggressive, so don't feel too bad about defending yourself." },
    { id = 97236, name = "Fang of Githyiss", level = 5, minLevel = 1, faction = "Alliance", finish = { npc = "Gilshalan Windwalker", area = 141, x = 57.8, y = 41.6 }, desc = "A fresh specimen from a beast of this size is quite a find. Perhaps someone in Aldrassil familiar with the study of spiders would be interested in the fang." },
    { id = 97977, name = "Nature's Call", level = 3, minLevel = 1, faction = "Alliance", giver = "Tarindrella", start = { npc = "Tarindrella", area = 141, x = 57.8, y = 45 }, finish = { npc = "Tarindrella", area = 141, x = 57.8, y = 45 }, objective = "Collect 4  Gnarlpine Totems and bring them to Tarindrella.", desc = "The Gnarlpine furbolg would not turn on their ancient allies so readily. We must learn more of their plight.\n\nSearch their abandoned homes for totems. If any survived the chaos of their departure, their engravings may tell us more of what happened here.\n\nYou'll find their camps along the western edge of the glen, though the grell and grellkin may have scattered them beyond." },
    { id = 97979, name = "The Goddess Provides", level = 1, minLevel = 1, faction = "Alliance", giver = "Shanda", start = { npc = "Shanda", area = 141, x = 59.2, y = 40.4 }, finish = { npc = "Shanda", area = 141, x = 59.2, y = 40.4 }, objective = "Cast Elune's Light and Shadowmeld.", desc = "You are born kaldorei--the children of the stars--and have inherited a birthright unlike any other in this world. Elune's grace may illuminate our strengths, helping our strikes hit true, or it may help conceal us just as the moon may eclipse the sun.\n\nOur Long Vigil after the defense of Mount Hyjal has ended, and we have joined an Alliance of others--which you will meet in due time. For now, you are nestled in the boughs of Teldrassil.\n\nDemonstrate Mother Moon's gifts, and bask in her blessings." },
    { id = 98046, name = "Crown of the Earth (1/2)", level = 11, minLevel = 1, faction = "Alliance", giver = "Arch Druid Fandral Staghelm", start = { npc = "Arch Druid Fandral Staghelm", area = 1657, x = 34.8, y = 8.8 }, finish = { npc = "Lariia", area = 1657, x = 40.2, y = 88.4 }, objective = "Bring the Drained Vessel to Lariia in the Temple of the Moon in Darnassus.", desc = "<Arch Druid Fandral Staghelm's gaze narrows.>\n\nYou're still here?\n\nTake the phial and get out of my sight, <class>. It is clear my answers do not lie in the waters, just as they did not before.\n\nPerhaps one of the priestesses in the Temple of the Moon to the south will dispose of it.\n\n<Fandral looks away, no longer speaking to you.>\n\nI must look elsewhere if this is to work..." },
    { id = 98065, name = "Crown of the Earth (2/2)", level = 11, minLevel = 1, requires = { 98046 }, faction = "Alliance", giver = "Lariia", start = { npc = "Lariia", area = 1657, x = 40.2, y = 88.4 }, finish = { npc = "Tyrande Whisperwind", area = 1657, x = 39, y = 81.2 }, objective = "Bring the Moonwell Remnants to Tyrande Whisperwind in the Temple of the Moon in Darnassus.", desc = "You must bring this to Tyrande at once! I will transfer it to a more ceremonial container for you.\n\nDo not be afraid. The High Priestess of Elune is firm, but kind. She protects all who enter Darnassus, and carries our goddess' light to all.\n\nShe will be glad to receive this sacred water. You will find her directly above us." },
    { id = 98392, name = "Darkness in the Glade", level = 12, minLevel = 6, requires = { 937 }, faction = "Alliance", giver = "Sentinel Arynia Cloudsbreak", start = { npc = "Sentinel Arynia Cloudsbreak", area = 141, x = 38.2, y = 34.4 }, finish = { npc = "Sentinel Arynia Cloudsbreak", area = 141, x = 38.2, y = 34.4 }, steps = { { name = "Hatescreech's Amulet", area = 141, x = 35.2, y = 38.6 }, { name = "Windmistress Gaedress' Amulet", area = 141, x = 33.7, y = 35.6 }, { name = "Witchmother Arysa's Amulet", area = 141, x = 34.5, y = 28.3 } }, objective = "Collect Hatescreech's Amulet, Windmistress Gaedress' Amulet, and Witchmother Arysa's Amulet for Sentinel Arynia Cloudsbreak in the Oracle Glade.", desc = "These belts... look closely at the leather, <name>. Do you see the taint running through the fibers?\n\nI have a suspicion as to its origin, but we will need further proof to be sure.\n\nVenture back out into the harpies' nests to the west and take out their leaders. If their necklaces carry the same darkness as these belts, we'll have our answer." },
    { id = 98398, name = "The Oracle Tree", level = 12, minLevel = 6, requires = { 98392 }, faction = "Alliance", giver = "Sentinel Arynia Cloudsbreak", start = { npc = "Sentinel Arynia Cloudsbreak", area = 141, x = 38.2, y = 34.4 }, desc = "I am impressed by what you have accomplished here in so short a time, <name>. Would that I could ask you to remain here to assist me with my duties... but I know in my heart that greater tasks lie ahead for you.\n\nI have noticed the Oracle Tree has just shed a piece of its bark. No doubt it has a task that it wishes completed. You should speak with it." },
    { id = 98403, name = "Twisted Hatred (2/2)", level = 12, minLevel = 4, requires = { 932 }, faction = "Alliance", giver = "Tallonkai Swiftroot", start = { npc = "Tallonkai Swiftroot", area = 141, x = 55.4, y = 56.8 }, finish = { npc = "Tallonkai Swiftroot", area = 141, x = 55.4, y = 56.8 }, steps = { { name = "Mature Fel Moss", area = 141, x = 51.4, y = 44.5 }, { name = "Befouled Webwood", area = 141, x = 50, y = 45.2 } }, objective = "Kill 8 Befouled Webwoods and bring Xethorr the Wicked's Mature Fel Moss to Tallonkai Swiftroot in Dolanaar.", desc = "Lord Melenas did not act alone; he was at the behest of another. The one you seek is Xethorr the Wicked. It seems he has twisted the spiders that call Teldrassil home, intending their venom for some foul plan.\n\nHe has taken residence deep in the forest, in the area to the northwest of here known as the Cleft. Take caution, and bring allies, for Xethorr is not an opponent to be trifled with.\n\nDispatch his brood, and bring me anything that may tell us more of the satyr's work here." },
    { id = 99046, name = "The Lost Runner", level = 9, minLevel = 4, faction = "Alliance", giver = "Sentinel Kyra Starsong", start = { npc = "Sentinel Kyra Starsong", area = 141, x = 56, y = 59.4 }, finish = { npc = "Sentinel Eralya Leafshadow", area = 141, x = 37.6, y = 36.8 }, desc = "The Council of the Forest sent a small group of sentinels to the Oracle Tree some time ago. The tree sends messages to our elders, and it falls to us to deliver them to Darnassus safely.\n\nI received word that our most recent runner has not yet arrived. The Oracle's messages vary in frequency, but it has been abnormally long.\n\nPlease head towards the Oracle Glade along the road to to the west and check on her. It would have been Eralya Leafshadow's turn, and she is still in training. Elune guide you." },
    { id = 99047, name = "Not Dead Yet", level = 9, minLevel = 4, requires = { 99046 }, faction = "Alliance", giver = "Sentinel Eralya Leafshadow", start = { npc = "Sentinel Eralya Leafshadow", area = 141, x = 37.6, y = 36.8 }, finish = { npc = "Byancie", area = 141, x = 55.2, y = 56.8 }, desc = "My sisters and I... were dispatched... Oracle Tree...\n\nTree... message. I... harpies... everywhere...\n\n<Eralya coughs up blood, grimacing through the pain.>\n\nI may not have long... no one coming. Please... Byancie... in Dolanaar..." },
    { id = 99050, name = "The Great Tree Provides", level = 10, minLevel = 4, requires = { 99047 }, faction = "Alliance", giver = "Byancie", start = { npc = "Byancie", area = 141, x = 55.2, y = 56.8 }, finish = { npc = "Byancie", area = 141, x = 55.2, y = 56.8 }, steps = { { name = "Dewy Lasher Frond", area = 141, x = 56.4, y = 69 }, { name = "Refreshing Spring Water", area = 141, x = 37.7, y = 33.8 } }, objective = "Collect 6 Dewy Lasher Fronds, an Empty Vial, and a Refreshing Spring Water for Byancie in Dolanaar.", desc = "I will need your help acquiring the ingredients I need to stop the affliction long enough for Eralya to make it back here for further treatment.\n\nThankfully, our living home is still bountiful and will provide in our time of need.\n\nThe core ingredient is dewy lasher fronds. You'll find them around Lake Al'Ameth directly south of here, or Wellspring Lake and its river to the northwest.\n\nIn addition, I'll need an empty vial and some spring water. Both can be bought here in town, or traded for." },
    { id = 99053, name = "Escaping Ban'ethil", level = 9, minLevel = 4, faction = "Alliance", giver = "Sentinel Lynessa Duskblossom", start = { npc = "Sentinel Lynessa Duskblossom", area = 141, x = 43.3, y = 58.7 }, finish = { npc = "Sentinel Kyra Starsong", area = 141, x = 56, y = 59.4 }, objective = "Help Sentinel Lynessa Duskblossom escape Ban'ethil Barrow Den, and report her is safety to Sentinel Kyra Starsong in Dolanaar.", desc = "My prayers have been answered! I am thankful that you have fought your way down here.\n\nI was sent here by the Oracle Tree to deliver a message to the slumbering druids here only to find it completely overrun by furbolg! They ambushed me before I could turn back and brought me down here--I fear for their next meal.\n\nI don't know about you, but I loathe this place. Under the earth is no place for the kaldorei." },
    { id = 99073, name = "Easing Suffering", level = 10, minLevel = 4, faction = "Alliance", giver = "Byancie", start = { npc = "Byancie", area = 141, x = 55.2, y = 56.8 }, finish = { npc = "Sentinel Eralya Leafshadow", area = 141, x = 37.6, y = 36.8 }, objective = "Take the Lashwater Salve to Sentinel Eralya Leafshadow on the road to the Oracle Tree.", desc = "The salve is ready. Take it to Eralya swiftly.\n\nI do not know if it will truly cure her. The rot festers quickly, and grows in strength as it spreads.\n\nIt will, if nothing else, ease her suffering. And that is still worth your haste." },
})

ns.AddQuests("z148", {
    { id = 87760, name = "Holy Diver", level = 20, minLevel = 15, faction = "Alliance", giver = "Gwennyth Bly'Leggonde", start = { npc = "Gwennyth Bly'Leggonde", area = 148, x = 36.6, y = 45.4 }, finish = { npc = "Gwennyth Bly'Leggonde", area = 148, x = 36.6, y = 45.4 }, steps = { { name = "Rod of Deep Dominion", area = 148, x = 49.3, y = 12.5 } }, objective = "Find a Stormscale Beastmistress, slay her, and bring back her Rod of Deep Dominion.", desc = "I have received word back from Darnassus, <name>!\n\nFrom the animal samples, we learned that the naga dominated these sea creatures to use as unwilling mounts and beasts of burden. The ones that were too obstinate, or too old or badly injured, they drove out for sport. Monstrous!\n\nIt is our sacred duty to put a stop to this!\n\nThe naga have forces in the Ruins of Mathystra, and they must be seizing threshers from off the shore. Find their beastmistress, slay her, and bring back her tools of domination!" },
    { id = 97894, name = "Business in Auberdine", level = 17, minLevel = 13, faction = "Alliance", giver = "Borgus Steelhand", start = { npc = "Borgus Steelhand", area = 1519, x = 59.4, y = 34.2 }, finish = { npc = "Gorbold Steelhand", area = 148, x = 38, y = 41.2 }, objective = "Check on Gorbold Steelhand in Auberdine in Darkshore.\n\nBorgus mentioned a boat on the southern-most dock in Stormwind Harbor that can take you there.", desc = "Pleasure to make yer acquaintance! Name's Borgus, of the one and only Steelhand family. You can always count on a Steelhand fer a fair deal!\n\nA few weeks back me brother Gorbold joined up with a merchant stall in Auberdine. Plenty of coin to be made supplyin' ships there, let me tell you! Lucky sod.\n\nI haven't heard from him since--mind checking on him if yer heading that way?\n\nThere's a new ship in the harbor that will take ye straight there. Head to the southern-most dock; can't miss it!" },
    { id = 97926, name = "Making Do", level = 17, minLevel = 13, requires = { 97914 }, faction = "Alliance", giver = "Baros Alexston", start = { npc = "Baros Alexston", area = 1519, x = 57.6, y = 47.8 }, finish = { npc = "Thundris Windweaver", area = 148, x = 37.4, y = 40.2 }, objective = "Bring Alexston's Reply to Thundris Windweaver in Auberdine in Darkshore.", desc = "I wish it was that easy to help, <class>. I really do.\n\nShould you choose to spend more time in our lands, you will find that many are without. Stormwind's coffers are not what they once were, and what remains is spread thin.\n\nGive this reply to the elder the next time you see him. It's not what he's hoping for, but it's all I have to offer right now." },
    { id = 98013, name = "Swelling Forces", level = 20, minLevel = 12, faction = "Alliance", giver = "Arbal", start = { npc = "Arbal", area = 148, x = 43.6, y = 76.4 }, finish = { npc = "Arbal", area = 148, x = 43.6, y = 76.4 }, steps = { { name = "Stormscale Myrmidon", area = 148, x = 58.7, y = 20.3 }, { name = "Stormscale Sorceress", area = 148, x = 59.3, y = 20.2 }, { name = "Stormscale Warrior", area = 148, x = 60.9, y = 20.4 } }, objective = "Eliminate 12 Stormscale Myrmidons, 8 Stormscale Sorceresses, and 6 Stormscale Warriors for Arbal at the Grove of the Ancients.", desc = "Steel yourself for your time in the ruins, young one... you will not be granted free passage there.\n\nScores of cursed Highborne, now known as naga, roam the once great city. Travel northeast and dispatch them from this land.\n\nWhat they once were... is no more. If they aid the Twilight's Hammer, they can bring only further pain to the forests that once gave them shelter.\n\nWar is what they seek, <class>. War... is what we will bring." },
    { id = 98025, name = "WANTED: Jai'vhanel", level = 13, minLevel = 10, faction = "Alliance", giver = "WANTED: Murkdeep!", start = { npc = "WANTED: Murkdeep!", area = 148, x = 37.2, y = 44.2 }, finish = { npc = "Sentinel Glynda Nal'Shea", area = 148, x = 37.6, y = 43.4 }, steps = { { name = "Feather of Jai'vhanel", area = 148, x = 45, y = 58.4 } }, objective = "Find and slay the owl known as Jai'vhanel and take one of her feathers. The black owl was last seen north of the Ameth'Aran ruins near the mountain base. Report the death of Jai'vhanel to Sentinel Glynda Nal'Shea in Auberdine.", desc = "Attention!\n\nA reward is being offered for the death of the owl \"Jai'vhanel\" also know as \"Swordfeather\".\n\nUnfortunately this owl has gone mad and has begun to attack travelers as they journey along the road near Auberdine.\n\nJai'vhanel was last seen north of the Ameth'Aran ruins near the mountain base. Bring back one of her jet black feathers as proof of her death.\n\nReward claims for this bounty should be claimed with Sentinel Glynda Nal'Shea in Auberdine.\n\nThe Auberdine Village Council" },
    { id = 98028, name = "Baron Marinous", level = 21, minLevel = 17, faction = "Alliance", finish = { npc = "Onu", area = 148, x = 43.6, y = 76.4 }, objective = "Bring the Clouded Water Globe to Onu at the Grove of the Ancients in Darkshore.", desc = "All that remains of the powerful elemental is a globe of what seems to be pure water, clouded by some unknown substance. The edges of the sphere seem to be clear until you turn it--as if the cloud actively prevents you from peering within.\n\nWhatever happened to it--and to the ruins it was guarding--is still active in some way.\n\nOnly Onu, the Ancient of Lore at the Grove of the Ancients to the far south, would have a chance at knowing more." },
    { id = 98042, name = "It's All Fun and Games Until...", level = 17, minLevel = 12, faction = "Alliance", giver = "Twilight Tome", start = { npc = "Twilight Tome", area = 148, x = 38.6, y = 86.1 }, finish = { npc = "Thundris Windweaver", area = 148, x = 37.4, y = 40.2 }, steps = { { name = "Peerless Eye", area = 148, x = 38.9, y = 86.5 } }, objective = "Obtain a Peerless Eye from a Twilight Disciple or Thug at the Master's Glaive in Darkshore and find someone in Auberdine who is willing to take it.", desc = "<As you tear away the single page from the Twilight Tome, a foreboding voice floods your mind, uninvited.>\n\nThey have failed.\n\nYou will be forgotten.\n\nThey will lose the eye they gained." },
})

ns.AddQuests("z1497", {
    { id = 97583, name = "WRIGGLE.", level = 1, minLevel = 1, faction = "Horde", giver = "Excitable Slime", start = { npc = "Excitable Slime", area = 1497, x = 51.6, y = 58.8 }, finish = { npc = "Excitable Slime", area = 1497, x = 51.6, y = 58.8 }, objective = "Purchase Nutritious Slime Sludge and return to your befriended excitable slime. If it seems tired, try dancing with it again to catch its attention.", desc = "<The little slime seems delighted and is attempting to mirror your motions as you dance. It begins to look weary though.\n\nThe little slime hovers over a bit of sludge and absorbs it, looking slightly rejuvenated.\n\nIt seems all of this dancing has tuckered it out. Perhaps someone in the Undercity canals sells more of this nutritious sludge?>" },
    { id = 97891, name = "Prompt Potion Runner", level = 16, minLevel = 9, faction = "Horde", giver = "Alessandro Luca", start = { npc = "Alessandro Luca", area = 1497, x = 58.2, y = 55.2 }, finish = { npc = "Doctor Martin Felben", area = 1497, x = 46.6, y = 74.4 }, steps = { { name = "Doctor Martin Felben", area = 1497, x = 46.4, y = 74.2 } }, objective = "Bring the Unstable Potion to Doctor Martin Felben in the Apothecarium within the time limit.", desc = "You! Quickly, I need you to bring this potion across the slime canal to Doctor Martin Felben in the Apothecarium!\n\nIt has a very limited shelf life, and no I can't go myself, my knees rattle and pop out if I attempt to run.\n\nJust another lovely side effect of undeath, apparently.\n\nBut we're wasting time! Here, take this and go!\n\n<Alessandro makes a shooing motion.>" },
})

ns.AddQuests("z1519", {
    { id = 93963, name = "Exploring the Alliance", level = 13, minLevel = 7, requires = { 94947 }, faction = "Alliance", giver = "Highlord Bolvar Fordragon", start = { npc = "Highlord Bolvar Fordragon", area = 1519, x = 80, y = 38.4 }, finish = { npc = "Highlord Bolvar Fordragon", area = 1519, x = 80, y = 38.4 }, steps = { { name = "King Magni Bronzebeard", area = 1537, x = 39.6, y = 55.5 }, { name = "High Tinker Mekkatorque", area = 1537, x = 69.4, y = 49.1 }, { name = "Tyrande Whisperwind", area = 1657, x = 39, y = 80.8 }, { name = "Randal Emerson", area = 1519, x = 80.9, y = 58.9 } }, objective = "Speak with Randal Emerson in Stormwind Keep to receive further instructions. Use the instructions received to locate and speak with King Magni Bronzebeard, High Tinker Mekkatorque, and Tyrande Whisperwind.", desc = "Stormwind, Ironforge, and Darnassus all have unique peoples and cultures. As a guest of the Alliance here on Azeroth, you should take some time to visit each of our capital cities in turn.\n\nSpeak with Randal Emerson in the southern antechamber for directions to get you started." },
    { id = 94947, name = "Welcome to Azeroth", level = 13, minLevel = 7, requires = { 94946 }, faction = "Alliance", giver = "Denaaris Stargale", start = { npc = "Denaaris Stargale", area = 36, x = 12.4, y = 56.2 }, finish = { npc = "Highlord Bolvar Fordragon", area = 1519, x = 80, y = 38.4 }, objective = "Take the Skyborne Portal to Stormwind and report to Bolvar Fordragon in Stormwind Keep.", desc = "Its a big world down here, and we need our people to start branching out to explore it. That's where you come in.\n\nThe Kirin Tor is a member of an \"Alliance\" of like-minded nations. The de-facto heart of this alliance is the city of Stormwind to the south. Elaadrin has asked me to find someone to travel to Stormwind and meet with the regent lord there, a human named Bolvar Fordragon.\n\nWhen you are ready, the Kirin Tor mages have set up a special portal for the High Order to use to access Stormwind." },
    { id = 95065, name = "Fishin' Time", level = 12, minLevel = 7, faction = "Alliance", giver = "Gilbert Gray", start = { npc = "Gilbert Gray", area = 1519, x = 40, y = 60.8 }, finish = { npc = "Gilbert Gray", area = 1519, x = 40, y = 60.8 }, objective = "Bring 1 Shiny Bauble and 3 Nightcrawlers to Gilbert Gray at the harbor in Stormwind.", desc = "What a view... Best an old man can ask for.\n\nThe fish sure are bitin' now, though I'm down to my last bait. I don't suppose you have any spare fishing supplies on you? Of course not, forgive me. I get so excited at the thought of casting another line it didn't dawn on me I may be one of the few carrying supplies everywhere I go.\n\nWould you be able to help refresh my stock? Catherine Leland has an assortment of fishing goods just west of the Trade District along the canals. Tell her old Gray sent you." },
    { id = 97220, name = "Philmor's Favor", level = 15, minLevel = 9, faction = "Alliance", giver = "Manifest Clerk Philmor", start = { npc = "Manifest Clerk Philmor", area = 1519, x = 43.2, y = 46.9 }, finish = { npc = "Elaine Trias", area = 1519, x = 66.4, y = 73.5 }, objective = "Bring the Gatehouse Shipment to the stockroom entrance located in Trias' Cheese shop in the Trade District", desc = "Every day this week we've been short dockhands.\n\nCare to ease the stress on our cargo schedule?\n\nTake this package to the stockroom entrance of the Gatehouse. You'll find it inside Trias' Cheese shop on the second floor. The mistress, Elaine, will be quite familiar with the deliveries. The Gatehouse often has shipments arriving with more discretion to allow for ceremonial surprises on behalf of the guard's officers." },
    { id = 97222, name = "Gatehouse Goods", level = 15, minLevel = 9, requires = { 97220 }, faction = "Alliance", giver = "Elaine Trias", start = { npc = "Elaine Trias", area = 1519, x = 66.4, y = 73.5 }, finish = { npc = "Elaine Trias", area = 1519, x = 66.4, y = 73.5 }, objective = "Carry the Gatehouse Shipment up the stairs in Trias' shop and leave it outside the door.", desc = "Yes, it's only a flight of stairs, but if it's such a small ask, it should be no problem for you to finish the delivery yourself!\n\nTrias' Cheese isn't part of the Gatehouse or their stocking inventory, but our buildings share a floor.\n\nPlace the crate outside their stockroom door--the guard will send someone for a regular pickup. They will see the package arrival and carry it inside as they return to post." },
    { id = 97234, name = "Reading Room", level = 18, minLevel = 13, faction = "Alliance", giver = "Roy Lewells", start = { npc = "Roy Lewells", area = 1519, x = 49.5, y = 72.4 }, finish = { npc = "Donyal Tovald", area = 1519, x = 75.1, y = 30.2 }, objective = "Bring the wrapped reading material to the Stormwind library.", desc = "Are you here to discuss the deeper meanings of our storied legends? No?\n\nWell, after you're done looking around, can you carry this to the library for me? We're exchanging some of our less popular bodies of work for some more modern writing. I have a list of tomes I'm quite sure the librarian will be able to procure for us within our existing arrangement.\n\nComplimentary club refreshments on us, if you help us out." },
    { id = 97237, name = "Shelf Picked", level = 18, minLevel = 13, requires = { 97234 }, faction = "Alliance", giver = "Donyal Tovald", start = { npc = "Donyal Tovald", area = 1519, x = 75.1, y = 30.2 }, finish = { npc = "Roy Lewells", area = 1519, x = 49.5, y = 72.4 }, objective = "Find each of the reading materials located somewhere in the library and then return to Roy Lewells in Stormwind's Park.", desc = "I've checked our inventory and all of the selections Mr. Lewells has listed are currently available.\n\nYou will, however, need to procure them off the shelves yourself. Part of our librarian duty is vigilance, and for that, I will resume supervisory bookkeeping.\n\nReturning with the material to Roy on his behalf will not mark yourself accountable for their return; as with his note you're serving as the book club's official courier. Their establishment shall carry that burden.\n\nGood day, <name>." },
    { id = 97914, name = "Expanding Horizons", level = 17, minLevel = 13, faction = "Alliance", giver = "Thundris Windweaver", start = { npc = "Thundris Windweaver", area = 148, x = 37.4, y = 40.2 }, finish = { npc = "Baros Alexston", area = 1519, x = 57.6, y = 47.8 }, objective = "Bring Thundris' Letter to Baros Alexston in Stormwind.\n\nThundris mentioned a boat in Auberdine that can take you there.", desc = "Auberdine is a humble place, <class>. You will not hear its name spoken in the boughs of Darnassus. Most reference only what the Sundering took from us--the thriving cities of Ameth'Aran, Bashal'Aran, and... Lathar'Lazal.\n\nYet Auberdine remains in their shadow.\n\nI would see our work here recognized. A new vessel connects us to the kingdom of Stormwind, bringing life and supplies to our shores. I beseech you join its next voyage, and bring this letter to a human called Baros Alexston.\n\nMake our home known." },
    { id = 98190, name = "A Friend of the Family (7/8)", level = 25, minLevel = 20, requires = { 98189 }, faction = "Alliance", objective = "Bring the Menethil Statuette to Highlord Bolvar Fordragon in Stormwind Keep.", desc = "You'll want to take this to Stormwind right away. Proud as I am that this keep and harbor bears King Terenas Menethil II's name, we are a calm harbor in a very nasty storm of enemies. It's just not safe here.\n\nThe Dragonmaw in particular would sacrifice much to loot something like this... and I shudder to think of what they'd do with it.\n\nDon't bother going up the chain of command on this one, <lad/lass>. Go straight to Highlord Fordragon with this. He'll know where it will be best kept.\n        See if you've already completed this by typing:\n\n        /run print(C_QuestLog.IsQuestFlaggedCompleted(98190))\n            WH.clickToCopy(document.currentScript.parentNode, \"\\/run print(C_QuestLog.IsQuestFlaggedCompleted(98190))\");\n\n        const cta = WH.Tools.createWowheadClientCta();\n        if (cta) {\n            $('.db-page-collection-tracker-cta').append(cta);\n        }" },
    { id = 98191, name = "A Friend of the Family (8/8)", level = 25, minLevel = 20, requires = { 98190 }, faction = "Alliance", objective = "Bring the Menethil Statuette to Lord Grayson Shadowbreaker in the Cathedral of Light.", desc = "King Terenas was a good man. A devout man. Beloved by his people, and truly the reason we have this Alliance at all.\n\nThe irony is he was humble--he hated these sorts of memorials, and so precious few exist. And of those, few survived Lordaeron's fall.\n\nIt seems the Light has coalesced in this statuette. It would be best kept in the Cathedral of the Light in Cathdral Square, in the center of the city. Bring it to Lord Grayson Shadowbreaker for safekeeping." },
    { id = 98219, name = "The Shamed Lieutenant", level = 30, minLevel = 20, faction = "Alliance", objective = "Speak to Lieutenant Farren Orinelle in Southshore in Hillsbrad Foothills.", desc = "Thank you again for delivering the statuette safely, <name>.\n\nI could use your help with something else. There's a member of the city guard who was reassigned to duty in Southshore out in the Hillsbrad Foothills.\n\nHis father was a friend of mine, and while I don't disagree that he could use the lesson... I'd still like to see him succeed. He would really benefit from someone like you helping him out.\n\nThere is a boat that can take you that way from Menethil Harbor, if you are passing back through." },
})

ns.AddQuests("z1537", {
    { id = 97263, name = "Your Package Has Arrived", level = 2, minLevel = 1, faction = "Alliance", finish = { npc = "Eldrun Stormbreaker", area = 1537, x = 47.4, y = 13.6 }, objective = "Deliver Eldrun's misplaced package.", desc = "<Several misplaced packages have been left by the mailbox. You note that one of them is marked for delivery from Aerie Peak, to Ironforge, to Eldrun Stormbreaker. It is marked \"urgent.\">" },
})

ns.AddQuests("z1637", {
    { id = 93739, name = "Exploring the Horde", level = 13, minLevel = 7, requires = { 95350 }, faction = "Horde", giver = "Thrall", start = { npc = "Thrall", area = 1637, x = 32, y = 37.8 }, finish = { npc = "Thrall", area = 1637, x = 32, y = 37.8 }, steps = { { name = "Cairne Bloodhoof", area = 1638, x = 59.6, y = 51.5 }, { name = "Nazgrel", area = 1637, x = 32.5, y = 36.3 }, { name = "Lady Sylvanas Windrunner", area = 1497, x = 57.5, y = 91.5 }, { name = "Vol'jin", area = 1637, x = 34.3, y = 36.7 } }, objective = "Speak with Nazgrel in Grommash Hold to receive further instructions. Use the instructions received to locate and speak with Vol'jin, Cairne Bloodhoof, and Lady Sylvanas Windrunner.", desc = "Azeroth is a large world, and the territory of the Horde is vast. The Undercity, Orgrimmar, and Thunder Bluff all have very unique people and culture.\n\nIf you are to be a guest of the horde here on Azeroth, it would do you good to visit each of our capital cities in turn. Speak with my advisor Nazgrel for directions." },
    { id = 95350, name = "Welcome to Azeroth", level = 13, minLevel = 7, requires = { 95349 }, faction = "Horde", giver = "Alaana Stormwalker", start = { npc = "Alaana Stormwalker", area = 215, x = 34.9, y = 31.9 }, finish = { npc = "Thrall", area = 1637, x = 32, y = 37.8 }, desc = "Its a big world down here, and our new allies are the key to our survival.\n\nThe Earthen Ring is a member of the \"Horde\", a proud collection of like-minded peoples. The nearby city of Thunder Bluff is a part of the horde, and further to the east lies the capital of Orgrimmar.\n\nSeek out the flight master in the center of Thunder Bluff. They will fly you to Orgrimmar where you will make contact with the horde warchief--Thrall, on behalf of the Windshapers. Winds guide you, <name>." },
    { id = 97242, name = "Yelmak's Medley", level = 15, minLevel = 9, faction = "Horde", giver = "Kor'geld", start = { npc = "Kor'geld", area = 1637, x = 56.2, y = 34.2 }, finish = { npc = "Kor'geld", area = 1637, x = 56.2, y = 34.2 }, objective = "Take some cuttings from the Cattails and Speargrass growing around the water flows in the Valley of Honor and return to Kor'geld in Yelmak's Alchemy and Potions", desc = "Yelmak doesn't want his apprentice breaking anything. Well, anything more than he already has.\n\nHe told me the young mixer in training has too much pride to ask for help when he really needs it. Yelmak wants to give him a taste of a particular home-brewed recipe.\n\nGather a mix of cattail and speargrass cuttings taken from the plants growing around the water in the Valley of Honor. I'd get them myself, but if I left the shop, Whuut would surely know we're catering to his mood." },
    { id = 97246, name = "Meal Appeal", level = 15, minLevel = 5, faction = "Horde", giver = "Thatog", start = { npc = "Thatog", area = 1637, x = 55.6, y = 72 }, finish = { npc = "Borstan", area = 1637, x = 57.4, y = 53.4 }, desc = "My son, Migi, always takes off to play with his friends all day. I tell him to pick up a lunch at Borstan's, but I know he almost never does, because he comes home starving. These kids think their games are more important than their own bodies!\n\nPlease, stop at Borstan's Firepit and tell him you're there to deliver Migi's lunch. You can almost certainly find Migi behind Grommash Hold with the rest of his friends.\n\nDuties keep me here during the day and I can't watch over his every meal." },
    { id = 97249, name = "Favorite Food", level = 15, minLevel = 5, faction = "Horde", giver = "Borstan", start = { npc = "Borstan", area = 1637, x = 57.4, y = 53.4 }, finish = { npc = "Migi", area = 1637, x = 36.8, y = 29 }, objective = "Bring Migi's Lunch to him behind Grommash Hold", desc = "Now that I know his parents worry about how much he's actually filling that belly, I've got an idea.\n\nThey made me promise not to pack the same meal every day, so Migi grows a taste for more than one thing. Still, whenever the smoker's full and we're making sweetglazed hog belly sandwiches, he always shows up for lunch. We've started crumbling the leftover crispy glazed bits as a topping--something we can add daily.\n\nTake this to him. Maybe he'll start showing up early and bringing friends!" },
    { id = 97275, name = "Whuut's the Rush", level = 15, minLevel = 9, faction = "Horde", giver = "Yelmak", start = { npc = "Yelmak", area = 1637, x = 56.6, y = 33.2 }, finish = { npc = "Whuut", area = 1637, x = 55.8, y = 33.2 }, objective = "Give Yelmak's Potion to Whuut.", desc = "Whuut is a prodigy. That much is true. But he doesn't yet have the experience, wisdom, and time on the stirring rod to know how to respect alchemical processes.\n\nHe is exhausting all of the rarest and most exotic reagents we have available without pausing to practice and refine his basic skills.\n\nGive him this potion I've brewed with a quick tonic method. He'll reconsider everything he's doing when he learns how local remedies and careful touch are the first true mastery." },
    { id = 97326, name = "Rocks to Rests", level = 15, minLevel = 5, faction = "Horde", giver = "Thra", start = { npc = "Thra", area = 1637, x = 36.8, y = 29 }, finish = { npc = "Thra", area = 1637, x = 36.8, y = 29 }, objective = "Return 8 Smooth Boulders to Thra behind Grommash Hold.", desc = "Hey! You've got time to help us out! I know you do, I can tell by the way you smiled watching the game we're playing.\n\nThis spot behind Grommash Hold is nice because it's clear enough for us to set up our figures. But what stinks is we don't have enough rocks for chairs or tables.\n\nYou're big and strong... d'ya think you could carry back some medium sized rocks, smooth enough to sit on if we need a rest?" },
})

ns.AddQuests("z1638", {
    { id = 97485, name = "Traditions of the Bluff", level = 10, minLevel = 3, faction = "Horde", giver = "Eylah Sunhorn", start = { npc = "Eylah Sunhorn", area = 1638, x = 38.2, y = 56.2 }, finish = { npc = "Eylah Sunhorn", area = 1638, x = 38.2, y = 56.2 }, objective = "Purchase a Bundle of Herbs from Nida the herbalist, a Bundle of Ceder Twigs from Nata the enchanting supplier, and Sinew Thread from Mahu the leatherworking supplier and Ceremonial Flint and Tinder from Naal the cooking supplier.\n\nCombine the items and sprinkle the incense off of Hunter's Rise.", desc = "Blessings of An'she, friend.\n\nWe tauren have a tradition of scattering incense to the winds and I was hoping you'd be interested in honoring this tradition.\n\nYou will need to craft the incense by purchasing herbs from Nida, cedar from Nata, sinew thread from Mahu in the mid rise, and ceremonial flint and tinder from Naal on the upper rise. Once you have these items, combine them and spread them off the south facing cliff of Hunter's Rise.\n\nYou will find a mat and incense at the ceremonial site." },
    { id = 98251, name = "Never Coming Back", level = 22, minLevel = 18, faction = "Horde", steps = { { name = "Ashenvale Bear", area = 331, x = 42.9, y = 63.6 }, { name = "Shadowhorn Stag", area = 331, x = 43.2, y = 63.8 } }, objective = "Kill 6 Shadowhorn Stag and 6 Ashenvale Bear and return to Va'xug Firefure northwest of Fallen Sky Lake.", desc = "Gaaah!\n\nI'm so angry. They said Ashenvale was easy to follow. Easy for who? The beasts? The birds?\n\nOne moment I was gathering an herb, the next I'm trapped in this ravine. Do I truly have to circle half the forest to reach where I stood just moments ago?\n\nWhen I'm like this, my spells grow volatile and behave... differently.\n\nCould you thin the wildlife nearby? Even their stupid hooves grate on me. I despise this cursed forest." },
    { id = 98252, name = "A Void Path", level = 22, minLevel = 18, requires = { 98251 }, faction = "Horde", objective = "Show Va'xug's Eye of Kilrogg the way back to the main Ashenvale road.", desc = "Show my Eye of Kilrogg the way out of this ravine and back to the Ashenvale road. Keep it moving and I'll follow once I see a clear path.\n\nI'll stay here--one of us should keep our bearings. If you lose the way, I can guide you back through the eye. I will not have us both wandering blind in this malicious forest.\n\nI can hold the channel for four minutes. No longer. Reach the road before the vision breaks, or return to me and we try again." },
})

ns.AddQuests("z1657", {
    { id = 98067, name = "Eyes of the Sentinels", level = 11, minLevel = 1, faction = "Alliance", giver = "Sentinel Dalia Sunblade", start = { npc = "Sentinel Dalia Sunblade", area = 1657, x = 39.8, y = 89.2 }, finish = { npc = "Sentinel Dalia Sunblade", area = 1657, x = 39.8, y = 89.2 }, steps = { { name = "Credit", area = 1657, x = 33.7, y = 16.2 }, { name = "Credit", area = 1657, x = 41, y = 43.6 }, { name = "Credit", area = 1657, x = 66.6, y = 15.5 }, { name = "Credit", area = 141, x = 35.8, y = 54.2 } }, objective = "Place Sentinel Owls at the entrance to the Cenarion Hold depths, the Darnassus Bank, the Craftsman's Terrace Inn, and the City Gate for Sentinel Dalia Sunblade in the Temple of the Moon in Darnassus.", desc = "General Feathermoon ensures all sentinels have time to pray to Elune. A proper huntress wields not blade alone, but gifts of the goddess to overcome our enemies.\n\nYou may help with my daily duties. Place sentinels around the city--start with the tunnels leading beneath Cenarion Hold to the north, the bank at the center of town, the inn in the Craftsman's Terrace to the northeast, and the city gates. The guards can assist you.\n\nSomething is amiss in Teldrassil--we must remain vigilant." },
    { id = 98391, name = "The Sisterhood of Elune", level = 10, minLevel = 5, faction = "Alliance", giver = "Laurna Morninglight", start = { npc = "Laurna Morninglight", area = 141, x = 55.6, y = 56.8 }, finish = { npc = "Sister Aquinne", area = 1657, x = 29, y = 45.4 }, desc = "Blessings to you, <class>. The Sisterhood of Elune has stood as a pillar of kaldorei society for thousands of years.\n\nBefore the Great Sundering, before the War of the Ancients, through the Long Vigil, we have guided and healed our people through the darkness. Such is our charge, and such is the demand of the peerless Mother Moon.\n\nWe now require your aid in a matter of great importance. Sister Aquinne awaits your arrival in Darnassus." },
})

ns.AddQuests("z16593", {
    { id = 92454, name = "Welcome!", level = 1, minLevel = 1, objective = "Bring the Thendal Grove Gift Voucher to Dalia Windbreeze.", desc = "Welcome to the World of Warcraft!\n\nAs special thanks for purchasing the World of Warcraft Collector's Edition, turn in this gift voucher to Dalia Windbreeze in Thendal Grove.  You'll then be given a gift: a little companion to join you on your quest for adventure and glory.\n\nThanks again, and enjoy your stay in the World of Warcraft!" },
    { id = 92460, name = "Coming of Age", level = 1, minLevel = 1, giver = "Ailee Farheart", start = { npc = "Ailee Farheart", area = 16593, x = 42.8, y = 23.4 }, finish = { npc = "Rorian the Dayseeker", area = 16593, x = 42, y = 23.4 }, desc = "Look at you, bright eyed and ready for adventure! We've been awaiting your arrival and anticipating your much needed help here in Thendal Village. I imagine you are brimming with both nerves and excitement for what is to come. After all, you only get to come of age once in a lifetime.\n\n<Ailee smiles kindly.>\n\nGo, seek out our village leader Rorian the Dayseeker at the entrance to the greatfather tree just west of here. He will get you started on your journey." },
    { id = 92461, name = "Harmony in Balance", level = 1, minLevel = 1, requires = { 92460 }, giver = "Rorian the Dayseeker", start = { npc = "Rorian the Dayseeker", area = 16593, x = 42, y = 23.4 }, finish = { npc = "Rorian the Dayseeker", area = 16593, x = 42, y = 23.4 }, steps = { { name = "Juvenile Vuldren", area = 16593, x = 44.6, y = 25.4 } }, objective = "Slay 8 Vuldren Juveniles in Thendal Grove.", desc = "We live in times of great uncertainty for our people. We face unprecedented challenges that may require bold solutions, but we also must contend with the ordinary and mundane here in Thendal Grove. Take, for example, the recent unsustainable rise in the vuldren population.\n\nThe vuldren are a vital part of our ecosystem. However, imbalances must be corrected to maintain the delicate harmony that all creatures in Thendal Grove share.\n\nHead east and cull some of the vuldren there." },
    { id = 92462, name = "Infestation Investigation", level = 2, minLevel = 1, giver = "Elatrell Featherlight", start = { npc = "Elatrell Featherlight", area = 16593, x = 43.4, y = 24.8 }, finish = { npc = "Elatrell Featherlight", area = 16593, x = 43.4, y = 24.8 }, steps = { { name = "Pesky Cirrusfly", area = 16593, x = 45.6, y = 27 } }, objective = "Slay 8 Pesky Cirrusflies in Thendal Grove.", desc = "One of our rangers recently reported an infestation of cirrusflies here in Thendal Grove.\n\nCirrusflies can be dangerous if the swarm is allowed to grow too large, so please head to the eastern end of the Grove and exterminate as many as you can." },
    { id = 92463, name = "The Cirrusfly Queen", level = 3, minLevel = 2, giver = "Elatrell Featherlight", start = { npc = "Elatrell Featherlight", area = 16593, x = 43.4, y = 24.8 }, finish = { npc = "Elatrell Featherlight", area = 16593, x = 43.4, y = 24.8 }, steps = { { name = "Cirrusfly Queen", area = 16593, x = 47.7, y = 28.6 } }, objective = "Destroy the Cirrusfly Queen in Thendal Grove.", desc = "If the forest is as thick with these insects as it sounds, simply killing the workers won't be enough.\n\nGo deeper into the forest and find the queen. She'll be close to the hive and surrounded by bigger and more aggressive soldiers, so be careful.\n\nPut her down and return here when it's done. That'll be one less problem to think about around here." },
    { id = 92464, name = "Elemental Unrest", level = 3, minLevel = 2, giver = "Rorian the Dayseeker", start = { npc = "Rorian the Dayseeker", area = 16593, x = 42, y = 23.4 }, finish = { npc = "Yala Windwatcher", area = 16593, x = 47.2, y = 21.8 }, objective = "Speak to the Yala Windwatcher in Thendal Grove.", desc = "Ever since our elemental benefactors left us, it seems that we are simply moving from one unrest to another. The problem we face now is that the manifestations of the winds near the standing stones to the northeast are agitated.\n\nNot truly self-aware like the sentient wind spirits that once lived here, these simple sprites respond in kind to forces, emotions, and intentions of the creatures around them.\n\nMy apprentice Yala Windwatcher went to observe them. Seek her out and discover what she's learned." },
    { id = 92465, name = "Agitators", level = 3, minLevel = 2, requires = { 92464 }, giver = "Yala Windwatcher", start = { npc = "Yala Windwatcher", area = 16593, x = 47.2, y = 21.8 }, finish = { npc = "Yala Windwatcher", area = 16593, x = 47.2, y = 21.8 }, steps = { { name = "Roiling Winds", area = 16593, x = 47.3, y = 19.9 }, { name = "Al'Aketh Convert", area = 16593, x = 47.3, y = 19.9 } }, objective = "Slay 6 Roiling Winds and 7 Al'Aketh Converts in Thendal Grove.", desc = "The Al'Aketh cult is a blight upon this island. These cultists are surely the ones responsible for agitating the simple wind sprites that reside here and turning them violent.\n\nRegrettably, we'll need to disperse these roiling winds here before they harm someone. We also need to send a clear message to the cult that they are not welcome in the grove.\n\nWill you lend me your aid, <class>?" },
    { id = 92466, name = "Call of Earth (1/2)", level = 4, minLevel = 3, faction = "Horde", giver = "Windshaper Boro", start = { npc = "Windshaper Boro", area = 16593, x = 42.8, y = 23.6 }, finish = { npc = "Windshaper Boro", area = 16593, x = 42.8, y = 23.6 }, steps = { { name = "Signet of Akir", area = 16593, x = 36.5, y = 32.9 } }, objective = "Bring a Signet of Akir to Windshaper Boro.", desc = "While we owe much of our prosperity to the elements of wind, the path we walk requires that we obey the call of all four of the primary elements and undertake a trial for each. Before you begin your first trial in earnest however, you must prove the strength of your resolve.\n\nTravel to the standing stones to the east. A force of Al'Aketh converts has been spotted there and they must be driven off. Confront the cultists there and bring me one of their signets as proof of your deeds." },
    { id = 92467, name = "Call of Earth (2/2)", level = 4, minLevel = 3, requires = { 92466 }, faction = "Horde", giver = "Windshaper Boro", start = { npc = "Windshaper Boro", area = 16593, x = 42.8, y = 23.6 }, finish = { npc = "Minor Manifestation of Earth", area = 16593, x = 49.6, y = 24 }, objective = "Find the Rise of Spirits and drink the Earth Sapta.\n\nProvided item:", desc = "A sapta is a drink created to bind our spirits to the elements. Fused with magic, the potion will allow the strong willed to see the elements as no one else can. Your spirit will be connected to the element the sapta was created for, and only a select few shaman know the recipe.\n\nThe sapta is always drunk in a sacred place, and never anywhere else--remember that.\n\nSeek out the Rise of Spirits up the pass northeast of here. Drink your sapta there, and... well, you will see what you need see." },
    { id = 92468, name = "Call of Earth", level = 4, minLevel = 3, faction = "Horde", giver = "Minor Manifestation of Earth", start = { npc = "Minor Manifestation of Earth", area = 16593, x = 49.6, y = 24 }, finish = { npc = "Windshaper Boro", area = 16593, x = 42.8, y = 23.6 }, objective = "Bring the Rough Quartz to Windshaper Boros in Thendal Grove.", desc = "Take this Rough Quartz from me and bring it to the one you call Windshaper Boro as proof of our meeting. He will craft a totem for you, and this shard will be the heart of it. As small as it may seem, you will come to find that size does not matter, and that even the smallest of things can outlast many others.\n\nBe patient, <name>. Remain strong. And seek wisdom. This is what the elements ask of you. In the end, you shall become one with the earth--respect it as it shall respect you." },
    { id = 92469, name = "Return to Rorian", level = 4, minLevel = 3, giver = "Yala Windwatcher", start = { npc = "Yala Windwatcher", area = 16593, x = 47.2, y = 21.8 }, finish = { npc = "Rorian the Dayseeker", area = 16593, x = 42, y = 23.4 }, desc = "You've done enough here, <class>. I'll stay and clean up any stragglers down there.\n\nHead back to the Village and tell Rorian about the cult's presence. He will not be pleased." },
    { id = 92470, name = "Foul Matriarch", level = 5, minLevel = 2, requires = { 92469 }, giver = "Aetheen of the Gales", start = { npc = "Aetheen of the Gales", area = 16593, x = 42.6, y = 23.6 }, finish = { npc = "Aetheen of the Gales", area = 16593, x = 42.6, y = 23.6 }, steps = { { name = "Head of Urs'anah", area = 16593, x = 35.5, y = 25.3 }, { name = "Ursera Scavenger", area = 16593, x = 36.8, y = 25.5 } }, objective = "Slay 8 Ursera Scavengers and collect the head of the den mother, Urs'anah in Thendal Grove.", desc = "Rorian informed you that I've been watching you. I now offer you a test of resolve. However, be warned--it will send you into great danger.\n\nGo to the caves to the south. Thin out the ursera's numbers there, and find their matriarch, one the rangers call \"Urs'anah\". Put her down and bring me proof of her demise. Once you have done that, you will have taken an important step on your path." },
    { id = 92471, name = "Aetheen of the Gales", level = 4, minLevel = 4, giver = "Rorian the Dayseeker", start = { npc = "Rorian the Dayseeker", area = 16593, x = 42, y = 23.4 }, finish = { npc = "Aetheen of the Gales", area = 16593, x = 42.6, y = 23.6 }, desc = "You may not realize this but everything you've done has been a trial of sorts. A test for what is to come for you. It's a big island out there, and Zephras needs spirited young adventurers such as yourself if we are to survive the trials our people face.\n\nThe one called Aetheen of the Gales is one of the leaders of our people here on Zephras Isle, and she has been watching you. She has a task that you must complete. Speak with her to learn more." },
    { id = 92472, name = "The Next Step", level = 5, minLevel = 3, requires = { 92470 }, giver = "Aetheen of the Gales", start = { npc = "Aetheen of the Gales", area = 16593, x = 42.6, y = 23.6 }, finish = { npc = "Constable Aonda", area = 16593, x = 45.6, y = 45.4 }, desc = "One of the most pervasive threats on Zephras Isle is the Al'Aketh Cult. They are religious zealots devoted to the worship of the supposed elemental ruler of Skywall, Al'Akir the Windlord. They are brutal, single minded, and their power and ambitions are growing more deadly by the day.\n\nYour path will soon take you to Shen'dar Village to the south. Present yourself to Constable Aonda when you arrive. The cult threatens Shen'dar and they are in need of aid. Tell Aonda that I sent you." },
    { id = 92473, name = "Aggressive Encroachment", level = 4, minLevel = 3, giver = "Valreaa Valewind", start = { npc = "Valreaa Valewind", area = 16593, x = 42.4, y = 25 }, finish = { npc = "Valreaa Valewind", area = 16593, x = 42.4, y = 25 }, steps = { { name = "Scrawny Ursera Claw", area = 16593, x = 39.5, y = 27.2 } }, objective = "Collect 6 Scrawny Ursera Claws from Scrawny Ursera in Thendal Grove.", desc = "The ursera den to the southwest is rapidly becoming a problem. Just last week the rangers had to kill an adolescent ursera who wandered too close to the village and attempted to attack a boy playing near the base of the elder tree in the center of the village.\n\nWe were fortunate that the boy escaped with his life. Hunger and desperation makes these beasts too dangerous to be left unchecked. Go south and put the scrawniest among the ursera down. Bring me their claws as proof when it is done." },
    { id = 92474, name = "Falling With Style", level = 2, minLevel = 2, giver = "Myriaal Mistwake", start = { npc = "Myriaal Mistwake", area = 16593, x = 43.6, y = 24 }, finish = { npc = "Rorian the Dayseeker", area = 16593, x = 42, y = 23.4 }, desc = "Well hello there, <name>! Want to play a game?\n\nAll you've got to do is step up on that ledge... then jump! Use your innate ability to walk on the air to slow your fall and see how far forward you can float.\n\nThe rules are made up and the points don't matter, but you get bonus points if you can land right in front of Rorian the Dayseeker and startle him! He won't like it but I'll certainly get a good laugh if you can get him all worked up! Hah!" },
    { id = 92480, name = "zzOLD UNUSED Cult Ambush", level = 6, minLevel = 4, objective = "Bring the Orders from the High Priestess to Shen'Dar Village and present it to whomever is in charge there.", desc = "The cultist you just killed dropped what appears to be orders from a high priestess of the Cult of Al'Akir. It makes mention of a spy in Shen'dar Village and cult operations in a place called Falaath Village. The authorities at Shen'dar Village will want to learn of this." },
    { id = 92514, name = "Welcome to Shen'dar Village", level = 6, minLevel = 4, faction = "Horde", giver = "Constable Aonda", start = { npc = "Constable Aonda", area = 16593, x = 45.6, y = 45.4 }, finish = { npc = "Constable Aonda", area = 16593, x = 45.6, y = 45.4 }, steps = { { name = "Illaya Amberwind", area = 16593, x = 43.5, y = 44.8 }, { name = "Coriella Calmbreeze", area = 16593, x = 43, y = 43.2 } }, objective = "Speak with Illaya Amberwind and Coriella Calmbreeze in Shen'dar Village.", desc = "You've got that \"Windshaper\" air about you. Something about how I can feel a tiny bit of static on my skin when near someone spirit-touched that gives it away. Before I properly put you to work around here, you should check in with our resident Windshaper elder, Illaya Amberwind. She's just outside, near the center of town.\n\nOh, and check in with Coriella Calmbreeze as well, she runs the local inn and can provide lodging and supplies, should you need them." },
    { id = 92515, name = "The Problem With Prideclaws", level = 6, minLevel = 4, giver = "Indari Sunseam", start = { npc = "Indari Sunseam", area = 16593, x = 44.6, y = 44.4 }, finish = { npc = "Indari Sunseam", area = 16593, x = 44.6, y = 44.4 }, steps = { { name = "Prideclaw Pelt", area = 16593, x = 42.2, y = 43.6 } }, objective = "Collect 10 Prideclaw Pelts from the Prideclaws in Shen'dar Highlands.", desc = "As if bandits and mad cultists weren't enough, the hills are thick with prideclaws as well right now. They are starting to encroach on the village borders and growing bolder by the day. It's only a matter of time before someone's pet or child is taken. It would be a mercy for us to cull their numbers now rather than after some tragedy occurs.\n\nBring me a dozen or so of their pelts. I can turn them into all sorts of goods that will be of aid to the village." },
    { id = 92516, name = "Hippogryph Harrassment", level = 7, minLevel = 4, giver = "Teeri Wellwind", start = { npc = "Teeri Wellwind", area = 16593, x = 44.4, y = 45 }, finish = { npc = "Teeri Wellwind", area = 16593, x = 44.4, y = 45 }, steps = { { name = "Hippogryph Matriarch", area = 16593, x = 34.3, y = 53.3 }, { name = "Hippogryph Protector", area = 16593, x = 35.5, y = 53.4 }, { name = "Hippogryph Youth", area = 16593, x = 37.9, y = 54.4 } }, objective = "Slay 8 Hippogryph Youths, 6 Hippogryph Protectors and a Hippogryph Matriarch in the Shen'dar Highlands.", desc = "A flock of Hippogryph have recently established nesting grounds southeast of Shen'dar Village and they've been wreaking havoc on travelers on the road. I need someone to head down there and thin them out for us." },
    { id = 92517, name = "The Criminal Element", level = 7, minLevel = 4, requires = { 92514 }, giver = "Constable Aonda", start = { npc = "Constable Aonda", area = 16593, x = 45.6, y = 45.4 }, finish = { npc = "Constable Aonda", area = 16593, x = 45.6, y = 45.4 }, steps = { { name = "Highlands Bandit", area = 16593, x = 49, y = 36.4 }, { name = "\"Badwind\" Bennic", area = 16593, x = 50.6, y = 33.6 } }, objective = "Kill 10 Highlands Bandits and their leader, \"Badwind\" Bennic in the Shen'dar Highlands.", desc = "There's a cave not far to the north, hidden behind a waterfall. It's well known to me that there's a group of bandits that are operating out of that cave. They were a problem for us before the cult arrived, but now they are a real terror. I can't spare the people to go and clear them out, unfortunately.\n\nI need you to go there and take care of them for me. Kill as many as you can, and if possible, take out their leader, the one they call \"Badwind\" Bennic. That cave is dangerous, so be careful." },
    { id = 92528, name = "Among the Faithful", level = 8, minLevel = 5, requires = { 92529 }, giver = "Missionary Jasaan", start = { npc = "Missionary Jasaan", area = 16593, x = 46.8, y = 56.2 }, finish = { npc = "Constable Aonda", area = 16593, x = 45.6, y = 45.4 }, objective = "Look around Falaath Village to learn about the cult's intentions in the Shen'dar Highlands.", desc = "The faithful of Al'Akir grow ever stronger with each eager new recruit like yourself. As you can see, our strength gives form to the storm itself!\n\nNormally I'd send you straight to Skypriest Aanders for assessment, but he is occupied at present receiving a guest at the inn on the north side of town. Please avoid that place for now. An unshaven recruit like yourself in the presence of such a guest would be inappropriate.\n\nFor now, just don't get in anyone's way." },
    { id = 92529, name = "Falaath Village", level = 8, minLevel = 5, requires = { 93036 }, giver = "Sania Silverstream", start = { npc = "Sania Silverstream", area = 16593, x = 44.8, y = 45.4 }, finish = { npc = "Missionary Jasaan", area = 16593, x = 46.8, y = 56.2 }, objective = "Report to Missionary Jasaan near the entrance to Falaath Village.\n\nIf you lose your Mark of Akir, speak with Sania Silverstream in Shen'dar Village to regain the effect.", desc = "It gladdens my heart that you wish to serve Al'Akir. Our current trials as a people stem from our own complacency. We grew prideful and took the bounty of the winds for granted. The stagnation that followed is the reason the spirits of the wind abandoned us.\n\nOnly through acts of contrition may we feel the wind's caress once more. If you seek the fellowship of like-minded shen'dorei, go to Falaath Village and find Missionary Jasaan there. I will mark you so that the faithful will know you as a recruit." },
    { id = 92544, name = "Al'Aketh Thugs", level = 5, minLevel = 2, giver = "Hanaa Nightwind", start = { npc = "Hanaa Nightwind", area = 16593, x = 38.2, y = 30.2 }, finish = { npc = "Hanaa Nightwind", area = 16593, x = 38.2, y = 30.2 }, steps = { { name = "Al'Aketh Brute", area = 16593, x = 36.5, y = 33 }, { name = "Al'Aketh Neophyte", area = 16593, x = 36.5, y = 32.7 }, { name = "Malduko Cloudcrush", area = 16593, x = 36.2, y = 33.3 } }, objective = "Slay 6 Al'Aketh Brutes, 4 Al'Aketh Neophytes, and Malduko Cloudcrush in Thendal Grove.", desc = "A band of Al'Aketh cult ruffians have taken up residence near the temple ruins just southwest of here, led by a real monster called Malduko Cloudcrush. This rabble has no doubt been dispatched here by High Priestess Lorthuna at the Shrine of Akir to attack travelers and coerce our people into joining the cult.\n\nI need to stay here at my post to alert travelers leaving the grove of the danger, but I would be grateful if you could do something about those cultists and their leader for me." },
    { id = 92550, name = "Havoc in the Highlands", level = 8, minLevel = 5, requires = { 92528 }, giver = "Constable Aonda", start = { npc = "Constable Aonda", area = 16593, x = 45.6, y = 45.4 }, finish = { npc = "Constable Aonda", area = 16593, x = 45.6, y = 45.4 }, steps = { { name = "Commander Cyclas's Head", area = 16593, x = 50.1, y = 56.7 }, { name = "Living Lightning", area = 16593, x = 48.4, y = 55.7 }, { name = "Al'Aketh Stormcaller", area = 16593, x = 48.6, y = 55.7 } }, objective = "Travel to the ruins of Falaath Village and slay 6 Al'Aketh Stormcallers, 4 Living Lightning and take the head of Commander Cyclas.", desc = "Our best defense here might just be a strong offense. The advantage we now have is that we expect an attack is coming. What they won't expect is for us to hit them first.\n\nI've already asked a lot of you, but please head back over to Falaath Village. Kill as many cultists as you can and if you can get close enough, kill the commander and bring me his head. I'll stay here and organize the citizens and our few peacekeepers to prepare a defense... just in case you don't return." },
    { id = 92551, name = "Stolen Supplies", level = 8, minLevel = 5, giver = "Danarii Bellowveil", start = { npc = "Danarii Bellowveil", area = 16593, x = 45.2, y = 45.2 }, finish = { npc = "Danarii Bellowveil", area = 16593, x = 45.2, y = 45.2 }, objective = "Collect 10 packs of Stolen Shen'dar Supplies from Falaath Village in the Shen'dar Highlands.", desc = "I overheard you might be going to Falaath Village? While you are there, please keep an eye out for our stolen supply caches.\n\nThe Al'Aketh have been raiding our supply caravans carrying various goods such as food and windstones to and from the lowlands for months. They've been blaming the bandits, of course, but we all know that it all ends up in the same place. If there's any of that stuff left in Falaath, it would be a huge help if you could recover it." },
    { id = 92553, name = "Restocking the Larders", level = 6, minLevel = 4, giver = "Zerril Softbreeze", start = { npc = "Zerril Softbreeze", area = 16593, x = 43.8, y = 43.8 }, finish = { npc = "Zerril Softbreeze", area = 16593, x = 43.8, y = 43.8 }, steps = { { name = "Small Egg", area = 16593, x = 39.1, y = 52.1 } }, objective = "Collect 3 Small Eggs and 8 Strider Meat from creatures found throughout the Shen'dar Highlands.", desc = "Up for a bit of work? I could use a bit of muscle from a strong adventuring-type such as yourself. With how dangerous things are getting around here, no one's had much time to hunt or forage of late, and I need someone to get out there and source me fresh eggs and strider meat to keep this village fed.\n\nI'd be happy to teach you one of my famous recipes if you can bring me what I need. What do you say?" },
    { id = 92579, name = "To Valanaar", level = 8, minLevel = 6, requires = { 92550 }, faction = "Horde", giver = "Constable Aonda", start = { npc = "Constable Aonda", area = 16593, x = 45.6, y = 45.4 }, finish = { npc = "Valennia Stormfist", area = 16593, x = 66.2, y = 76.6 }, objective = "Deliver Aonda's Written Report to Valennia Stormfist in Valanaar.", desc = "For now it seems the pylon and the village are safe, so I'd like you to deliver this report to the Valennia Stormfist in Valanaar, at the southeastern edge of the island. Valennia is the leader of the peacekeepers on the island and she needs to know what happened here.\n\nThe cult is expanding rapidly and the peacekeepers have avoided direct conflict until now, but those days are over. Valanaar will need to be ready for a fight.\n\nAt any rate, thank you. You'll always have friends in Shen'dar, <name>." },
    { id = 92595, name = "The Windshapers", level = 6, minLevel = 4, faction = "Horde", giver = "Illaya Amberwind", start = { npc = "Illaya Amberwind", area = 16593, x = 43.6, y = 44.8 }, finish = { npc = "Illaya Amberwind", area = 16593, x = 43.6, y = 44.8 }, steps = { { name = "Illaya Amberwind", area = 16593, x = 43.5, y = 44.8 } }, objective = "Listen to what Illaya Amberwind has to say.", desc = "<Illaya smiles warmly at you.>\n\nI am glad you returned to speak with me, child of the winds. I knew it the first moment you walked into my presence, that you were strong in the skysight. Do you find this surprising? Even those who have not trained as a Shaman may possess the gift.\n\nCome, let us speak about the mandate of the Windshapers, the nature of our struggles on Zephras, and the plight of our people." },
    { id = 92596, name = "The High Order", level = 6, minLevel = 4, faction = "Alliance", giver = "Rathiril Sunlance", start = { npc = "Rathiril Sunlance", area = 16593, x = 45, y = 46.4 }, finish = { npc = "Rathiril Sunlance", area = 16593, x = 45, y = 46.4 }, steps = { { name = "Rathiril Sunlance", area = 16593, x = 45, y = 46.4 } }, objective = "Have a seat and speak with Rathiril Sunlance.", desc = "The aura of arcane energy that surrounds you is strong, even though you are not initiated as a mage. I am quite sure that you are going to be a capable adventurer, and your connection with our ancient magic will only ever be a boon to you even if you were to never utter a single word of power in spellcasting.\n\nCome, let us sit and speak some on my order, the nature of the arcane here on Zephras, and the plight of our people." },
    { id = 92597, name = "Reading the Ley Lines", level = 4, minLevel = 2, faction = "Alliance", giver = "Falorne Fallwind", start = { npc = "Falorne Fallwind", area = 16593, x = 43.2, y = 24.8 }, finish = { npc = "Falorne Fallwind", area = 16593, x = 43.2, y = 24.8 }, objective = "Use your Read Ley Line racial ability at the ley line in Thendal Grove.", desc = "Here in the elemental plane, we derive much of our arcane strength from ley lines that still run through the ground under our feet. Of late, these ley lines have begun to pierce the surface, giving us more direct and powerful access to these latent arcane energies.\n\nGo to the standing stones to the northeast. There is a ley line there. Tap into your birthright and draw in its energy." },
    { id = 92598, name = "The Gift of Skysight", level = 4, minLevel = 2, faction = "Horde", giver = "Ventaari Brightwish", start = { npc = "Ventaari Brightwish", area = 16593, x = 42.6, y = 24.4 }, finish = { npc = "Ventaari Brightwish", area = 16593, x = 42.6, y = 24.4 }, objective = "Use your Skysight racial ability at the Elemental Convergence in Thendal Grove.", desc = "As a Windshaper, you have the ability to use the sacred skysight gifted to us by the elemental spirits. Travel to the standing stones to the northeast of the village. Find the elemental convergence there and use your gift.\n\nYou'll find that you may draw upon the skysight anywhere, but its boon is much more powerful if you do so in the presence of an elemental convergence. You may at times receive other bits of wisdom from the spirits that are drawn to such places of power, as well." },
    { id = 92640, name = "Desperate Times", level = 11, minLevel = 6, requires = { 94568 }, giver = "Talaanis Shadowsong", start = { npc = "Talaanis Shadowsong", area = 16593, x = 66.2, y = 76.6 }, finish = { npc = "Valennia Stormfist", area = 16593, x = 66.2, y = 76.6 }, steps = { { name = "Ayessa Dawnsinger", area = 16593, x = 59, y = 79.5 }, { name = "Valennia Stormfist", area = 16593, x = 66.2, y = 76.6 }, { name = "Elaadrin Evengale", area = 16593, x = 66.5, y = 79.8 } }, objective = "Speak with Valennia Stormfist in Valanaar and follow her instructions.", desc = "Since engaging the cult in the open is not viable, our best chance is going to be to use this opportunity to attack the shrine itself. We can take Lorthuna herself off the board before she can finish her part of this scheme.\n\nIt so happens that Valennia has been preparing a strategy for a potential assault on the Shrine for some time now. The only problem is, we will need help.\n\nSpeak with Valennia for the details." },
    { id = 92642, name = "Disrupting Logistics", level = 11, minLevel = 6, giver = "Yorana Windyreed", start = { npc = "Yorana Windyreed", area = 16593, x = 69.6, y = 67 }, finish = { npc = "Yorana Windyreed", area = 16593, x = 69.6, y = 67 }, steps = { { name = "Al'Aketh Healer", area = 16593, x = 65.7, y = 66.8 }, { name = "Al'Aketh Brawler", area = 16593, x = 65.5, y = 66.9 } }, objective = "Slay 4 Al'Aketh Healers and 8 Al'Aketh Brawlers in the Gustberry Lowlands.", desc = "Valennia only sent one person to help repel a full-scale assault... by the winds.\n\nYou don't look like much but I'll take what I can get. We need to inflict as much damage as possible to stop this soon. My people can't hold out much longer.\n\nGo down the hill and disrupt their logistics. Their healers are keeping the attackers coming, if we take them out we might be able to rally and push them back. Any other cultists you kill while you are out there are helpful as well." },
    { id = 92643, name = "The Turncoat", level = 11, minLevel = 6, giver = "Talaanis Shadowsong", start = { npc = "Talaanis Shadowsong", area = 16593, x = 66.2, y = 76.6 }, finish = { npc = "Dead Cultist", area = 16593, x = 56, y = 58.8 }, steps = { { name = "Dead Cultist", area = 16593, x = 56, y = 58.8 } }, objective = "Find the cultist turncoat at the house just inside the highlands northwest of Valanaar.", desc = "There is a turncoat amongst the Al'Aketh. They claim to know the cult's true intentions for the island and want to come in, but will only do so with assurances of protection.\n\nThis defector is hiding at a secluded residence just northwest of Valanaar inside the highlands. I need someone who can discreetly go there, find the traitor, and escort him back to us. This might be a trap, but if this information is as important as this traitor claims, its worth some risk." },
    { id = 92644, name = "Unfortunate News", level = 11, minLevel = 6, requires = { 92643 }, giver = "Dead Cultist", start = { npc = "Dead Cultist", area = 16593, x = 56, y = 58.8 }, finish = { npc = "Talaanis Shadowsong", area = 16593, x = 66.2, y = 76.6 }, objective = "Deliver the glowing crystal to Talanaanis Shadowsong in Valanaar.", desc = "<You reach beneath the still-warm body of the turncoat cultist and recover a small, glowing blue crystal. It appears to be damaged, but it may still be important. High Elder Shadowsong may be interested in this.>" },
    { id = 92645, name = "Breaking the Breaker", level = 11, minLevel = 6, giver = "Yorana Windyreed", start = { npc = "Yorana Windyreed", area = 16593, x = 69.6, y = 67 }, finish = { npc = "Yorana Windyreed", area = 16593, x = 69.6, y = 67 }, steps = { { name = "Commander Belguilos", area = 16593, x = 65.5, y = 65.5 } }, objective = "Slay Commander Belguilos in the Gustberry Lowlands.", desc = "This attack is going to be hard to repel unless we can take out the cult commander. Belguilos \"the Breaker\" they call her, and she's a veritable terror. She used to be a peacekeeper before the cult got out of control, and even then she was... off. As a cultist I can only imagine how much worse she could be now.\n\nI might just be sending you to your death, but someone needs to take Belguilos out if we are going to survive here. You can find her at the villa at the hill's base. Good luck, <class>." },
    { id = 92646, name = "Confront Lorthuna", level = 12, minLevel = 7, faction = "Horde", giver = "Valennia Stormfist", start = { npc = "Valennia Stormfist", area = 16593, x = 65.2, y = 50.4 }, finish = { npc = "Ayessa Dawnsinger", area = 16593, x = 59, y = 79.6 }, objective = "Take the portal to the Rohashi Spires overhead and join Elaadrin Evengale and Ayessa Dawnsinger in their confrontation with the High Priestess Lorthuna.", desc = "Lorthuna fled up to the spires above using some sort of portal. Ayessa and Elaadrin went in after her. That was just a few moments ago.\n\nI'm afraid I took one too many hits and this is where I stay. Go through the portal, find Ayessa and help them stop Lorthuna.\n\nUnless that help that Elaadrin and Ayessa said they sent for arrives soon, you are on your own from here. Good luck, <class>." },
    { id = 92679, name = "Blood Tithe", level = 9, minLevel = 5, giver = "Alvarion Windfield", start = { npc = "Alvarion Windfield", area = 16593, x = 62, y = 73.2 }, finish = { npc = "Aamelia Windfield", area = 16593, x = 46.6, y = 81.8 }, steps = { { name = "Alvarion Windfield", area = 16593, x = 62, y = 73.2 }, { name = "Aamelia Windfield", area = 16593, x = 47.3, y = 79.6 } }, objective = "Listen to what Alvarion Windfield has to say and find Aamelia Windfield at the Windfield Orchard.", desc = "H--Hello, stranger. You have the look of a capable adventurer about you. I...\n\n<The Skyborne man winces, clearly suffering terrible pain>\n\n...I was wondering if you were seeking employment? I came here to Valanaar to recruit fighters to help save my farm. If you are interested, please go find my wife Aamelia Windfield at our orchard to the west of Valanaar, in the lowlands." },
    { id = 92682, name = "Make Yourself Useful", level = 9, minLevel = 5, requires = { 92679 }, giver = "Aamelia Windfield", start = { npc = "Aamelia Windfield", area = 16593, x = 46.6, y = 81.8 }, finish = { npc = "Aamelia Windfield", area = 16593, x = 46.6, y = 81.8 }, steps = { { name = "Hungry Bandit", area = 16593, x = 47.5, y = 80.8 } }, objective = "Gather 10 Ripe Stormapples and slay 5 Hungry Bandits at the Windfield Orchard.", desc = "Oh, so you've got more courage than sense, then? Fine, I won't argue.\n\nFerauu and his goons aren't due to pick up their take of the harvest just yet, so I'm going to put you to work for your meals until they arrive.\n\nHead outside and gather today's batch of stormapples for me. Oh, and the bandits lurking around the stormapple trees... They think they are sneaky. They aren't. Kill them for me.\n\nLet's see what you've got in a fight." },
    { id = 92683, name = "Flutterfly Dust", level = 9, minLevel = 5, giver = "Aamelia Windfield", start = { npc = "Aamelia Windfield", area = 16593, x = 46.6, y = 81.8 }, finish = { npc = "Aamelia Windfield", area = 16593, x = 46.6, y = 81.8 }, objective = "Gather 5 Flutterfly Dust from the Flutterflies around the Gustberry Lowlands.", desc = "I'm sure you've noticed the giant flutterflies out in the outer fields near the orchard? They are pleasant to look at, but they also have other benefits; namely their wing dust. It can be a mess, but if you can gather it up in large amounts, it has useful household applications.\n\nTake this Flutterfly Swatter and give the big bugs a good swat for me. They'll usually just get scared and flee, but sometimes they'll take some offense. Either way, they'll give their rumps a shake and drop a pile of dust." },
    { id = 92684, name = "Ornery Ornery Galestriders", level = 9, minLevel = 5, giver = "Aamelia Windfield", start = { npc = "Aamelia Windfield", area = 16593, x = 46.6, y = 81.8 }, finish = { npc = "Aamelia Windfield", area = 16593, x = 46.6, y = 81.8 }, steps = { { name = "Lowlands Galestrider Tenderloin", area = 16593, x = 51.4, y = 77.6 } }, objective = "Gather 7 Lowlands Galestrider Tenderloins from the Ornery Galestriders found throughout the Gustberry Lowlands.", desc = "As if the harvest wasn't light enough this year already, the galestriders in the area have been getting into the orchard and stealing my stormapples. Think you can head out to the fields and cull them for me?\n\nTake care though stranger, these lowlands galestriders are bigger and angrier than the highlands variety. Watch yourself. A well timed kick is all it takes to put you down for good if you aren't paying attention.\n\nBring me some of their meat and I can make us a hot meal with it as well." },
    { id = 92685, name = "The Hills Have Eyes", level = 9, minLevel = 5, giver = "Aamelia Windfield", start = { npc = "Aamelia Windfield", area = 16593, x = 46.6, y = 81.8 }, finish = { npc = "Aamelia Windfield", area = 16593, x = 46.6, y = 81.8 }, steps = { { name = "Blood-Stained Bandit Mask", area = 16593, x = 47, y = 74.7 } }, objective = "Loot 7 Blood-Stained Bandit Masks from Highwayman Bandits in the Gustberry Lowlands.", desc = "The bandits have camps all over and there's a small one in the hills just north of here. Head up there and start cracking skulls. If we can catch them off guard and take them out before they come for us, we might just even the odds enough to stand a chance.\n\nBring me their masks. The bloodier the better." },
    { id = 92693, name = "Standing Our Ground", level = 9, minLevel = 5, giver = "Aamelia Windfield", start = { npc = "Aamelia Windfield", area = 16593, x = 46.6, y = 81.8 }, finish = { npc = "Aamelia Windfield", area = 16593, x = 46.6, y = 81.8 }, steps = { { name = "Aamelia Windfield", area = 16593, x = 47.3, y = 79.6 }, { name = "Ferauu the Bludgeon", area = 16593, x = 47.6, y = 78 } }, objective = "Speak with Aamelia Windfield when you are ready to confront the bandit leader.", desc = "You've done a lot to give us a fighting chance. Even if we die today, we'll at least know we gave it our best shot.\n\nThis is your last chance, stranger. If you want to head back to Valanaar and live another day, I wouldn't blame you.\n\nOn the other hand, if you really have a thing for lost causes just let me know when you are ready to go. We'll walk out there with our heads held high and whatever happens, happens." },
    { id = 92698, name = "What Is My Purpose?", level = 9, minLevel = 5, giver = "Malfunctioning Cyclone Construct", start = { npc = "Malfunctioning Cyclone Construct", area = 16593, x = 48.8, y = 78.4 }, finish = { npc = "Aamelia Windfield", area = 16593, x = 46.6, y = 81.8 }, desc = "<You lean in close to try and hear the words coming from beneath the giant construct's armor plates.>\n\n...Function error...\n\n...Question...\n\n...What is....\n\n...Function...\n\n<These fragmented words and phrases seem to just repeat. Maybe someone nearby knows more about this construct?>" },
    { id = 92699, name = "The Supreme Magister", level = 9, minLevel = 4, faction = "Alliance", giver = "Valennia Stormfist", start = { npc = "Valennia Stormfist", area = 16593, x = 66.2, y = 76.6 }, finish = { npc = "Elaadrin Evengale", area = 16593, x = 66.6, y = 79.8 }, desc = "Now that you've arrived in Valanaar, you'll likely want to check in with the other members of the High Order here. The current Supreme Magister, Elaadrin Evengale and his people operate out of the lodge on the far southeastern part of Valanaar.\n\nYou should also take care, the High Order and Windshapers don't get along very well here. Be careful and give the Windshapers a good, wide berth. We've got enough to worry about with the cult, I won't tolerate faction violence in the streets of Valanaar." },
    { id = 92700, name = "The Grand Skyseer", level = 9, minLevel = 4, faction = "Horde", giver = "Valennia Stormfist", start = { npc = "Valennia Stormfist", area = 16593, x = 66.2, y = 76.6 }, finish = { npc = "Ayessa Dawnsinger", area = 16593, x = 59, y = 79.6 }, desc = "Now that you've arrived in Valanaar, you'll likely want to check in with the other members of the Windshapers here. The current Grand Skyseer and her people operate out of the lodge near the center of Valanaar.\n\nYou should also be aware, the Windshapers and High Order don't get along very well in these parts. Be careful and give the High Order a good, wide berth. We've got enough to worry about with the cult, I won't tolerate faction violence in the streets of Valanaar." },
    { id = 92701, name = "To Valanaar", level = 9, minLevel = 6, faction = "Alliance", giver = "Constable Aonda", start = { npc = "Constable Aonda", area = 16593, x = 45.6, y = 45.4 }, finish = { npc = "Valennia Stormfist", area = 16593, x = 66.2, y = 76.6 }, objective = "Deliver Aonda's Written Report to Valennia Stormfist in Valanaar.", desc = "For now it seems the pylon and the village are safe, so I'd like you to deliver this report to the Valennia Stormfist in Valanaar, at the southeastern edge of the island. Valennia is the leader of the peacekeepers on the island and she needs to know what happened here.\n\nThe cult is expanding rapidly and the peacekeepers have avoided direct conflict until now, but those days are over. Valanaar will need to be ready for a fight.\n\nAt any rate, thank you. You'll always have friends in Shen'dar, <name>." },
    { id = 92703, name = "Deliver the News", level = 9, minLevel = 5, requires = { 92693 }, giver = "Aamelia Windfield", start = { npc = "Aamelia Windfield", area = 16593, x = 46.6, y = 81.8 }, finish = { npc = "Alvarion Windfield", area = 16593, x = 62, y = 73.2 }, desc = "I guess it doesn't feel quite right to keep calling you stranger after all of this so... thank you, <name>.\n\nIf you wouldn't mind and are back out that way, please let Alvarion know what happened here. Also, tell him that once he's up on his feet he needs to bring a windshaper back here to look at that construct for us to make sure it's safe to have around our... our family.\n\n<Aamelia touches her belly gently.>\n\nHe doesn't know about this part. Let's just keep that bit between us for now." },
    { id = 92708, name = "A Grand Adventure", level = 12, minLevel = 7, faction = "Horde", giver = "Ayessa Dawnsinger", start = { npc = "Ayessa Dawnsinger", area = 16593, x = 59, y = 79.6 }, finish = { npc = "Ayessa Dawnsinger", area = 16593, x = 59, y = 79.6 }, objective = "Listen to what Ayessa Dawnsinger has to say.", desc = "The Windshapers have been hard at work trying to respond to the current crisis on Zephras Isle. We have made several surprising discoveries in our search for the missing wind spirits, and we are developing a plan of action that could help us gain the means to save the island.\n\nWe'll need strong young adventurer's like yourself for this to work however. Please, if you have a moment, let us speak on this further." },
    { id = 92709, name = "A Grand Adventure", level = 12, minLevel = 7, faction = "Alliance", giver = "Elaadrin Evengale", start = { npc = "Elaadrin Evengale", area = 16593, x = 66.6, y = 79.8 }, finish = { npc = "Elaadrin Evengale", area = 16593, x = 66.6, y = 79.8 }, objective = "Listen to what Elaadrin Evengale in Valanaar has to say.", desc = "Your highborne lineage shines as clearly in your eyes as the sky above. You are one of us, and its youth like yourself that will help us save our home. But first, let me tell you more of our mission and plans here on Zephras... and beyond." },
    { id = 92727, name = "The Missing Scholar", level = 10, minLevel = 4, faction = "Alliance", giver = "Dondallion Whisperwind", start = { npc = "Dondallion Whisperwind", area = 16593, x = 66.2, y = 79.8 }, desc = "Seeking knowledge is the primary mandate of the High Order, but this work has never been more dangerous than it is now on Zephras.\n\nOne of our scholars--Fillion Flamebreeze--was en route to the Shen'dar Highlands to study the windborne magic that congregates in some areas there. Regrettably, he has not returned and we fear that something may have befallen him on the road.\n\nIf you can, please locate him for us. He was last seen on the road leading west from Valanaar towards Shen'dar Highlands." },
    { id = 92741, name = "Unwelcome Visitors", level = 13, minLevel = 8, faction = "Alliance", giver = "Iaadaria Bitterwind", start = { npc = "Iaadaria Bitterwind", area = 16593, x = 66.2, y = 79.6 }, finish = { npc = "Iaadaria Bitterwind", area = 16593, x = 66.2, y = 79.6 }, steps = { { name = "Shriekling Talons", area = 16593, x = 59.7, y = 38.9 } }, objective = "Travel to Shadowgale Forest and collect 8 Shriekling Talons for Iaadaria Bitterwind in Valanaar.", desc = "The Shadowgale Forest is incredibly dangerous and is usually off limits to normal adventurers. In recent months there's been an explosion in the shriekling population and they've started to expand their territory outside the woods, which is a potential problem. I have an interest in the alchemical properties of shriekling talons, so a much-needed culling also presents an opportunity for scholarly gain.\n\nTravel to Shadowgale Forest and hunt the beasts. Bring me as many of their talons as you can." },
    { id = 92834, name = "Avenged Tenfold", level = 11, minLevel = 6, requires = { 92840 }, faction = "Alliance", giver = "Elaadrin Evengale", start = { npc = "Elaadrin Evengale", area = 16593, x = 66.6, y = 79.8 }, finish = { npc = "Elaadrin Evengale", area = 16593, x = 66.6, y = 79.8 }, steps = { { name = "Al'Aketh Windstone Charm", area = 16593, x = 63.8, y = 56.9 } }, objective = "Collect 10 Al'Aketh Windstone Charms from Al'Aketh cultists found north of Valanaar at the Gustberry Fields or Shrine of Akir.", desc = "When the cult began their campaign of violence, the Peacekeepers and Windshapers responded with posturing. I saw this as foolish escalation so I advocated for peaceful dialogue. Yesterday I dispatched my friend Belathaan Brightwish to the Shrine of Akir, hoping to establish that dialogue.\n\nA box just arrived containing Belathaan's tongue, dipped in silver pigment.\n\nIts clear to me now that there is no reasoning with the cult. Kill any cultists you see, and bring me the prayer charms that they carry." },
    { id = 92840, name = "Catching Wind", level = 11, minLevel = 5, faction = "Alliance", giver = "Elaadrin Evengale", start = { npc = "Elaadrin Evengale", area = 16593, x = 66.6, y = 79.8 }, finish = { npc = "Elaadrin Evengale", area = 16593, x = 66.6, y = 79.8 }, steps = { { name = "Index Esoteria", area = 16593, x = 48, y = 69 } }, objective = "Take the Index Esoteria to the Overlook Standing Stones in Shen'dar Highlands and use it once there. Protect the Index from harm as it gathers data.", desc = "The same magic that sustains this island can be found lingering around the standing stones in the Shen'dar Highlands. Unfortunately, these are considered sacred sites and are under the direct protection of the Windshapers, which has made it difficult for us to study the magic present there.\n\nWith the Windshapers focused elsewhere, we have an opportunity to study the nature of this elemental magic.\n\nTake this device to the standing stones and protect it as it gathers vital data. Be discreet, please." },
    { id = 92849, name = "The Missing Scholar (1/2)", level = 10, minLevel = 4, faction = "Alliance", finish = { npc = "Fillion Flamebreeze", area = 16593, x = 52, y = 69.4 }, steps = { { name = "Fillion Flamebreeze", area = 16593, x = 50.5, y = 65.4 }, { name = "Fillion Flamebreeze", area = 16593, x = 51.1, y = 67 } }, objective = "Keep searching for Fillion Flamebreeze.", desc = "<Judging by what you've just found, its very likely that Fillion befell some misfortune here. He may still be nearby, and he might be in need of aid. You notice a cave just to the north of your current location. You should continue searching for him there.>" },
    { id = 92850, name = "The Missing Scholar (2/2)", level = 10, minLevel = 4, requires = { 92849 }, faction = "Alliance", giver = "Fillion Flamebreeze", start = { npc = "Fillion Flamebreeze", area = 16593, x = 52, y = 69.4 }, finish = { npc = "Dondallion Whisperwind", area = 16593, x = 66.2, y = 79.8 }, steps = { { name = "Shriekling Matriarch's Head", area = 16593, x = 52.4, y = 66 } }, objective = "Slay the Shriekling Matriarch in the Shriekling Den then return its head to Dondallion Whisperwind in Valanaar.", desc = "I am feeling much better already. I have some skill with the arcane arts and we are but a short distance from Valanaar. I can make it on my own. More important than my safety however is how close to Valanaar these shrieklings have nested and the danger they pose. If you would be so kind, please head back inside and take the head of that beast!\n\nAfter it's done, you'll find me with Dondallion back in Valanaar. I need to return to him as soon as possible. He's probably going to pieces with worry." },
    { id = 92860, name = "In Service of Zephras", level = 12, minLevel = 6, requires = { 92834 }, faction = "Alliance", giver = "Elaadrin Evengale", start = { npc = "Elaadrin Evengale", area = 16593, x = 66.6, y = 79.8 }, finish = { npc = "Valennia Stormfist", area = 16593, x = 66.2, y = 76.6 }, desc = "The High Order has done our best to avoid direct conflict with the cult, but that is clearly no longer an option. Their hostility has been clearly demonstrated, and now there's rumors of larger-scale cult movements around the island. They are clearly gearing up for something and whatever it is can't be good for the people of Zephras.\n\nReport to Valennia Stormfist and inform her that the High Order offers our full support in Valanaar's efforts against the Al'Aketh, should the need arise." },
    { id = 92871, name = "In Service of Zephras", level = 11, minLevel = 6, faction = "Horde", giver = "Ayessa Dawnsinger", start = { npc = "Ayessa Dawnsinger", area = 16593, x = 59, y = 79.6 }, finish = { npc = "Valennia Stormfist", area = 16593, x = 66.2, y = 76.6 }, desc = "Valennia Stormfist and her peacekeepers have ever been the protectors of Zephras, and we've done our best to lend aid where we can. There's rumors of larger-scale cult movements around the island, and they are clearly gearing up for something.\n\nReport to Valennia and reiterate to her that the Windshapers offer their full support in Valanaar's efforts against the Al'Aketh, should the need arise." },
    { id = 92880, name = "Return to Valanaar", level = 11, minLevel = 6, giver = "Yorana Windyreed", start = { npc = "Yorana Windyreed", area = 16593, x = 69.6, y = 67 }, finish = { npc = "Valennia Stormfist", area = 16593, x = 66.2, y = 76.6 }, desc = "I suspect it will take a bit of time for us to mop up what's left of the attackers, but our chances are far better now. Head back to Valanaar and let them know that we are stable here now.\n\nI can't thank you enough for your help. We'd be in much worse shape without you. I asked for reinforcements and it seems that I got a burgeoning hero instead. I'll take that.\n\nMay the four winds bless you, <class>." },
    { id = 92881, name = "The High Elder's Request", level = 11, minLevel = 6, giver = "Valennia Stormfist", start = { npc = "Valennia Stormfist", area = 16593, x = 66.2, y = 76.6 }, finish = { npc = "Talaanis Shadowsong", area = 16593, x = 66.2, y = 76.6 }, desc = "The attack on both the western and eastern watchtowers are not a coincidence. Based on what you told us about what occurred at the western watchtower with that skypriest, our best guess is that the cult is trying to do something to the anchor pylons.\n\nPlease speak with High Elder Shadowsong. He will tell you about a lead that could prove to be promising." },
    { id = 92947, name = "Making Our Move", level = 12, minLevel = 7, requires = { 93065 }, giver = "Valennia Stormfist", start = { npc = "Valennia Stormfist", area = 16593, x = 61.2, y = 71 }, finish = { npc = "Hyusaa Quickbreeze", area = 16593, x = 63.8, y = 50.4 }, steps = { { name = "Al'Aketh Guardian", area = 16593, x = 61.5, y = 51.6 }, { name = "Al'Aketh Spiritcaller", area = 16593, x = 61.2, y = 51.4 }, { name = "Al'Aketh Blademaster", area = 16593, x = 61.3, y = 51.3 }, { name = "Hyusaa Quickbreeze", area = 16593, x = 63.8, y = 50.5 } }, objective = "Slay 8 Al'Aketh Guardians, 6 Al'Aketh Spiritcallers, and 6 Al'Aketh Blademasters, then report to Hyusaa Quickbreeze at the Shrine of Akir.", desc = "Everyone is here, good. I've just sent a few of my best fighters in through the front of the shrine to cause a bit of trouble and serve as a distraction, while I lead the Windshapers and High Order in from the flank.\n\nIf all goes well, we should be able to punch through quickly and take out the High Priestess. As for you, get in there and start cracking skulls. Meet my second, Hyusaa Quickbreeze, near the steps to the shrine after you've caused some trouble.\n\nWinds guide you, <class>." },
    { id = 93036, name = "Infiltrating the Cult", level = 8, minLevel = 5, giver = "Constable Aonda", start = { npc = "Constable Aonda", area = 16593, x = 45.6, y = 45.4 }, finish = { npc = "Sania Silverstream", area = 16593, x = 44.8, y = 45.4 }, desc = "You may or may not be aware of this, but Sania Silverstream over there is a \"missionary\" for the Al'Aketh. They like to play at being a normal religious order and send non-threatening emissaries around to recruit. We've tolerated Sania so far to avoid direct conflict with the cult, but its obvious the illusion of peace won't last much longer.\n\nYou are new here and unknown to most, so I'd like to see if you can use Sania to get close to the cult and find out what their plans are for the village." },
    { id = 93065, name = "Prepare for Battle", level = 12, minLevel = 7, requires = { 92640 }, giver = "Valennia Stormfist", start = { npc = "Valennia Stormfist", area = 16593, x = 66.2, y = 76.6 }, finish = { npc = "Valennia Stormfist", area = 16593, x = 61.2, y = 71 }, steps = { { name = "Valennia Stormfist", area = 16593, x = 61.2, y = 71 } }, objective = "Speak with Valennia Stormfist in the Gustberry Lowlands.", desc = "The Peacekeepers are mobilizing and we are all gearing up to head out. Make whatever preparations you need to make and meet us at the eastern road leading north out of town. We'll have one final check-in with everyone before we move out." },
    { id = 93089, name = "What Comes Next", level = 13, minLevel = 7, requires = { 94369 }, faction = "Alliance", giver = "Talaanis Shadowsong", start = { npc = "Talaanis Shadowsong", area = 16593, x = 66.2, y = 76.6 }, finish = { npc = "Elaadrin Evengale", area = 16593, x = 66.6, y = 79.8 }, desc = "Please extend my thanks to Elaadrin for all that the High Order and your new friends from this \"Kirin Tor\" have done for Zephras Isle. I'm aware of the High Order's plans to leave the island, and your order has my blessing and well-wishes in this expedition.\n\nI can only hope that whatever arcane solution the High Order finds can truly provide us with the stability we've lacked these past years. If you plan to go with them... well, his mission will be all the stronger for it.\n\nWinds be with you, <name>." },
    { id = 93090, name = "What Comes Next", level = 13, minLevel = 7, requires = { 93836 }, faction = "Horde", giver = "Talaanis Shadowsong", start = { npc = "Talaanis Shadowsong", area = 16593, x = 66.2, y = 76.6 }, finish = { npc = "Ayessa Dawnsinger", area = 16593, x = 59, y = 79.6 }, desc = "Please extend my thanks to Ayessa for all that the Windshapers and your new friends from this \"Earthen Ring\" have done for Zephras Isle. I'm aware of the plan to take the Windshapers shamans and leave the island, and your order has my blessing and well-wishes in this expedition.\n\nI can only hope that whatever solution the Windshapers find can truly provide us with the stability we've lacked these past years.\n\nWinds be with you, <name>." },
    { id = 93159, name = "The Strange Hermit", level = 13, minLevel = 8, giver = "Strange Hermit", start = { npc = "Strange Hermit", area = 16593, x = 54, y = 39 }, finish = { npc = "Strange Hermit", area = 16593, x = 54, y = 39 }, steps = { { name = "Strange Hermit", area = 16593, x = 54, y = 39 } }, objective = "Speak with the Strange Hermit in the Shadowgale Forest and learn more about him.", desc = "Uh, um... h-hello, I mean to say, hi! Greetings, even! I'm sorry... its um, been so long since I've actually spoken to another person. I'm afraid I'm a bit rusty at this.\n\n<The strange hooded figure shifts uncomfortably before you.>\n\nSo er, um... how is your day going?" },
    { id = 93160, name = "The Forest's Bounty", level = 13, minLevel = 8, giver = "Strange Hermit", start = { npc = "Strange Hermit", area = 16593, x = 54, y = 39 }, finish = { npc = "Strange Hermit", area = 16593, x = 54, y = 39 }, objective = "Gather 8 Shadowgale Acorns in Shadowgale Forest.", desc = "I do appreciate you stopping by to talk with me! I-If you do want to help out, I could use a bit of help gathering up acorns from the forest floor. I've gathered most of the ones close by but there sure are a lot of raptor-bird things in the forest. It's dangerous out there and I'd rather not become a giant bird's lunch!\n\nSo if you want, you could maybe gather them for me? I'll make us something tasty if you do!" },
    { id = 93165, name = "Mercy Falls on Deaf Ears", level = 13, minLevel = 8, giver = "Vayn Moongaze", start = { npc = "Vayn Moongaze", area = 16593, x = 63.8, y = 36 }, finish = { npc = "Vayn Moongaze", area = 16593, x = 63.8, y = 36 }, steps = { { name = "Al'Alketh Cultist's Ear", area = 16593, x = 63.7, y = 56.8 } }, objective = "Collect 10 Al'Aketh Cultist's Ears from the Al'Aketh cultists in Shadowgale Forest, the Shine of Akir, or Gustberry Lowlands.", desc = "The Al'Aketh have visited great tragedy upon our enclave, and blood must be repaid with blood.\n\nI have an offer for you, stranger. Should you find conflict with these accursed cultists, bring me the ears of those you kill. I will reward you for each that you return with in both coin and, in time, access to the Nightclaw's secrets should you prove yourself to be a true friend." },
    { id = 93172, name = "Free the Hollows", level = 13, minLevel = 8, giver = "Strange Hermit", start = { npc = "Strange Hermit", area = 16593, x = 54, y = 39 }, finish = { npc = "Strange Hermit", area = 16593, x = 54, y = 39 }, steps = { { name = "Wind Hollow", area = 16593, x = 57.9, y = 32.1 } }, objective = "Destroy 10 Wind Hollows in Shadowgale Forest.", desc = "Most of the elves on this island seem to think that these woods are haunted, and they aren't wrong.\n\nAt the old ruins to the northeast, a strange type of ghost-like spirits gather. Some nights, you can almost hear them \"singing\". It's not like any song I've heard before, but its definitely a song and its... just so sad.\n\nI'm not sure why, but I think something terrible happened there at some point, and the spirits are trapped there somehow. If you are feeling brave, maybe you can help set them free?" },
    { id = 93317, name = "Crab Season", level = 9, minLevel = 4, giver = "Nyalah Brightfire", start = { npc = "Nyalah Brightfire", area = 16593, x = 60.6, y = 72.6 }, finish = { npc = "Nyalah Brightfire", area = 16593, x = 60.6, y = 72.6 }, steps = { { name = "Windsong Crawler Meat", area = 16593, x = 56.2, y = 59.1 } }, objective = "Collect 6 pieces of Windsong Crawler Meat.", desc = "Are you familiar with Windsong Crawlers? You see, these crabs are native only to Windsong Lake here on Zephras, and they are only able to be harvested a few weeks of the year.\n\nWith all of the cult activity of late, I've not been able to get out to the lake to harvest them, and our window is rapidly closing. I'd be appreciative if you could go and gather some for me. They can generally be found along the shorelines around the lake and in rivers.\n\nDo be careful though, they are meaner than they look!" },
    { id = 93318, name = "WANTED: Vulgara the Insatiable", level = 9, minLevel = 4, finish = { npc = "Danarii Bellowveil", area = 16593, x = 45.2, y = 45.2 }, steps = { { name = "Vulgara's Head", area = 16593, x = 42.6, y = 52.2 } }, objective = "Kill Vulgara the Insatiable in the Shen'dar Highlands and bring her head to Danarii Bellowveil.", desc = "By order of Constable Aonda of the Peacekeepers, a bounty is hereby placed upon the scourge of the highlands, Vulgara the Insatiable. Last spotted on a hilltop rise just southwest of Shen'dar Village, the winged vuldren terror is highly dangerous and should be approached with caution.\n\nDeliver the beast's head to Danarii Bellowveil to receive your reward." },
    { id = 93319, name = "Pilfered Windstones", level = 7, minLevel = 4, giver = "Teeri Wellwind", start = { npc = "Teeri Wellwind", area = 16593, x = 44.4, y = 45 }, finish = { npc = "Teeri Wellwind", area = 16593, x = 44.4, y = 45 }, steps = { { name = "Pilfered Windstone", area = 16593, x = 48.9, y = 36.5 } }, objective = "Collect 10 Pilfered Windstones from the Highlands Bandits in the Shen'dar Highlands.", desc = "We are relying on windstones more and more for day to day living here on Zephras so we try and maintain a cache of them in reserve for emergencies. Lately I've noticed some go missing from our stores.\n\nWe've found windstones on bandits we've captured recently, and I suspect they are behind our shortages.\n\nIf you find yourself near the bandit cave to the north, mind knocking a few heads together and reclaiming some of our pilfered windstones for me?" },
    { id = 93320, name = "Tower Defense", level = 11, minLevel = 6, giver = "Valennia Stormfist", start = { npc = "Valennia Stormfist", area = 16593, x = 66.2, y = 76.6 }, finish = { npc = "Yorana Windyreed", area = 16593, x = 69.6, y = 67 }, desc = "I've just received word that the cult is attacking the pylon watchtower just outside of town! I've sent the few extra peacekeepers we have here to try and break through the enemy back line to relieve the defenders, but any additional help could mean the difference between our people there living or dying.\n\nPlease leave immediately for the east watchtower and provide whatever aid you can.\n\nMy lieutenant Yorana Windyreed led the relief force. If she still lives she can tell you how best to help." },
    { id = 93459, name = "More Al'Aketh Ears", level = 13, minLevel = 8, finish = { npc = "Vayn Moongaze", area = 16593, x = 63.8, y = 36 }, objective = "Collect 10 Al'Aketh Cultist's Ears from the Al'Aketh in Shadowgale Forest, the Shine of Akir, or Gustberry Lowlands and return them to Vayn Moonclaw in Shadowgale Forest.", desc = "The Al'Aketh cult normally gives this forest a wide berth, fearing the rumors that it is haunted... rumors we are happy to maintain. The Druids of my order wish only to live quiet, peaceful lives here in Shadowgale and they threaten that.\n\nMany among us are afraid.\n\nI come with an offer. Fight the cultists for us, and bring us the ears of those you kill. We will reward you for each that you return with in both coin and, in time, access to our secrets should you prove yourself to be a true friend." },
    { id = 93461, name = "Welcome to Shen'dar Village", level = 6, minLevel = 4, faction = "Alliance", giver = "Constable Aonda", start = { npc = "Constable Aonda", area = 16593, x = 45.6, y = 45.4 }, finish = { npc = "Constable Aonda", area = 16593, x = 45.6, y = 45.4 }, steps = { { name = "Rathiril Sunlance", area = 16593, x = 45, y = 46.4 }, { name = "Coriella Calmbreeze", area = 16593, x = 43, y = 43.2 } }, objective = "Speak with Rathiril Sunlance and Coriella Calmbreeze in Shen'dar Village.", desc = "You've got that \"High Order\" look to you. Those with Highborne ancestry always seem to have a slight twinkle in their eyes that gives it away. Before I properly put you to work around here, you should check in with our resident High Order elder Rathiril Sunlance. You can find him here in the main lodge, just around the corner from me.\n\nOh, and check in with Coriella Calmbreeze as well, she runs the local inn and can provide lodging and supplies, should you need them." },
    { id = 93552, name = "Harvesting Windstones", level = 4, minLevel = 2, giver = "Dalia the Collector", start = { npc = "Dalia the Collector", area = 16593, x = 43.2, y = 24 }, finish = { npc = "Dalia the Collector", area = 16593, x = 43.2, y = 24 }, objective = "Collect 15 Windstone Clusters from Raw Windstones in Thendal Grove.", desc = "Windstones are a critical resource on Zephras Isle as they contain the raw, concentrated energy of the winds themselves. The wind elementals who used to live here on zephras with us vanished several centuries ago, and since then, the magic that sustains this island is slowly fading. Not without limitations, the Windstones are still a reliable energy source, and are incredibly valuable to us.\n\nYou'll find raw Windstones scattered around the grove, think you can help me harvest them?" },
    { id = 93735, name = "The Broken Construct", level = 9, minLevel = 4, faction = "Horde", giver = "Ayessa Dawnsinger", start = { npc = "Ayessa Dawnsinger", area = 16593, x = 59, y = 79.6 }, finish = { npc = "Riaani Nightwind", area = 16593, x = 59, y = 73 }, desc = "Historically, the Windshapers have seen to the tending of the magical instruments and devices that were gifted to us by the spirits of the wind. This includes the myriad of magical constructs around the island. Since the spirits left us, only a scant few of these are still functional.\n\nOne of the few remaining working constructs in Valanaar has become damaged. One of our artisans was dispatched to help, but he may be in need of aid. Travel to the west end of the city and offer any assistance you can." },
    { id = 93736, name = "Unwelcome Spirits", level = 9, minLevel = 4, faction = "Horde", giver = "Endaria Mistgaze", start = { npc = "Endaria Mistgaze", area = 16593, x = 58.2, y = 78.4 }, finish = { npc = "Endaria Mistgaze", area = 16593, x = 58.2, y = 78.4 }, steps = { { name = "Wind Hollow Essence", area = 16593, x = 57.9, y = 32.1 } }, objective = "Gather 10 Wind Hollow Essences from Wind Hollows in the Shadowgale Forest.", desc = "The paramount concern of the Windshapers is to better understand why the spirits left us, and what we may be able to do to bring them back. One curious fixture of Shadowgale Forest to the north is the presence of a curious form of wind sprite that some call \"hollows\". We know little of them and why they are there, but we do know that they first started to appear after the spirits of the wind left us.\n\nI need you to go there and disperse them. Gather the remains and bring them back here." },
    { id = 93737, name = "The Broken Construct (1/2)", level = 9, minLevel = 4, faction = "Horde", giver = "Riaani Nightwind", start = { npc = "Riaani Nightwind", area = 16593, x = 59, y = 73 }, finish = { npc = "Riaani Nightwind", area = 16593, x = 59, y = 73 }, steps = { { name = "Riaani Nightwind", area = 16593, x = 59, y = 73 } }, objective = "Speak with Rianni Nightwind and list to what he has to say.", desc = "Oh, hello. Ayessa sent you to assist me? Very well then.\n\nNot sure what an obvious novice like yourself can do, but if you give me a moment to pull my head out of this construct's innards I might have a few ideas of things you can do to help." },
    { id = 93738, name = "The Broken Construct (2/2)", level = 9, minLevel = 4, requires = { 93737 }, faction = "Horde", giver = "Riaani Nightwind", start = { npc = "Riaani Nightwind", area = 16593, x = 59, y = 73 }, finish = { npc = "Ayessa Dawnsinger", area = 16593, x = 59, y = 79.6 }, desc = "Brightwish, eh? So the High Order wanted to remove these components for some reason. But why though?\n\nThe High Order has always been meddlesome, constantly wanting to experiment with the wind spirits' magic. They are too bold by a mile, and we've strictly forbade them from meddling with knowledge under Windshaper purview, but lately they've been testing our patience.\n\nI think you should report what you've learned back to Ayessa Dawnsinger. She can instruct you further on what to do." },
    { id = 93740, name = "Blood for Blood", level = 11, minLevel = 6, faction = "Horde", giver = "Ayessa Dawnsinger", start = { npc = "Ayessa Dawnsinger", area = 16593, x = 59, y = 79.6 }, finish = { npc = "Ayessa Dawnsinger", area = 16593, x = 59, y = 79.6 }, steps = { { name = "Al'Aketh Windstone Charm", area = 16593, x = 63.8, y = 56.9 } }, objective = "Collect 10 Al'Aketh Windstone Charms from the corpses of Al'Aketh cultists in the Gustberry Lowlands.", desc = "A number of our Windshaper novices were found dead in the Highlands this morning. We can't be certain but there is a strong chance that the Al'Aketh are responsible. Windshapers trade blood for blood, every time.\n\nHead north and kill any Al'Aketh you encounter. Bring me their windstone prayer charms as proof of the deed. We do not forgive and we do not forget." },
    { id = 93746, name = "A Firm Response", level = 9, minLevel = 4, faction = "Horde", giver = "Ayessa Dawnsinger", start = { npc = "Ayessa Dawnsinger", area = 16593, x = 59, y = 79.6 }, finish = { npc = "Ayessa Dawnsinger", area = 16593, x = 59, y = 79.6 }, steps = { { name = "Belathaan Brightwish", area = 16593, x = 59.8, y = 57 } }, objective = "Confront Belthaan Brightwish along the road to the Shrine of Akir.", desc = "The High Order has been warned of the consequences of meddling with the Windshaper's affairs. I think we need to make an example out of Belathaan and send him back to the High Order with a few bruises and a healthy respect for the boundaries we set.\n\nBelathaan was seen leaving town, traveling north towards the Shrine of Akir. I don't know why he was going there, but confronting him alone on the road is the safest option. Find him, and put a bit of fear into his heart." },
    { id = 93835, name = "Confront Lorthuna", level = 12, minLevel = 7, faction = "Alliance", giver = "Valennia Stormfist", start = { npc = "Valennia Stormfist", area = 16593, x = 65.2, y = 50.4 }, finish = { npc = "Elaadrin Evengale", area = 16593, x = 66.6, y = 79.8 }, objective = "Take the portal to the Rohashi Spires overhead and join Elaadrin Evengale and Ayessa Dawnsinger in their confrontation with High Priestess Lorthuna.", desc = "Lorthuna fled up to the spires above using some sort of portal. Ayessa and Elaadrin went in after her. That was just a few moments ago.\n\nI'm afraid I took one too many hits and this is where I stay. Go through the portal, find Elaadrin and help them stop Lorthuna.\n\nUnless that help that Elaadrin and Ayessa said they sent for arrives soon, you are on your own from here. Good luck, <class>." },
    { id = 93836, name = "The Fate of Zephras", level = 12, minLevel = 7, requires = { 92646 }, faction = "Horde", giver = "Ayessa Dawnsinger", start = { npc = "Ayessa Dawnsinger", area = 16593, x = 59, y = 79.6 }, finish = { npc = "Talaanis Shadowsong", area = 16593, x = 66.2, y = 76.6 }, steps = { { name = "Talaanis Shadowsong", area = 16593, x = 66.2, y = 76.5 } }, objective = "Speak with Talaanis Shadowsong in Valanaar.", desc = "Muln has told me much of the elemental lords and I am afraid that we have good reason to fear Al'Akir. Now that the wards that have hidden Zephras from his view are down, we are utterly defenseless.. If he chooses to attack us, we stand no chance against him here in his own domain.\n\nHigh Elder Shadowsong needs to know of the danger we are in, and more importantly, what our intentions are for our mission to Azeroth. We will find the means to save our home. I swear it." },
    { id = 93926, name = "The Western Watch", level = 8, minLevel = 5, giver = "Constable Aonda", start = { npc = "Constable Aonda", area = 16593, x = 45.6, y = 45.4 }, finish = { npc = "Peacekeeper Vaaniel", area = 16593, x = 42.4, y = 62 }, steps = { { name = "Peacekeeper Vaaniel", area = 16593, x = 42.4, y = 62 } }, objective = "Find Peacekeeper Vaaniel at the western watchtower.", desc = "Whatever reason the cult has for attacking the tower, it's not worth losing our people over.\n\nI'd like for you to head to the southwest and check in on that watchtower for us. Find the peacekeepers there and tell them to head back to the village. Holding that tower is not worth the lives it would cost and I'd rather concentrate the defenders we do have here to protect our citizens.\n\nPeacekeeper Vaaniel is in charge, let him know to head back here as quickly as possible. Hurry!" },
    { id = 93927, name = "A Last Request", level = 8, minLevel = 5, requires = { 93926 }, giver = "Peacekeeper Vaaniel", start = { npc = "Peacekeeper Vaaniel", area = 16593, x = 42.4, y = 62 }, finish = { npc = "Constable Aonda", area = 16593, x = 45.6, y = 45.4 }, steps = { { name = "Skypriest Aanders", area = 16593, x = 41, y = 64.3 } }, objective = "Collect the note you found near the dead peacekeeper and read it to determine your next steps.", desc = "<As you inspect the body of the dead peacekeeper, a bloody note falls free of his hands. Picking it up and reading it may give you a clue as to how to proceed from here.>" },
    { id = 93948, name = "Deliver the Signet", level = 9, minLevel = 6, giver = "Constable Aonda", start = { npc = "Constable Aonda", area = 16593, x = 45.6, y = 45.4 }, finish = { npc = "Talaanis Shadowsong", area = 16593, x = 66.2, y = 76.6 }, objective = "Deliver the Shadowsong Family Signet to Talaanis Shadowsong in Valanaar.", desc = "Since you are going to Valanaar anyway, please deliver the signet ring you recovered from the tower to Talaanis Shadowsong in Valanaar.\n\nHe will want this back, and more importantly, he will want to learn the fate of his nephew. Talaanis is the High Elder of Zephras Isle and more importantly, he is a good man who is well loved by the people, despite our current hardships. It pains me to think of how he will react to this news. Please express my condolences for his loss." },
    { id = 93949, name = "Bugged", level = 8, minLevel = 6, giver = "Valennia Stormfist", start = { npc = "Valennia Stormfist", area = 16593, x = 66.2, y = 76.6 }, finish = { npc = "Valennia Stormfist", area = 16593, x = 66.2, y = 76.6 }, objective = "Kill Skyhoppers in Valanaar until you've eliminated 8 enchanted Skyhoppers.", desc = "We've been bugged.\n\nIt's skyhopper season in the lowlands, which means the pests are everywhere. One of the High Order mages reported that one of the insects that they killed had an enchantment of some kind placed upon it. When we inspected it closely it seems to be some sort of listening spell.\n\nWe suspect that the cult is using these enchanted insects as spies. Go and exterminate them for us. You won't be able to tell which are enchanted by looking at them, so you'll just have to kill them all." },
    { id = 93951, name = "A Little Beauty", level = 7, minLevel = 4, giver = "Taleen Shimmerthread", start = { npc = "Taleen Shimmerthread", area = 16593, x = 44.8, y = 44.2 }, finish = { npc = "Taleen Shimmerthread", area = 16593, x = 44.8, y = 44.2 }, objective = "Collect 8 Hippogryph Down feathers in the Shen'dar Highlands.", desc = "The Hippogryph that have taken up residence southwest of the village can be a nuisance, but they also present a rather unique opportunity to obtain their feathers. Many skyborne love to adorn their hair with vibrant plumes and the down feathers of a hippogryph are exceptionally vibrant and more importantly, silky soft.\n\nIf you are heading that way, try and gather as many of the fallen feathers as you can from in and around their nesting grounds. Do be careful, as wild hippogryph are not tolerant of guests." },
    { id = 93958, name = "The Inner Sanctum", level = 12, minLevel = 7, giver = "Hyusaa Quickbreeze", start = { npc = "Hyusaa Quickbreeze", area = 16593, x = 63.8, y = 50.4 }, finish = { npc = "Valennia Stormfist", area = 16593, x = 65.2, y = 50.4 }, desc = "Valennia's forces just breached the inner sanctum. The fighting was thick in there at first, but it's grown... unsettlingly quiet. Go in there and do your best to link up with Valennia and her forces... if any of them are left.\n\nI'll stay here and watch your back." },
    { id = 94369, name = "The Fate of Zephras", level = 12, minLevel = 7, requires = { 93835 }, faction = "Alliance", giver = "Elaadrin Evengale", start = { npc = "Elaadrin Evengale", area = 16593, x = 66.6, y = 79.8 }, finish = { npc = "Talaanis Shadowsong", area = 16593, x = 66.2, y = 76.6 }, steps = { { name = "Talaanis Shadowsong", area = 16593, x = 66.2, y = 76.5 } }, objective = "Speak with Talaanis Shadowsong in Valanaar.", desc = "Ansirem has told me much of the elemental lords and I am afraid that we have good reason to fear Al'Akir now that the wards that have hidden Zephras are down. If the Windlord chooses to attack us, we stand no chance to defend ourselves while we are here in his domain.\n\nHigh Elder Shadowsong needs to know of the danger we are in, and more importantly, what our intentions are for our mission to Azeroth. We will find the means to save our home. I swear it." },
    { id = 94411, name = "Meddlesome Mages", level = 6, minLevel = 4, faction = "Horde", giver = "Illaya Amberwind", start = { npc = "Illaya Amberwind", area = 16593, x = 43.6, y = 44.8 }, finish = { npc = "Illaya Amberwind", area = 16593, x = 43.6, y = 44.8 }, steps = { { name = "High Order Apprentice", area = 16593, x = 46.4, y = 38.9 } }, objective = "Slay 6 High Order Apprentices in Shen'dar Highlands.", desc = "Be warned, members of the High Order have been seen in the vicinity of the standing stones north of the village. We have warned them time and again to not meddle at our sacred sites, but they are growing more bold in pushing us. Prove your resolve to us by going to the standing stones and dispersing them.\n\nI am loathe to condone outright bloodshed, but do what you must to drive them off. Return to me when its done." },
    { id = 94413, name = "A Magical Affront", level = 6, minLevel = 4, faction = "Alliance", giver = "Rathiril Sunlance", start = { npc = "Rathiril Sunlance", area = 16593, x = 45, y = 46.4 }, finish = { npc = "Rathiril Sunlance", area = 16593, x = 45, y = 46.4 }, steps = { { name = "Windshaper Novice Seer", area = 16593, x = 38.9, y = 47.3 } }, objective = "Slay 6 Windshaper Novice Seers in Shen'dar Highlands.", desc = "The recent emergence of the ley lines on the surface of Zephras has been profound for our order. We have more direct and tangible access to the energies that permeate this place and it has increased our understanding of said magic greatly.\n\nThe Windshapers, however, view these emergences as scars on the land that must be \"healed\". This is an affront to our order and is something we simply cannot abide.\n\nGo to the ley line in the forest to the southwest and drive off the Windshapers you find there." },
    { id = 94414, name = "The Anchors of Zephras", level = 2, minLevel = 2, giver = "Halaan Hawk-Eye", start = { npc = "Halaan Hawk-Eye", area = 16593, x = 43.8, y = 24 }, finish = { npc = "Halaan Hawk-Eye", area = 16593, x = 43.8, y = 24 }, objective = "Speak with Halaan Hawk-Eye and borrow his gift to view the anchor pylon in the distance.", desc = "Greetings, young <name>. I often times come here to look upon the ancient anchor pylon. Gifts from the spirits of the winds, they bind and sustain our island. Of late however, their magic has grown unstable and inconsistent.\n\nThey suffer no distress I can see. Their splendor has not changed.\n\nIf you'd like, I can lend you my gift to look upon them yourself." },
    { id = 94484, name = "Unnerving Silence", level = 11, minLevel = 8, giver = "Lotheluum Starbreeze", start = { npc = "Lotheluum Starbreeze", area = 16593, x = 64, y = 75 }, finish = { npc = "Elegael Thornpaw", area = 16593, x = 61.6, y = 39.2 }, desc = "A moment, if you will <name>. Are you headed towards Shadowgale Forest? There is a druid conclave there in a cave to the northeast. I have been waiting on word from them but their correspondence is long overdue.\n\nWith Ban'aethall in ruins and all the unrest lately I worry something dire may have happened. Please, if you are able go, seek out Elegael Thornpaw and put my mind at ease." },
    { id = 94485, name = "Tears of the Lady", level = 12, minLevel = 8, giver = "Elegael Thornpaw", start = { npc = "Elegael Thornpaw", area = 16593, x = 61.6, y = 39.2 }, finish = { npc = "Elegael Thornpaw", area = 16593, x = 61.6, y = 39.2 }, objective = "Collect 8 Lady's Tear Moss.", desc = "If we are to save my fellows in the Nightclaw Den, I am going to need some ingredients for a poultice. The first and most important is a spindly moss called Lady's Tear. It typically grows on the base of the trees here in Shadowgale.\n\nThis moss secretes a sticky substance that acts as an antiseptic and is perfect for binding open wounds. I have gathered what little I can reach but I know there is more in this forest.\n\nGo and be swift. We are going to need a lot if the injured I left behind still live." },
    { id = 94486, name = "Feathers for Binding", level = 11, minLevel = 8, giver = "Elegael Thornpaw", start = { npc = "Elegael Thornpaw", area = 16593, x = 61.6, y = 39.2 }, finish = { npc = "Elegael Thornpaw", area = 16593, x = 61.6, y = 39.2 }, steps = { { name = "Pristine Shriekling Feather", area = 16593, x = 59.7, y = 38.9 } }, objective = "Collect 20 feathers from the Shadowgale Shrieklings in Shadowgale Forest.", desc = "The other ingredient I need for the poultice is feathers from the Shadowgale shrieklings that roam this forest. In their juvenile form, the shrieklings have insulative feathers which would be ideal to put over the moss. These feathers will prevent the antiseptic sap from drying out and will provide at least some protection against the elements.\n\nBe warned, the shrieklings are normally docile but they have been incredibly hostile of late. Their large talons can easily disembowel you if you aren't careful." },
    { id = 94487, name = "Unwanted and Unworthy", level = 11, minLevel = 8, giver = "Elegael Thornpaw", start = { npc = "Elegael Thornpaw", area = 16593, x = 61.6, y = 39.2 }, finish = { npc = "Elegael Thornpaw", area = 16593, x = 61.6, y = 39.2 }, steps = { { name = "Bloody Heirloom", area = 16593, x = 63.8, y = 37.3 } }, objective = "Collect 10 Bloodied Heirlooms from Al'Aketh Footsoldiers and Al'Aketh Stormchasers in the Shadowgale Forest.", desc = "The Al'aketh Cultists ambushed us with no warning, though their motives remain a mystery to me. I knew these cultists had clouds in-between their ears, but I never imagined they would upset the delicate balance here on Zephras with such brutality. Go, slay as many as you can and take their heirlooms if they wear any.\n\n<Elegael spits.>\n\nThese storm cursed cultists don't deserve to be called shen'dorei. The beasts of the forest can have their bodies. Their ashes don't deserve the winds." },
    { id = 94488, name = "The Ties That Bind", level = 11, minLevel = 8, giver = "Elegael Thornpaw", start = { npc = "Elegael Thornpaw", area = 16593, x = 61.6, y = 39.2 }, finish = { npc = "Elegael Thornpaw", area = 16593, x = 61.6, y = 39.2 }, steps = { { name = "Commander Haalien's Severed Head", area = 16593, x = 65.5, y = 36.5 } }, objective = "Kill Commander Haalien and bring his head to Elegael Thornpaw in the Shadowgale Forest.", desc = "The reason for cultists presence here still baffles me, but I smell a familiar scent over the bloodshed.\n\nOne of our circle druids, Haalien, disappeared months back. It appears he's thrown his sorry hide in with the cultists.\n\nShow him what happens when he spills the blood of his kin! Take his head and return it to me." },
    { id = 94489, name = "The Wounds of Betrayal", level = 12, minLevel = 8, giver = "Elegael Thornpaw", start = { npc = "Elegael Thornpaw", area = 16593, x = 61.6, y = 39.2 }, finish = { npc = "Elegael Thornpaw", area = 16593, x = 61.6, y = 39.2 }, steps = { { name = "Jorel Windsinger", area = 16593, x = 64.5, y = 34.5 }, { name = "Naaleos Leafwhisper", area = 16593, x = 64.8, y = 34.8 }, { name = "Telenos \nLeafwhisper", area = 16593, x = 64.6, y = 35 }, { name = "Nayeela Snarlfang", area = 16593, x = 64.5, y = 34.8 }, { name = "Neyasteel Mossmender", area = 16593, x = 64, y = 32 }, { name = "Bryaes Galechaser", area = 16593, x = 64.4, y = 31.8 }, { name = "Mithraless Sterngale", area = 16593, x = 65.8, y = 32.8 }, { name = "Baeo Sharpstrike", area = 16593, x = 65.8, y = 33.4 } }, objective = "Enter the Nightfang Den and heal 7 druids and find Jorel Windsinger in Shadowgale Forest.", desc = "I have finished the poultices. Quickly, take them to the druids in the cave, north just across the clearing. I know my brethren are in much more dire condition than I. They are likely too injured to heal their own wounds. There are so few of us shen'dorei druids that every life is precious.\n\nBefore you go, I have a selfish request. My mate, Jorel Windsinger was in dire condition when I left. Please, see to his wounds if he still lives." },
    { id = 94490, name = "Ripped Missive", level = 12, minLevel = 9, finish = { npc = "Elegael Thornpaw", area = 16593, x = 61.6, y = 39.2 }, objective = "Bring the Ripped Missive to Elegael Thornpaw in the Shadowgale Forest.\n\nProvided item:", desc = "<Tucked behind one of Haalien's bracers is a note that's been slightly torn and bloodstained in your fight. It looks like it contains useful information for about the cultist motivations for the attack on the druid den. Elegael would be interested in this intel.>" },
    { id = 94491, name = "The Fate of the Den", level = 12, minLevel = 8, giver = "Elegael Thornpaw", start = { npc = "Elegael Thornpaw", area = 16593, x = 61.6, y = 39.2 }, finish = { npc = "Lotheluum Starbreeze", area = 16593, x = 64, y = 75 }, objective = "Give the missive to Lotheluum in Valannar and tell him what has transpired.\n\nProvided item:", desc = "It would appear that there is a correspondent hiding somewhere in Valanaar feeding information to the cult. I am clearly in no shape to make the journey, but Lotheluum needs to know what transpired here.\n\nHe should also know the fate of those who are no longer with us. Thanks to your help I think we can handle the rest of the situation from here, thought the damage has been done.\n\nPlease go swiftly, <name>. I hope our paths will cross again someday. Until then, I have cultists to slay." },
    { id = 94493, name = "A Sacrifice in Vain", level = 11, minLevel = 8, faction = "Alliance", giver = "Elegael Thornpaw", start = { npc = "Elegael Thornpaw", area = 16593, x = 61.6, y = 39.2 }, finish = { npc = "Elegael Thornpaw", area = 16593, x = 61.6, y = 39.2 }, desc = "Thank goodness our message got to Lotheluum. Wait, where are the rest of the reinforcements? Surely it is not just you they sent?\n\n<Elegael pales as you explain yourself.>\n\nSo the message did not get to Valanaar. We are in dire straights indeed then.\n\n<Elegael sighs deeply then looks resolute.>\n\nThen we must handle this on our own. Time is of the essence." },
    { id = 94559, name = "UNUSED", level = 11, minLevel = 6, objective = "Seek out the Al'Aketh Turncoat in the Shen'dar Highlands.", desc = "There is a turncoat amongst the Al'Aketh. They claim to know the cult's true intentions for the island and want to come in, but will only do so with assurances of protection.\n\nThis defector is hiding at a house just northwest of Valanaar, just inside the highlands. I need someone who can discreetly go there, find the traitor, find out and escort him back to us. This might be a trap, but if this information is as important as this traitor claims, its worth some risk." },
    { id = 94568, name = "The Cult's True Plans", level = 11, minLevel = 6, requires = { 92644 }, giver = "Talaanis Shadowsong", start = { npc = "Talaanis Shadowsong", area = 16593, x = 66.2, y = 76.6 }, finish = { npc = "Talaanis Shadowsong", area = 16593, x = 66.2, y = 76.6 }, objective = "Speak with Talaanis Shadowsong and observe the conversation.", desc = "The turncoat clearly was afraid of the what the cult had planned, enough so to defect and seek our aid. It's truly unfortunate that he is dead and took his secrets to the grave with him.\n\nWe must discuss this further to determine our next steps." },
    { id = 94896, name = "Aid For The Refugees", level = 11, minLevel = 8, giver = "Ealaane Nimbuswalker", start = { npc = "Ealaane Nimbuswalker", area = 16593, x = 65.8, y = 74.4 }, finish = { npc = "Ealaane Nimbuswalker", area = 16593, x = 65.8, y = 74.4 }, objective = "Collect 8 Abandoned Belongings from the ruins of Ban'aethal.", desc = "You look like a capable adventurer. Do you happen to be headed towards Shadowgale Forest? Ban'aethal lies deep in the forest; that's where we're all from.\n\n<Ealaane gestures to the other refugees.>\n\nWe've recently had to evacuate Ban'aethal, as it began to fall into the sky. It was sudden and in the middle of the night. If you are headed that way, would you please look for any belongings left behind? The forest and village are far too dangerous for us to return to now." },
    { id = 94897, name = "The Fate of a Loved One", level = 11, minLevel = 8, giver = "Ealaane Nimbuswalker", start = { npc = "Ealaane Nimbuswalker", area = 16593, x = 65.8, y = 74.4 }, finish = { npc = "Ealaane Nimbuswalker", area = 16593, x = 65.8, y = 74.4 }, steps = { { name = "Resaan's Heirloom", area = 16593, x = 57, y = 29.5 } }, objective = "Find Resaan in the Ruins of Ban'aethal.", desc = "If you are traveling to Ban'aethal, I have a selfish request. My love, Resaan... I believe is no longer a part of this world. He had tried to go back to get supplies even though I begged him to stay. It has been over a week already and I fear the worst.\n\nPlease, if you find him bring him home. If he has perished then I beg you to please bring me his heirloom." },
    { id = 94898, name = "Violent Winds (Temp Disabled)", level = 11, minLevel = 8, steps = { { name = "Wind Hollow", area = 16593, x = 57.9, y = 32.1 } }, objective = "Slay 10 Wind Hollows.", desc = "When our home started to fall into the sky that fateful night, its as if the elements themselves were waiting to consume us. Wind spirits began appearing as we were fleeing, and to our dismay they began attacking the fleeing survivors.\n\nWe lost many villagers to the sky, but even more to the relentless anger of those wind spirits. I don't know if it was our village falling into the sky, but they are extremely dangerous.\n\nIf you are able, please put them to rest." },
    { id = 94901, name = "Hopping Helpers", level = 11, minLevel = 8, objective = "Collect $1oa Gustjumper frogs.", desc = "[PH] Collect frogs" },
    { id = 94902, name = "Valanaar Vintages", level = 11, minLevel = 8, objective = "Collect $1oa grapes.", desc = "[PH] Collect grapes from the vineyard" },
    { id = 94946, name = "The Magical City of Dalaran", level = 13, minLevel = 7, requires = { 93089 }, faction = "Alliance", giver = "Elaadrin Evengale", start = { npc = "Elaadrin Evengale", area = 16593, x = 66.6, y = 79.8 }, finish = { npc = "Denaaris Stargale", area = 36, x = 12.4, y = 56.2 }, desc = "I had intended to be the first of us to step foot onto Azeroth, but recent events with the cult have changed my plans. As a result, I will be remaining here in Valanaar for a time. Fret not though, one of our mages will be waiting to receive you upon your arrival in Dalaran. I'd encourage you to explore Azeroth while we set our affairs in order here. We will call upon you when you are needed.\n\nWhen you are ready, please proceed to the dock just outside this lodge and board the skycutter ship there." },
    { id = 95349, name = "The Earthen Ring", level = 13, minLevel = 7, requires = { 93090 }, faction = "Horde", giver = "Ayessa Dawnsinger", start = { npc = "Ayessa Dawnsinger", area = 16593, x = 59, y = 79.6 }, finish = { npc = "Alaana Stormwalker", area = 215, x = 34.9, y = 31.9 }, desc = "The recent events with the cult have delayed my plans to travel to Azeroth and I must remain here in Valanaar for a time. You and a handful of other Windshapers will be our vanguard instead. Alaana Stormwalker will be waiting to receive you upon your arrival in Mulgore, and I'd encourage you to explore Azeroth while we finish our business here. We will join you soon.\n\nWhen you are ready, please proceed to the dock just outside this lodge and board the skycutter ship there. Banu-Alah, <name>." },
    { id = 98512, name = "Al'Aketh Assassins", level = 11, minLevel = 6, giver = "Fendaal Windstone", start = { npc = "Fendaal Windstone", area = 16593, x = 56.8, y = 61 }, finish = { npc = "Fendaal Windstone", area = 16593, x = 56.8, y = 61 }, steps = { { name = "Al'Aketh Assassin", area = 16593, x = 55.6, y = 60 } }, objective = "Kill 10 Al'Aketh Assassins in the Shen'dar Highlands.", desc = "You there, stranger. Get low and keep quiet. We are not alone here.\n\nI was on patrol near the border and noticed that there are a number of Al'Aketh skulking around the house just up the hill there to the north. I don't know what they are doing here, but it can't be good.\n\nIf you want to make yourself useful, get in there and take them out. I'll wait here and watch your back." },
    { id = 99260, name = "Fillion's Mission (3/6)", level = 10, minLevel = 5, requires = { 92850 }, faction = "Alliance", giver = "Fillion Flamebreeze", start = { npc = "Fillion Flamebreeze", area = 16593, x = 66.2, y = 79.8 }, finish = { npc = "Elaadrin Evengale", area = 16593, x = 66.6, y = 79.8 }, desc = "I was tasked to retrieve important data on the flow of elemental energy from the Overlook Standing Stones. That data is vital to our plans to safely travel between Skywall and Azeroth. Without that data to aid in our calculations, our attempts to steer our skycutter ships through the elemental plane will fail.\n\nThe data is likely lost at this point, and I'm in no state to attempt to gather it again. I told the Supreme Magister of your role in saving me, and he wishes to speak with you again." },
})

ns.AddQuests("z17", {
    { id = 92706, name = "WANTED: Bruuz", level = 20, minLevel = 15, faction = "Horde", giver = "WANTED", start = { npc = "WANTED", area = 17, x = 62.6, y = 37.5 }, finish = { npc = "Gazlowe", area = 17, x = 62.6, y = 36.2 }, steps = { { name = "Bruuz's Dorsal Fin", area = 17, x = 64.6, y = 39.2 } }, objective = "Bring Bruuz's Dorsal Fin to Gazlowe in Ratchet.", desc = "Calling all anglers!\n\nA giant shark has been circling the waters near the shipping dock, attacking sailors and small boats. Dockworkers have given it the nickname \"Bruuz\". A hefty reward will be given to whoever brings me its fin!\n\n-- Gazlowe" },
    { id = 95494, name = "Bruised Pride and Lion Hides", level = 18, minLevel = 14, faction = "Horde", giver = "Vrang Wildgore", start = { npc = "Vrang Wildgore", area = 17, x = 43.8, y = 12.2 }, finish = { npc = "Vrang Wildgore", area = 17, x = 43.8, y = 12.2 }, steps = { { name = "Savannah Lion Hide", area = 17, x = 61.1, y = 32.9 } }, objective = "Collect 6 Savannah Lion Hides from the Savannah Matriarchs and Savannah Patriarchs in the Barrens.", desc = "I need someone with a strong sword arm and some extra time on their hands to help me gather some lion hides. It stings my pride to ask a stranger for this aid, but I took an injury to my leg recently. Until I heal, I'm in no shape to go hunting myself but I have obligations to keep.\n\nThe big ones in this area generally have the best hides, so start with those first." },
    { id = 95495, name = "The Hermit Tanner", level = 18, minLevel = 14, requires = { 95494 }, faction = "Horde", giver = "Vrang Wildgore", start = { npc = "Vrang Wildgore", area = 17, x = 43.8, y = 12.2 }, finish = { npc = "Walton", area = 17, x = 42, y = 11.4 }, objective = "Bring the Bundle of Hides to the hermit on the ridge overlooking the Dry Hills in the Barrens.", desc = "These hides are bound for a tanner who I often trade with. He is something of a hermit and he lives alone on the top of the ridge behind me. Climbing up a steep hillside isn't something I can manage easily right now so I'd be in your debt if you could make this delivery for me.\n\nOh, and about this tanner's... appearance. You need not be alarmed. In spite of his looks, he is no threat. I swear this is true." },
    { id = 95507, name = "Vrang's Game", level = 18, minLevel = 14, faction = "Horde", giver = "Vrang Wildgore", start = { npc = "Vrang Wildgore", area = 17, x = 43.8, y = 12.2 }, finish = { npc = "Vrang Wildgore", area = 17, x = 43.8, y = 12.2 }, objective = "Collect 8 Trapped Game from traps found in Sprung Traps in the Barrens.", desc = "While you are out there, it would be of great help to me if you could check on my traps for me. I've got them strewn all over the valley.\n\nBring back any small game that I've caught. Keep your eye out for the other wildlife, though. This area can be dangerous if you aren't paying attention." },
    { id = 95508, name = "Unwelcome Guests", level = 18, minLevel = 14, faction = "Horde", giver = "Walton", start = { npc = "Walton", area = 17, x = 42, y = 11.4 }, finish = { npc = "Walton", area = 17, x = 42, y = 11.4 }, steps = { { name = "Terry Longdrink", area = 17, x = 41.8, y = 11.4 } }, objective = "Help Walton survive the encounter with Terry Longdrink and the Kul Tiras marines.", desc = "Yes, I used to be a member of the Kul Tiras navy. After Lord Admiral took Theramore and started his campaign in Durotar, I had... \"objections\" to his methods. Particularly the methods involving executing civilians.\n\nThere's more to the story but... wait... what's that?\n\nThere's a group of men coming up the ridge!" },
    { id = 95621, name = "Trouble in the Valley", level = 18, minLevel = 14, requires = { 95495 }, faction = "Horde", giver = "Walton", start = { npc = "Walton", area = 17, x = 42, y = 11.4 }, finish = { npc = "Walton", area = 17, x = 42, y = 11.4 }, steps = { { name = "Benedict's Orders", area = 17, x = 41.9, y = 15.7 } }, objective = "Travel to the wrecked caravan and learn more about why the Kul Tirans are here.", desc = "This morning I spotted a group of humans searching for something in the valley below. I managed to use my rifle's scope for a better look, and it was clear that they were soldiers sporting the livery of Kul Tiras.\n\nIf you'd be willing to take work from me, travel to where these soldiers made camp near the wrecked caravan to the south. Kill any you find and try to learn why they are here." },
    { id = 95774, name = "Her Name Is Olgra", level = 20, minLevel = 14, requires = { 4921 }, faction = "Horde", giver = "Mankrik", start = { npc = "Mankrik", area = 17, x = 52, y = 31.6 }, finish = { npc = "Mankrik", area = 17, x = 52, y = 31.6 }, steps = { { name = "Olgra's Adornments", area = 17, x = 49.6, y = 51.4 } }, objective = "Slay quilboars and collect 4 of Olgra's Adornments for Mankrik's memorial.", desc = "The healer who saved me could not save her, and she has died in battle. Her name is Olgra, and I will never forget her.\n\nYou did not find her adornments on her body? She wore many jewels of polished bone.\n\nSlay the Razormane Raiders near where she fell, and find her precious works of art!\n\nI will place them with the memorial that I build in her memory." },
    { id = 95819, name = "Sign Me Up!", level = 60, minLevel = 1, objective = "Bring the completed form to Jornah in The Barrens.", desc = "Greetings, accomplished craftsperson!\n\nCompletion of this form will grant you non-exclusive, revocable, and legally limited permission to display advertisement signs for your tradeskill(s) all across Azeroth!\n\nOnce completed, please bring this to your local Durotar Supply & Logistics Contract Coordinator to begin processing.\n\nHappy crafting!" },
    { id = 97003, name = "Chol'aruk the Ravener", level = 21, minLevel = 15, faction = "Horde", giver = "Gur'ak", start = { npc = "Gur'ak", area = 17, x = 52.6, y = 29 }, finish = { npc = "Gur'ak", area = 17, x = 52.6, y = 29 }, steps = { { name = "Chol'aruk's Head", area = 17, x = 57.5, y = 27.3 } }, objective = "Bring the head of Chol'aruk to Gur'ak in the Barrens.", desc = "You there, <class>. I need your aid. There are rumors of a beast that makes its lair deep in a cave at Thorn Hill, northeast of here. The Razormane call it Chol'aruk or \"The Ravener\". It's supposedly five times the size of a normal quilboar with a thirst for blood that can never be sated.\n\nMost don't believe the tales. But I do--because I've fought its like before.\n\nSeek out its lair and slay Chol'aruk. Bring me its head. I warn you though--prepare well and do not go alone.\n\nBlood and thunder, <class>." },
    { id = 97005, name = "Chol'aruk the Ravener", level = 21, minLevel = 15, faction = "Alliance", giver = "Bainham", start = { npc = "Bainham", area = 17, x = 61.8, y = 39.4 }, finish = { npc = "Bainham", area = 17, x = 61.8, y = 39.4 }, steps = { { name = "Chol'aruk's Head", area = 17, x = 57.5, y = 27.3 } }, objective = "Bring Chol'aruk's Head to Bainham in the Barrens.", desc = "There's rumors of a monstrous abomination that makes its lair at a cave to the northwest of here, on the plateau known as Thorn Hill. The Razormane call it Chol'aruk or \"The Ravener\" and those that have seen it say its so massive that it can swallow an orc whole.\n\nFew believe such tales, but I do... because I've fought one like it myself. On the honor of those I lost to these things, this beast must die.\n\nGather strong allies and find the lair of Chol'aruk. Kill the abomination and bring me it's head." },
    { id = 97250, name = "Wrongly Blamed, Justly Corrected", level = 23, minLevel = 18, faction = "Horde", giver = "Grunt Logmar", start = { npc = "Grunt Logmar", area = 17, x = 44.6, y = 59.2 }, finish = { npc = "Grunt Logmar", area = 17, x = 44.6, y = 59.2 }, steps = { { name = "Encroaching Soldier", area = 17, x = 48.5, y = 77.3 }, { name = "Outraged Pillager", area = 17, x = 49, y = 77 } }, objective = "Slay Alliance soldiers encroaching into the Barrens at the border to Dustwallow Marsh, then return to Grunt Logmar at Camp Taurajo.", desc = "Traveler, have you plans to head toward Dustwallow Marsh? I have heard mutterings that a few human soldiers have taken a stand at its border and are toppling the landmarks left behind by our tauren pathfinders.\n\nRumor has it that a favored tavern has burned to the ground, and in typical Alliance fashion, they immediately cast their blame onto the Horde! I cannot know whether there is any truth to their claim, but their incursion onto OUR land must not stand.\n\nKill first, investigate later!" },
    { id = 97253, name = "Parts and Pieces", level = 14, minLevel = 9, faction = "Horde", giver = "Wrenix the Wretched", start = { npc = "Wrenix the Wretched", area = 17, x = 63, y = 36.4 }, finish = { npc = "Wrenix the Wretched", area = 17, x = 63, y = 36.4 }, objective = "Collect 5 Handfuls of Complicated Parts from the upper pirate camp south of Ratchet, then return to Wrenix the Wretched in Ratchet.", desc = "Hey, got a sec?\n\nSo, apparently, nobody I've sent to deal with the recent pirate problem has come back alive. After five or six attempts I thought, \"what if I sent a machine instead?\" Turns out, scimitars double as screwdrivers in a pinch, and before I could redirect it home, it was already in pieces and scattered across their camp!\n\nI need those parts back, and since this is a quick little retrieval mission, I'd wager your odds for survival are MUCH higher than the others. Whaddya say?" },
    { id = 98024, name = "Journey to the Crossroads", level = 13, minLevel = 7, faction = "Horde", giver = "Thrall", start = { npc = "Thrall", area = 1637, x = 32, y = 37.8 }, finish = { npc = "Thork", area = 17, x = 51.4, y = 30.8 }, desc = "After journeying here from the elemental plane, the problems our lands face may seem small. Rest assured, the dangers the horde faces are very real, and you will grow formidable should you survive your service.\n\nIf you'd like to get started doing some good in our world, travel southwest to the vast lands known as the Barrens. There is a settlement there known as the Crossroads. The proud citizens there are ever in need of aid.\n\nGo with honor, adventurer!" },
    { id = 98093, name = "Field to Clear", level = 23, minLevel = 18, faction = "Horde", giver = "Sulhasa", start = { npc = "Sulhasa", area = 17, x = 47.8, y = 77.6 }, finish = { npc = "Sulhasa", area = 17, x = 47.8, y = 77.6 }, steps = { { name = "Stormhide", area = 17, x = 46.6, y = 78 }, { name = "Hecklefang Stalker", area = 17, x = 46.5, y = 78.2 } }, objective = "Sulhasa in southern Barrens wants you to clear out 7 Stormhide lizards and 7 Hecklefang Stalkers in the area so she can leave the tree safely.", desc = "I'm so glad you saw me!\n\nThe weather was lovely this morning, so I walked from Camp Taurajo down the golden road. When it came time to head back, I couldn't--a pack of hyenas started circling, and Stormhide lizards blocked my only escape.\n\nScrambling up this tree I went, and now there are too many foes about at this hour for me to make the run home through the fields.\n\nWould you mind clearing out these Stormhide and Hecklefang Stalkers for me?" },
    { id = 98094, name = "Scout Support", level = 25, minLevel = 19, faction = "Horde", objective = "High Executor Darthalia wants you to deliver updated orders to Deathstalker Masoj, south of Tarren Mill, outside of Dun Garok", desc = "Now that we can trust you to deliver critical information to our forward spies, there's an extra task for you.\n\nBring this to Deathstalker Masoj almost directly south of us. He'll have more for you to do once you get there and hand this to him. He is posted on elevated terrain north of the rotten vineyard they call Nethander Stead.\n\nOur plan to take control of these lands continues steadily." },
    { id = 98095, name = "Valuable Vantages", level = 25, minLevel = 19, requires = { 98094 }, faction = "Horde", objective = "Deathstalker Masoj needs you to place the three Apothecary Vials on peaks around Hillsbrad Foothills and return to him.", desc = "Our high command inserts strategic troops using bat riders. Key points around the foothills have lost their signaling beacons.\n\nTake these vials. Uncork them in three locations: the hills bordering Dun Garok, the plataeu overlooking Dunholde Keep, and the last on the ridge of the Headland above the town of Hillsbrad. The vapors that emanate will be like a potent tuning rod to the senses of the bat, drawing them to the desired drop-off points once more.\n\nLook for crushed empty vials and renew our marks." },
})

ns.AddQuests("z215", {
    { id = 95805, name = "Grace of An'she and Mu'sha", level = 4, minLevel = 1, faction = "Horde", giver = "Seer Graytongue", start = { npc = "Seer Graytongue", area = 215, x = 42.6, y = 90 }, objective = "Carry the Smoldering Incense to the shrine of An'she and Mu'sha in the southeastern hills before the incense burns to ash in ten minutes!", desc = "The sun and the moon, An'she and Mu'sha, are not part of our world like the elements, yet their light gives us life, guidance, and hope.\n\nWe pay respect to the spirits of the world, and so we pay respect to the twins as well.\n\nIf you would show your respect, take this smoldering incense and bring it to a shrine in the hills to the southeast, overlooking the mesa, south of the quilboar. Be quick, so that you can reach the shrine before the incense burns away.\n\nDon't get it wet!" },
    { id = 96130, name = "Chakuyak", level = 8, minLevel = 5, faction = "Horde", giver = "Yaw Sharpmane", start = { npc = "Yaw Sharpmane", area = 215, x = 46.9, y = 59.6 }, finish = { npc = "Yaw Sharpmane", area = 215, x = 46.9, y = 59.6 }, steps = { { name = "Chakuyak's Pelt", area = 215, x = 40, y = 67.3 } }, objective = "Defeat Chakuyak and bring back her pelt.", desc = "Among the prairie wolves that hunt the hills nearby is one that is especially aggressive. We have taken to calling her Chakuyak. She has become a threat to travelers coming from abroad.\n\nShe stalks the trees west of Stonebull Lake, moving from tree stand to tree stand.\n\nEnd this threat and bring me her pelt, and I will speak your praises to the chief. Beware, for she is dangerous! You might see other hunters seeking her out there, and perhaps you could work as a team." },
    { id = 98424, name = "Fizsprocket's Notes", level = 10, minLevel = 5, faction = "Horde", finish = { npc = "Morin Cloudstalker", area = 215, x = 51.3, y = 63.4 }, steps = { { name = "Mulgore Expansion Plans", area = 215, x = 59.9, y = 51.1 } }, objective = "Collect the rest of Supervisor Fizsprocket's pages inside The Venture Co. Mine and bring them to Morin Cloudstalker near Bloodhoof Village.", desc = "Some particularly worn papers are held separately, folded in Fizsprocket's inside breast pocket.\n\nThey seem to detail important information that could be used against the Venture Co. and its operations in the region. It would be prudent to look for more before returning to Morin Cloudstalker." },
    { id = 98427, name = "Ceasing Operations", level = 12, minLevel = 5, requires = { 98424 }, faction = "Horde", giver = "Morin Cloudstalker", start = { npc = "Morin Cloudstalker", area = 215, x = 51.3, y = 63.4 }, finish = { npc = "Morin Cloudstalker", area = 215, x = 51.3, y = 63.4 }, steps = { { name = "Clearcutter Key", area = 215, x = 54.3, y = 49.2 } }, objective = "Bring the Clearcutter Key to Morin Cloudstalker outside Bloodhoof Village.", desc = "The shredder one of the pages speaks of--I have seen them before in my travels. They can decimate a forest in a fraction of the time that hand and axe can.\n\nEntire glades--homes to the Earth Mother's children for millenia--erased in days.\n\nWe will not allow this to happen in our home, a stone's throw from where our young ones take their first steps.\n\n<name>, I must ask you to gather others, go back into the mine to the northeast, and ensure it fells not a single tree more." },
    { id = 98430, name = "The Longwalkers", level = 8, minLevel = 1, faction = "Horde", giver = "Perith Stormhoof", start = { npc = "Perith Stormhoof", area = 215, x = 34.6, y = 68.1 }, finish = { npc = "Cairne Bloodhoof", area = 1638, x = 59.8, y = 51.6 }, objective = "Help Perith Stormhoof escape Palemane Rock, and report his safety to Cairne Bloodhoof in Thunder Bluff.", desc = "Hail, <class>. What brings you deep into such a dark and violent place?\n\nI was sent here by High Chieftain Cairne Bloodhoof as a part of our efforts to communicate with the gnolls that have taken residence. The rest of my mission must remain a secret, as do all things with the Longwalkers, the trusted scouts of our chieftain.\n\nAll you must know is our diplomacy was met with violence, and I fear I may be tonight's feast for the gnolls if you do not help me escape.\n\nAre you up to the task?" },
    { id = 98435, name = "Thunderhorn's Report", level = 10, minLevel = 4, requires = { 760 }, faction = "Horde", giver = "Mull Thunderhorn", start = { npc = "Mull Thunderhorn", area = 215, x = 47.4, y = 63.6 }, finish = { npc = "Arch Druid Hamuul Runetotem", area = 1638, x = 78.4, y = 28.4 }, objective = "Bring Thunderhorn's Report to Arch Druid Hamuul Runetotem in Thunder Bluff.", desc = "Our elders in Thunder Bluff must know of the progress we have made here, thanks to your aid.\n\nPlease, take this to Arch Druid Hamuul Runetotem in Thunder Bluff. You will find him in the Elder Rise, on the east side of the city. You must take the lifts up to the center of the city, then cross the bridges to reach it." },
    { id = 99079, name = "Longwalker Malah", level = 9, minLevel = 4, faction = "Horde", giver = "Brave Wildrunner", start = { npc = "Brave Wildrunner", area = 215, x = 45.9, y = 65.8 }, finish = { npc = "Malah Longwind", area = 215, x = 55.1, y = 65.9 }, desc = "The Longwalkers are our people's most trusted scouts. Though their loyalty lies with the High Chieftain alone, young Baine at times seeks their aid.\n\nThis is one such time. Longwalker Malah was dispatched near our borders to the east and did not return last night after three days. When this occurs, it is our duty to confirm their safety.\n\nI must ensure the village remains safe. Prove yourself, and seek Malah out. You will know her by her headband and feathered staff, emblematic of the Longwalkers." },
    { id = 99080, name = "Drive Them Out", level = 9, minLevel = 4, requires = { 99101 }, faction = "Horde", giver = "Baine Bloodhoof", start = { npc = "Baine Bloodhoof", area = 215, x = 46.6, y = 63.4 }, finish = { npc = "Baine Bloodhoof", area = 215, x = 46.6, y = 63.4 }, steps = { { name = "Herak's Head", area = 215, x = 57.5, y = 62.9 }, { name = "Galak Centaur", area = 215, x = 59.6, y = 64.1 }, { name = "Galak Outrunner", area = 215, x = 59.7, y = 64.1 } }, objective = "Kill 6 Galak Centaurs, 4 Galak Outrunners, and bring the head of Herak the Pillager to Baine Bloodhoof.", desc = "Hear my words well: we will not yield a single blade of grass to the centaur.\n\nGo to their camp now, before they have rested and have a chance to ride to our village. Slaughter them all. Ensure none escape to the Barrens to rally others to their aid.\n\nIf you find the leader of this would-be raiding party, bring me his head so that it may serve as a warning to others who dare tread on our ancestral homeland." },
    { id = 99081, name = "Grim Tidings", level = 9, minLevel = 4, requires = { 99079 }, faction = "Horde", giver = "Malah Longwind", start = { npc = "Malah Longwind", area = 215, x = 55.1, y = 65.9 }, finish = { npc = "Brave Wildrunner", area = 215, x = 45.9, y = 65.8 }, objective = "Bring Longwalker Malah's Report to Brave Wildrunner in Bloodhoof Village.\n\nProvided item:", desc = "You can see what appears to be a new centaur camp in the direction the arrows in Malah's back would have come from. There is a stir of activity, suggesting a small raiding party has made its way into Mulgore.\n\nThe Longwalker has a report in her still-clenched hand. Brave Wildrunner will want to know of Malah's fate--and her killers." },
    { id = 99082, name = "The High Chieftain", level = 9, minLevel = 4, requires = { 99080 }, faction = "Horde", giver = "Baine Bloodhoof", start = { npc = "Baine Bloodhoof", area = 215, x = 46.6, y = 63.4 }, finish = { npc = "Cairne Bloodhoof", area = 1638, x = 59.8, y = 51.6 }, desc = "Your bravery defending your people demands recognition. Journey to Thunder Bluff to the northwest, our mighty city whose shadow grants us shade in the warmer months, and seek audience with my father.\n\nIt was he who led the charge with the young Warchief Thrall to reclaim these plains and drive the centaur away for good. As High Chieftain, he will reward you generously for your part in ensuring his own bravery is honored.\n\nYou must take a lift to reach the High Chieftain, who sits on the central rise." },
    { id = 99101, name = "Our Ancient Enemy", level = 9, minLevel = 4, requires = { 99081 }, faction = "Horde", giver = "Brave Wildrunner", start = { npc = "Brave Wildrunner", area = 215, x = 45.9, y = 65.8 }, finish = { npc = "Baine Bloodhoof", area = 215, x = 46.6, y = 63.4 }, objective = "Bring Longwalker Malah's Report to Baine Bloodhoof.", desc = "Baine Bloodhoof leads our village. He must know of this incursion at once.\n\nBring him Longwalker Malah's report. You will find him at the center of town.\n\nQuickly, now. There is no time to waste!" },
    { id = 99108, name = "Sparring Match", level = 6, minLevel = 4, faction = "Horde", giver = "Krang Stonehoof", start = { npc = "Krang Stonehoof", area = 215, x = 48.2, y = 63.6 }, finish = { npc = "Krang Stonehoof", area = 215, x = 48.2, y = 63.6 }, objective = "Defeat 3 other players in duels or Novice Warriors for Tang Stonehoof.", desc = "Hail, young <class>. Though you are not a warrior and I cannot teach you that path, that does not mean you would not benefit from my tutelage.\n\nBefore you lies the arena. In it, it matters not who you call mother or whether you wield sword or bow. All are equal, and all learn to sharpen their horns in direct combat.\n\nWill you enter our space, and learn our ways for yourself? You may face any of these novices, or any other willing adversary. I care not which." },
    { id = 99196, name = "A Donation of Wool", level = 60, minLevel = 12, faction = "Horde", giver = "Oura Stormspinner", start = { npc = "Oura Stormspinner", area = 215, x = 35.6, y = 31.9 }, finish = { npc = "Oura Stormspinner", area = 215, x = 35.6, y = 31.9 } },
})

ns.AddQuests("z36", {
    { id = 99191, name = "A Donation of Wool", level = 60, minLevel = 12, faction = "Alliance" },
})

ns.AddQuests("z38", {
    { id = 86585, name = "Banner of the Fallen", level = 17, minLevel = 10, faction = "Alliance", giver = "Mountaineer Ylva", start = { npc = "Mountaineer Ylva", area = 38, x = 31.8, y = 86.2 }, finish = { npc = "Captain Rugelfuss", area = 38, x = 23.2, y = 73.8 }, steps = { { name = "Headsplitter", area = 38, x = 32.2, y = 86.4 } }, objective = "Raise the standard of Ironforge, call out the trogg Headsplitter and kill it, then report to Captain Rugelfuss.", desc = "The fallen mountaineer bears a standard of Ironforge. Perhaps she was scouting, or making a doomed charge. Either way, the standard has been cast down and trampled. The mountaineer was hit on the head so hard that her helm was knocked off and she was killed outright by a trogg, likely with a spiked club.\n\nThe trogg that killed her is probably still nearby, and likely remembers the banner. Raising the banner of Ironforge once more may call it out." },
    { id = 86613, name = "Excavation Tools", level = 18, minLevel = 13, faction = "Alliance", finish = { npc = "Prospector Ironband", area = 38, x = 65.8, y = 65.6 }, objective = "Return 6 Excavation Tools to Magmar Fellhew.", desc = "The excavation's tools, left behind when the dwarves fled from the troggs, seem mostly untouched. Returning them to the excavators will surely aid their work." },
    { id = 86614, name = "Silver of the Waves", level = 20, minLevel = 13, faction = "Alliance", finish = { npc = "Khara Deepwater", area = 38, x = 40.4, y = 39.4 }, objective = "Return the monogrammed silver hair clip to its owner.", desc = "<Among the fishing knickknacks in the debris are some rusty hooks, broken spools of wire, and a slightly corroded but ornate silver hair clip with the monogram \"K.D.\">" },
    { id = 86667, name = "Snowbound", level = 20, minLevel = 10, faction = "Alliance", giver = "Grenhild Darktalon", start = { npc = "Grenhild Darktalon", area = 38, x = 36.4, y = 48.2 }, finish = { npc = "Norric Lochthane", area = 38, x = 41.8, y = 19 }, objective = "Deliver a Jar of Snow to Norric Lochthane.", desc = "My old mentor, Norric, sent a minor elemental with an odd request. He needs a jar of snow for some of his shamanic workings! I don't know what he's going to do with that, but I learned a long time ago not to question his ways with respect to magic.\n\nI'm busy settling in and learning about the local elementals, so I can't leave to help him. Could you do this for me? Head over to South Gate Pass where there's snow year-round. Scoop some up in this ceramic jar and bring it to him before it melts." },
    { id = 86758, name = "Twisting the Knife", level = 16, minLevel = 12, faction = "Alliance", giver = "Marek Ironheart", start = { npc = "Marek Ironheart", area = 38, x = 81.8, y = 61.8 }, finish = { npc = "Marek Ironheart", area = 38, x = 81.8, y = 61.8 }, steps = { { name = "Marek's Croc-Hunting Knife", area = 38, x = 62, y = 44.7 } }, objective = "Find and defeat the crocolisk Daggerfang and bring back Marek's knife.", desc = "Did I ever tell you how I almost lost me hand to a crocolisk? Managed to jam me knife into its jaw, and scrambled out real quick. I thought I had the knife around here somewhere, but I can't seem to find it.\n\nAnyway, that croc is probably still out there hunting along the edge of the lake. That nasty brute probably needs to go, for the safety of the other hunters, if nothing else.\n\nI've taken to calling it Daggerfang. If you see it, give it a friendly hello from me! And by \"hello\" I mean \"stab.\"" },
    { id = 86776, name = "Ingredients for the Forge", level = 30, minLevel = 15, faction = "Alliance", giver = "Morhan Coppertongue", start = { npc = "Morhan Coppertongue", area = 38, x = 34, y = 46.6 }, finish = { npc = "Morhan Coppertongue", area = 38, x = 34, y = 46.6 }, objective = "Bring 10 Bronze Bars to Morhan Coppertongue.", desc = "Thelsamar's a great place to live, but we don't have all of the amenities of Ironforge. I'm always running out of bronze! I need more bronze if I'm going to keep making tools and kettles and pots!\n\nI can tell you have a little experience at the forge. Think you could smelt me some bronze bars? I can pay you well for it!" },
})

ns.AddQuests("z40", {
    { id = 92109, name = "My First Alchemy Set", level = 10, minLevel = 10, faction = "Alliance", giver = "Odd Child", objective = "Gather 5 Empty Vials, 5 Silverleaf, and 5 Peacebloom to the young, aspiring alchemist inside the barn of Moonbrook in Westfall.", desc = "Erm... 'Ello, <mister/miss>. I'm not supposed to talk to strangers, but... Hey, what are those shiny bottles sticking out of your backpack for? Are you an alchemist? That's so cool!\n\nWhen I grow up, I want to be an alchemist too. Daddy won't let me play with any of his herbs; too dangerous, he says.\n\nWell, I want to start learning now. Could you maybe get some supplies for me, pretty please?" },
    { id = 92110, name = "My First Real Potion", level = 10, minLevel = 10, requires = { 92109 }, faction = "Alliance", giver = "Odd Child", objective = "Gather 3 Murloc Eyes for the young, aspiring alchemist inside the barn of Moonbrook in Westfall.", desc = "Wow, my very first potion! Did you know that mixing those two herbs together would change the potion to a bright red color when you first started?\n\nThat was fun, but mixing a few flowers doesn't seem like the kind of alchemy Daddy does. He uses other ingredients too.\n\nI don't know what else to use, so let's try the first thing that comes to mind! Let's see... maybe murloc eyes? That sounds so gross, but I bet something will happen." },
    { id = 92742, name = "Testing the Wells", level = 12, minLevel = 9, faction = "Alliance", giver = "Alba Fairmoon", start = { npc = "Alba Fairmoon", area = 40, x = 52.4, y = 53 }, finish = { npc = "Alba Fairmoon", area = 40, x = 52.4, y = 53 }, objective = "Use the Well Water Sample Kit to collect samples from the wells at the Jansen Stead and the Molsen Farm.", desc = "We must determine the source and nature of the poison corrupting this land. Let us begin with the groundwater under the farms in the area.\nGo to the Jansen Stead and the Molsen Farm, and collect samples from the wells there." },
    { id = 92744, name = "Murloc Gills", level = 12, minLevel = 9, faction = "Alliance", giver = "Alba Fairmoon", start = { npc = "Alba Fairmoon", area = 40, x = 52.4, y = 53 }, finish = { npc = "Alba Fairmoon", area = 40, x = 52.4, y = 53 }, steps = { { name = "Longshore Murloc Gill", area = 40, x = 39.6, y = 14.4 } }, objective = "Alba Fairmoon wants you to collect 7 Longshore Murloc Gills along the shoreline of Westfall.", desc = "The corruption affecting Westfall's crops may have seeped into the ocean as well. If the local fish are affected too, it could doom Stormwind to famine.\nCollect gills from the murlocs along the shoreline and bring them to me. Murlocs are quite hardy, but their physiology is extremely sensitive to contaminants. Any toxins in the seawater will be readily apparent in the gills you find." },
    { id = 92745, name = "The State of the Mines", level = 14, minLevel = 9, faction = "Alliance", giver = "Alba Fairmoon", start = { npc = "Alba Fairmoon", area = 40, x = 52.4, y = 53 }, finish = { npc = "Alba Fairmoon", area = 40, x = 52.4, y = 53 }, steps = { { name = "Kobold Digger", area = 40, x = 45.1, y = 20.6 }, { name = "Riverpaw Miner", area = 40, x = 29.9, y = 48 } }, objective = "Slay 4 Kobold Diggers in the Jangolode Mine and 6 Riverpaw Miners in the Gold Coast Quarry.", desc = "The well samples you collected contain toxic metals! If we do not put an end to this corruption quickly, it will be decades before crops can grow in this soil again.\nThe Defias have seized the mines of Westfall and use creatures as labor to strip their resources. Disrupt them by slaying their miners in the Jangolode Mine to the north, and the Gold Coast Quarry to the west." },
    { id = 92747, name = "Moonbrook Espionage", level = 16, minLevel = 9, faction = "Alliance", giver = "Alba Fairmoon", start = { npc = "Alba Fairmoon", area = 40, x = 52.4, y = 53 }, finish = { npc = "Alba Fairmoon", area = 40, x = 52.4, y = 53 }, objective = "Collect 8 Suspicious Industrial Supplies from Moonbrook.", desc = "Strange - the poison does not seem to originate from the mines you investigated.\n\nI am told the Deadmines under the town of Moonbrook are the largest, deepest mines of Westfall, but they have been abandoned since the First War. Could the Deadmines be active again?\n\nPlease travel to Moonbrook, <name>, and look for evidence of mining or industrial activity. This is the last lead we have!" },
    { id = 92748, name = "Explosive Consultation", level = 16, minLevel = 9, faction = "Alliance", giver = "Alba Fairmoon", start = { npc = "Alba Fairmoon", area = 40, x = 52.4, y = 53 }, finish = { npc = "Sprite Jumpsprocket", area = 1519, x = 61.9, y = 30.6 }, desc = "The supplies you found point to a massive industrial operation somewhere in the Deadmines. There's no question that this is the source of the toxins plaguing the farmland of Westfall. We need to stop it, quickly.\n\nWhatever's down there will be difficult to destroy. Go to the Dwarven District of Stormwind, and find an engineer who can supply us with some explosives." },
    { id = 92749, name = "A Dynamite Plan", level = 16, minLevel = 9, faction = "Alliance", giver = "Sprite Jumpsprocket", start = { npc = "Sprite Jumpsprocket", area = 1519, x = 61.9, y = 30.6 }, finish = { npc = "Sprite Jumpsprocket", area = 1519, x = 61.9, y = 30.6 }, objective = "Obtain 10 Coarse Dynamite from crafting, trading, or the auction house, then return to Sprite Jumpsprocket in the Dwarven District of Stormwind.", desc = "Industrial sabotage? You've got my attention!\nWe'll start with some dynamite..." },
    { id = 92750, name = "Detonation at a Distance", level = 16, minLevel = 9, faction = "Alliance", giver = "Sprite Jumpsprocket", start = { npc = "Sprite Jumpsprocket", area = 1519, x = 61.9, y = 30.6 }, finish = { npc = "Jasper Fel", area = 1519, x = 80.2, y = 69.9 }, desc = "I assume you want a \"controlled\" explosion? Not as much fun, but a good choice if you want to keep all your limbs.\nI'm afraid I don't have a remote detonator - why don't you go check with the sneaky folks down at Stormwind Intelligence? They should be able to find us something." },
    { id = 92751, name = "Detonation at a Distance", level = 16, minLevel = 9, faction = "Alliance", giver = "Jasper Fel", start = { npc = "Jasper Fel", area = 1519, x = 80.2, y = 69.9 }, finish = { npc = "Sprite Jumpsprocket", area = 1519, x = 61.9, y = 30.6 }, objective = "Bring the Remote Detonator Kit to Sprite Jumpsprocket in the Dwarven District of Stormwind.", desc = "You need something destroyed? Would this have anything to do with your activities in Moonbrook? Don't look surprised. SI:7 stays apprised of all that goes on in Stormwind's lands.\nIf you're planning to set off an explosion in the caves below Westfall, you'll want to be well outside beforehand. Take this remote detonator - it's a recent prototype from our own engineers.\nOh - and it would be best if you didn't mention my involvement to your elf friend." },
    { id = 92752, name = "Explosive Consultation", level = 16, minLevel = 9, faction = "Alliance", giver = "Sprite Jumpsprocket", start = { npc = "Sprite Jumpsprocket", area = 1519, x = 61.9, y = 30.6 }, finish = { npc = "Alba Fairmoon", area = 40, x = 52.4, y = 53 }, objective = "Return to Alba Fairmoon in Westfall.", desc = "That's it - the bomb's ready to go! Careful with that detonator, now." },
    { id = 92753, name = "Destruction in Deadmines", level = 18, minLevel = 9, faction = "Alliance", giver = "Alba Fairmoon", start = { npc = "Alba Fairmoon", area = 40, x = 52.4, y = 53 }, finish = { npc = "Alba Fairmoon", area = 40, x = 38.6, y = 83.6 }, objective = "Find the forge hidden in the Deadmines, and plant the Extra-Destructive Explosives nearby. Then, meet up with Alba Fairmoon at the Deadmines exit.", desc = "The source of the poison is likely a large metallurgical forge of some kind. Find a way into the Deadmines and locate the forge, then place the explosives.\nI will wait for you in the hills behind Moonbrook. Once you return, we can detonate the explosives. Hopefully with the forge gone, the land can begin to heal." },
    { id = 92819, name = "Destruction in Deadmines", level = 18, minLevel = 9, faction = "Alliance", giver = "Alba Fairmoon", start = { npc = "Alba Fairmoon", area = 40, x = 38.6, y = 83.6 }, finish = { npc = "Alba Fairmoon", area = 40, x = 38.6, y = 83.6 }, objective = "Use the detonator.", desc = "We are almost finished. Use the detonator, and end this." },
    { id = 92909, name = "Harvesting the Harvesters", level = 15, minLevel = 8, faction = "Alliance", giver = "Ozwin Ironsprocket", start = { npc = "Ozwin Ironsprocket", area = 40, x = 51.6, y = 32.2 }, finish = { npc = "Ozwin Ironsprocket", area = 40, x = 51.6, y = 32.2 }, steps = { { name = "Golem Isospring", area = 40, x = 56.6, y = 21.3 }, { name = "Harvester Gyrostabilizer", area = 40, x = 51.4, y = 29.7 } }, objective = "Ozwin Ironsprocket at Saldean's Farm wants you to bring him 14 Golem Isosprings and 5 Harvester Gyrostabilizers.", desc = "Oh no... I'm in for it now!\n\nI heard about the harvesters terrorizing the fields of Westfall, so I traveled all the way from Ironforge to see if I could recalibrate them. But they're far more aggressive than my calculations anticipated, and they chased me into this stable!\n\nIf I had some isosprings and gyrostabilizers from the harvesters, I could build a device to cover my escape. Could you gather the parts for me?" },
    { id = 92910, name = "Harvesting the Harvesters", level = 15, minLevel = 8, faction = "Alliance", finish = { npc = "Ozwin Ironsprocket", area = 40, x = 51.6, y = 32.2 }, objective = "Bring the Precessive Autocognition Assembly to Ozwin Ironsprocket at Saldean's Farm.", desc = "The part you managed to salvage from the harvester appears mostly intact. Someone interested in harvest golems may want to see it." },
    { id = 92911, name = "Harvesting the Harvesters", level = 15, minLevel = 8, faction = "Alliance", giver = "Ozwin Ironsprocket", start = { npc = "Ozwin Ironsprocket", area = 40, x = 51.6, y = 32.2 }, finish = { npc = "Ozwin Ironsprocket", area = 40, x = 51.6, y = 32.2 }, steps = { { name = "Golem Isospring", area = 40, x = 52.5, y = 28 }, { name = "Copper Modulator", area = 40, x = 48.9, y = 27.4 }, { name = "Crude Scope", area = 40, x = 42.7, y = 68.4 } }, objective = "Ozwin Ironsprocket at Saldean's Farm wants you to bring him 8 Golem Isosprings, 4 Copper Modulators, and a Crude Scope.", desc = "I see... this gives me some insight into what makes those monsters tick. I have an idea how we could override their systems, at least momentarily.\n\nI'll continue tinkering with the assembly you brought me. In the meantime, could you scrounge up some parts for the device?" },
    { id = 93928, name = "Of Mice and Milk", level = 15, minLevel = 15, faction = "Alliance", giver = "Mouse", start = { npc = "Mouse", area = 40, x = 52.8, y = 54.2 }, finish = { npc = "Hemet Nesingwary", area = 33, x = 35.6, y = 10.8 }, desc = "I need a cookie, see?\n\nNyeah!" },
    { id = 98021, name = "Journey to Sentinel Hill", level = 13, minLevel = 7, faction = "Alliance", giver = "Highlord Bolvar Fordragon", start = { npc = "Highlord Bolvar Fordragon", area = 1519, x = 80, y = 38.4 }, finish = { npc = "Gryan Stoutmantle", area = 40, x = 56.2, y = 47.6 }, desc = "If you'd like to get started doing some good in our world, I'd recommend reporting to a man named Gryan Stoutmantle in Westfall to the south, at the settlement known as Sentinel Hill. His people are in need of aid.\n\nAfter journeying here from another plane of existence, the problems our lands face may seem small. I assure you, the aid you provide to those impacted by such problems means everything to them, and you will grow stronger for your labors.\n\nGood luck out there, adventurer!" },
})

ns.AddQuests("z406", {
    { id = 86574, name = "Stonetalon Supply Run", level = 24, minLevel = 20, faction = "Alliance", steps = { { name = "Stonetalon Supply Bundle", area = 400, x = 53.2, y = 41 } }, objective = "Collect 6 Stonetalon Supplies from Pridewing Wyverns and deliver them to Innkeeper Faralia.", desc = "<The unfortunate body here bears the marks of many strikes from the Pridewing wyverns. The pack nearby is rumpled and discarded, with its contents missing, and only a small note clutched in the courier's hand to indicate what was lost: a shipment meant for Innkeeper Faralia at Stonetalon Peak.>\n\n<The wyverns have probably carried off the supply bundles to line their nests.>" },
    { id = 86576, name = "Bloodfury Trinkets", level = 26, minLevel = 18, faction = "Horde", giver = "Maggran Earthbinder", start = { npc = "Maggran Earthbinder", area = 406, x = 47.2, y = 61 }, steps = { { name = "Glittering Sunstone", area = 406, x = 32.1, y = 66 } }, objective = "Bring 15 Glittering Sunstones to Mor'rogal.", desc = "In addition to spreading their filth across the Charred Vale, the Bloodfury harpies gather anything shiny that they can find. I'm told that they collect a variety of golden-yellow sunstones for decoration. I have no use for such trinkets, but Mor'rogal has mentioned using them before.\n\nWhile you're fighting the harpies of the Vale, keep your eye out for Glittering Sunstones. Bring any that you find to Mor'rogal, up on the hills above us." },
    { id = 97538, name = "Pigments for Paints", level = 26, minLevel = 20, faction = "Horde", giver = "Tah Winterhoof", start = { npc = "Tah Winterhoof", area = 1638, x = 54.2, y = 47.4 }, objective = "Tah Winterhoof in Thunder Bluff wants 30 Mirkweed Pods from Mirkfallon Lake.", desc = "Greetings, friend. I wonder if I may ask a favor of you? I have just run out of red pigment for my paints, and I am looking for one with younger hooves to make the long journey into the Stonetalon Mountains on my behalf.\n\nIn the middle of the mountain pass there lies a large circular lake, Mirkfallon Lake, that has a unique plant that grows within its waters. The pods of this plant, mirkweed, turn a vibrant red when dried. Gather the pods of this plant for me, and I will reward you well for your efforts." },
})

ns.AddQuests("z44", {
    { id = 91899, name = "A Sealed Crate", level = 60, minLevel = 1, giver = "Marcy Baker", start = { npc = "Marcy Baker", area = 44, x = 4.5, y = 71 }, finish = { npc = "Dokimi", area = 17, x = 50, y = 29.2 } },
    { id = 91900, name = "A Sealed Crate", level = 60, minLevel = 1, giver = "Marcy Baker", start = { npc = "Marcy Baker", area = 44, x = 4.5, y = 71 }, finish = { npc = "Dokimi", area = 17, x = 50, y = 29.2 } },
    { id = 91904, name = "A Sealed Crate", level = 60, giver = "Marcy Baker", start = { npc = "Marcy Baker", area = 44, x = 4.5, y = 71 }, finish = { npc = "Dokimi", area = 17, x = 50, y = 29.2 } },
    { id = 91905, name = "A Sealed Crate", level = 60, giver = "Marcy Baker", start = { npc = "Marcy Baker", area = 44, x = 4.5, y = 71 }, finish = { npc = "Dokimi", area = 17, x = 50, y = 29.2 } },
    { id = 95816, name = "Sign Me Up!", level = 60, minLevel = 1, objective = "Bring the completed form to Elaine Compton in Redridge Mountains.", desc = "Greetings, accomplished craftsperson!\n\nCompletion of this form will grant you non-exclusive, revocable, and legally limited permission to display advertisement signs for your tradeskill(s) all across Azeroth!\n\nOnce completed, please bring this to your local Azeroth Commerce Authority branch's Contract Coordinator to begin processing.\n\nHappy crafting!" },
    { id = 95999, name = "WANTED: Incinerator Gar'im", level = 25, minLevel = 16, faction = "Alliance", finish = { npc = "Magistrate Solomon", area = 44, x = 24.9, y = 44.2 }, steps = { { name = "Broken Staff of Incinerator Gar'im", area = 44, x = 72.3, y = 85.6 } }, objective = "Deliver the Broken Staff of Incinerator Gar'im to Magistrate Solomon in Lakeshire.", desc = "Wanted! Incinerator Gar'im, Leader of an orc incursion in Render's Valley. Purported to be working with the Blackrock of Stonewatch Keep.\n\nBeware of Incinerator Gar'im. He and his Shadowcasters are extremely dangerous. A handsome reward will to be given to any brave soul that can deliver proof of Incinerator Gar'im's demise to Magistrate Solomon." },
    { id = 98247, name = "Shipping Label", level = 60, minLevel = 10, faction = "Alliance", finish = { npc = "Marcy Baker", area = 44, x = 4.5, y = 71 }, objective = "Deliver the Shipping Label to someone at the Azeroth Commerce Authority trade hub in Redridge Mountains.", desc = "<A torn shipping label can be found on the side of the now fully stocked crate. Though the intended recipient is torn off, details of its origin still remain.\n\n\"Property of the Azeroth Commerce Authority. Please return empty crates or unfulfilled shipments to our local trade hub at the Three Corners crossroads in Redridge Mountains. Couriers will be compensated for their time and travel.\"\n\nBeside the text is a crudely drawn map of the area near the aforementioned destination.>" },
    { id = 98248, name = "Shipping Label", level = 60, minLevel = 10, faction = "Horde", finish = { npc = "Dokimi", area = 17, x = 50, y = 29.2 }, objective = "Deliver the Shipping Label to someone at the Durotar Supply and Logistics trade hub near the Crossroads in the Barrens.", desc = "<A torn shipping label can be found on the side of the now fully stocked crate. Though the intended recipient is torn off, details of its origin still remain.\n\n\"Return damaged shipments or empty crates to the Durotar Supply and Logistics trade outpost, now conveniently located due west of the Crossroads in the Barrens. Your time is valuable and we will compensate you for your efforts!\"\n\nBeside the text is a crudely drawn map of the area near the aforementioned destination.>" },
    { id = 98386, name = "Alther's Mill", level = 21, minLevel = 15, faction = "Alliance", giver = "Foreman Oslow", start = { npc = "Foreman Oslow", area = 44, x = 27.1, y = 48.6 }, finish = { npc = "Foreman Oslow", area = 44, x = 27.1, y = 48.6 }, steps = { { name = "Greater Tarantula", area = 44, x = 46.2, y = 41.5 } }, objective = "Slay 12 Greater Tarantulas and destroy 6 Tarantula Eggs in Alther's Mill for Foreman Oslow in Redridge.", desc = "Orcs, gnolls, murlocs. Everything seems to be out to stop me from getting this bridge done on time. Now we have word there's an infestation of tarantulas at our lumber mill!\n\nIf you're up to earn a bit more coin, would you head over to Alther's Mill to the east and clear out their spider problem? Place is as good as useless to me if I can't safely send workers to collect shipments.\n\nOh, and if you see ol' Alther, tell him he owes me for cleaning up his mess." },
    { id = 98387, name = "Blackrock Blockade", level = 21, minLevel = 18, faction = "Alliance", giver = "Marshal Marris", start = { npc = "Marshal Marris", area = 44, x = 28.3, y = 48.8 }, finish = { npc = "Marshal Marris", area = 44, x = 28.3, y = 48.8 }, objective = "Bring 10 Battleworn Axes to Marshal Marris in Lakeshire.", desc = "What the Blackrock orcs don't understand is that this is a war of attrition. Their brazen push into Alliance territory has left them vulnerable and without supplies, relying on the surrounding mountains to gather resources.\n\nAn army can't run on empty bellies, <name>. Go to their encampments south of Stonewatch Keep to the east and rob them of their food and weapons. Let's see the orcs' fighting spirit when they're starved and defenseless." },
    { id = 98407, name = "Show of Force", level = 17, minLevel = 11, faction = "Alliance", giver = "Deputy Feldon", start = { npc = "Deputy Feldon", area = 44, x = 25.7, y = 60 }, finish = { npc = "Deputy Feldon", area = 44, x = 25.7, y = 60 }, steps = { { name = "Spiked Collar", area = 44, x = 11.1, y = 64.2 } }, objective = "Collect 5 Spiked Collars from Gnoll Thrashers for Deputy Feldon near Lakeshire.", desc = "If the gnolls are growing so bold they are willing to camp this close to humans, there's no telling how much further they'll go. We need to deter them.\n\nThe beasts are hardly organized, but they seem to respect strength above all else. If we can slay the worst of them, maybe claim some of their trophies, we can remind these gnolls why they should stay in the hills where they belong.\n\nShould you see any of their thrashers, bring me their collars. That should put the fear of the Alliance back into them." },
})

ns.AddQuests("z85", {
    { id = 86784, name = "Sticks and Bones", level = 7, minLevel = 4, faction = "Horde", giver = "Deathguard Bartholomew", start = { npc = "Deathguard Bartholomew", area = 85, x = 58.4, y = 51.4 }, finish = { npc = "Eleanor Shackleton", area = 85, x = 57.2, y = 55.4 }, objective = "Collect 6 Dry Branches and bring them to Eleanor Shackleton.", desc = "My associate Eleanor Shackleton prides herself on traveling the wilds, surviving against weather and monsters. She is currently camped not far from here, in the hills to the west, and I remember a piece of advice that she once gave me: \"When you think you have enough firewood, gather five times more.\"\n\nIf you have some spare time, you could collect some wood in this basket and take it to her camp. I'm sure she could give you a few tips about the existence of a traveling adventurer." },
    { id = 95314, name = "That Shadowvale Green Elixir", level = 10, minLevel = 7, faction = "Horde", giver = "Carolai Anise", start = { npc = "Carolai Anise", area = 85, x = 59.4, y = 52.2 }, finish = { npc = "Carolai Anise", area = 85, x = 59.4, y = 52.2 }, objective = "Collect 8 Bottles of Whispering Elixir from Shadowvale, then return to Carolai Anise in Brill.", desc = "Before the Scourge invasion, the reclusive village of Shadowvale was known for its Whispering Elixir. Distilled from herbs found only in Tyr's Fall, the elixir was sought by apothecaries, mystics, and poisoners alike even after being banned in the city.\n\nI've had requests from a number of buyers eager to get their hands on some elixir. Travel to the ruins of Shadowvale deep in the Whispering Forest to the west. I'm prepared to offer significant compensation if you can recover some bottles for me." },
    { id = 95328, name = "Whispering Horror Residue", level = 10, minLevel = 7, faction = "Horde", finish = { npc = "Father Lankester", area = 1497, x = 49.6, y = 15.6 }, steps = { { name = "Whispering Horror Residue", area = 85, x = 9, y = 60.1 } }, objective = "Deliver Whispering Horror Residue to Father Lankester in the War Quarter of Undercity.", desc = "Against your better judgement you scrape up and collect the squirming remains of the beast. Someone in Undercity might have a use for them." },
    { id = 96895, name = "The Argent Emissary", level = 13, minLevel = 10, faction = "Horde", giver = "Deathguard Terrence", start = { npc = "Deathguard Terrence", area = 85, x = 61.4, y = 53.4 }, finish = { npc = "Hadric Harlson", area = 85, x = 65.8, y = 61 }, desc = "Not sure if you heard, but two emissaries of the Argent Dawn just passed through here. I don't mind the Argent Dawn, but I don't like them poking around Tirisfal unsupervised either. They were both Forsaken... but that doesn't make me any less nervous.\n\nOne of them just passed by here, headed southeast. There's a group of scourge cultists snooping around the outskirts of the city in that direction. If those two heard about them, there's no doubt that would have caught their attention." },
    { id = 96896, name = "A Righteous Cause", level = 13, minLevel = 10, requires = { 96899 }, faction = "Horde", giver = "Leonid Barthalomew the Revered", start = { npc = "Leonid Barthalomew the Revered", area = 85, x = 22, y = 44.8 }, finish = { npc = "Leonid Barthalomew the Revered", area = 85, x = 22, y = 44.8 }, desc = "Danitha and I fought against the scourge in the defense of the Undercity when Naxxramas attacked. We lost many good friends that day, including the hero after which this keep was named--Garek Bandarion.\n\nHe might just have been the first Forsaken to rediscover how to wield the light as a paladin. I am encouraged to see his legacy and potential live on here with Danitha and her cohort.\n\nIf only the rest of the forsaken felt the same way..." },
    { id = 96897, name = "The Cult of the Damned", level = 13, minLevel = 10, faction = "Horde", giver = "Hadric Harlson", start = { npc = "Hadric Harlson", area = 85, x = 65.8, y = 61 }, finish = { npc = "Hadric Harlson", area = 85, x = 65.8, y = 61 }, steps = { { name = "Dark Neophyte", area = 85, x = 68, y = 64.8 }, { name = "Dark Enforcer", area = 85, x = 68, y = 64.7 } }, objective = "Kill 8 Dark Neophytes and 8 Dark Enforcers in Tirisfal Glades.", desc = "The scourge are a blight on our lands, and their living servants are the worst of them. The people of Tirisfal have enough to deal with between the mindless dead and the Scarlet Crusade. If you wish to do some good, help me put an end to this scum." },
    { id = 96898, name = "Remnants of War", level = 13, minLevel = 10, faction = "Horde", giver = "Hadric Harlson", start = { npc = "Hadric Harlson", area = 85, x = 65.8, y = 61 }, finish = { npc = "Hadric Harlson", area = 85, x = 65.8, y = 61 }, steps = { { name = "Necrotic Crystal Fragment", area = 85, x = 68, y = 64.8 } }, objective = "Gather 12 Necrotic Crystal Fragments in Tirisfal Glades.", desc = "It wasn't long ago that the citadel of Naxxramas bore down upon this city, intent on wiping the Forsaken off the map. Both the Forsaken and the Argent Dawn lost much that day to secure the future of the Forsaken.\n\nDuring the battle, the great necrotic focusing crystal hanging beneath Naxxramas was shattered and its fragments were scattered all over this area. I suspect that is what the cultists are here for. Help me recover the fragments and deprive the scourge of them." },
    { id = 96899, name = "Bandarion Keep", level = 13, minLevel = 10, faction = "Horde", giver = "Hadric Harlson", start = { npc = "Hadric Harlson", area = 85, x = 65.8, y = 61 }, finish = { npc = "Leonid Barthalomew the Revered", area = 85, x = 22, y = 44.8 }, desc = "You've done a great thing for the cause of the Argent Dawn here today, and I thank you. I don't know how familiar you are with the fortress of Bandarion Keep, but my commander and I were headed that way to meet with the paladins that reside there. That was before we learned of the presence of the Cult of the Damned.\n\nIf you'd like to learn more about the Argent Dawn and our mission, seek out my commander at Bandarion Keep, to the northwest of here. I'll remain here to mop up the rest of this mess." },
    { id = 97558, name = "Hides for the Forsaken", level = 11, minLevel = 6, faction = "Horde", giver = "Shelene Rhobart", start = { npc = "Shelene Rhobart", area = 85, x = 65.4, y = 60 }, finish = { npc = "Shelene Rhobart", area = 85, x = 65.4, y = 60 }, objective = "Bring Shelene Rhobart 8 Duskbat Wing Membranes, 6 Darkhound Hides and 3 Vile Fin Murloc Skin.", desc = "One part of undeath no one mentions is what happens when we are injured. How does the skin of an undead heal itself?\n\nWell, it doesn't.\n\nOurs is a cursed life, <name>. We must take from the living to further our own existence.\n\nWhen we sustain an injury, we must replace our skin which usually means animal hides. Since different hide thicknesses are better for different places on our bodies a variety is key!\n\nBring me wing membranes of a duskbat, hides from a darkhound and skin of a Vile Fin murloc." },
    { id = 98389, name = "A Light in the Darkness", level = 4, minLevel = 2, faction = "Horde", giver = "Aramis Hammerhand", start = { npc = "Aramis Hammerhand", area = 85, x = 31, y = 66.2 }, finish = { npc = "Aramis Hammerhand", area = 85, x = 31, y = 66.2 }, steps = { { name = "Webbed Forsaken", area = 85, x = 24.9, y = 59.7 } }, objective = "Free 6 Webbed Victims in Night's Web Hollow for Aramis Hammerhand in Deathknell.", desc = "Greetings, <class>. Yes, I am a paladin. Not even death can stop the Light.\n\nThis my kind have in common with all Forsaken--we have overcome what the living view as their end. However, some even among our own fear us; they suspect we will smite them as some monstrosity.\n\nIn truth, our relationship with undeath is complex, but I am not here to hurt our own. Help me show the others this. Venture to Night's Web Hollow to the northwest and free the freshly raised fools trapped by the spiders there." },
    { id = 98545, name = "Leonid's Letter", level = 13, minLevel = 10, requires = { 96896 }, faction = "Horde", giver = "Leonid Barthalomew the Revered", start = { npc = "Leonid Barthalomew the Revered", area = 85, x = 22, y = 44.8 }, finish = { npc = "Glix Xizzix", area = 1497, x = 69.8, y = 47 }, objective = "Deliver the Sealed Letter to Glix Xizzix in the Undercity.", desc = "Since you are here, I'd like you to deliver this letter to an old friend of mine in the Undercity. I'd deliver myself but I have a somewhat colorful history with the Dark Lady, and it would be better if a neutral third party made the delivery.\n\nYou are looking for a goblin named Glix Xizzix in the Trade Quarter area of the Undercity. I'm sure he'd be happy to compensate you for your time.\n\n<Leonid lets out a low chuckle as he hands you the letter.>" },
    { id = 99134, name = "Discipline", level = 6, minLevel = 4, faction = "Horde", giver = "Executor Zygand", start = { npc = "Executor Zygand", area = 85, x = 60.6, y = 51.8 }, finish = { npc = "Executor Zygand", area = 85, x = 60.6, y = 51.8 }, steps = { { name = "Deathguard Linnea", area = 85, x = 58.1, y = 53.6 } }, objective = "Punish 5 Deathguards for Executor Zygand.", desc = "You are not a member of the Deathguard, and therefore have yet to disappoint me.\n\nAs a reward for your lack of incompetence, you shall be rewarded with punishing those that have demonstrated such talents in excess.\n\nSwiftly now--<name>, is it?--or I shall add your name to my ledger for someone else's reward." },
    { id = 99141, name = "Patience", level = 6, minLevel = 4, faction = "Horde", giver = "Executor Zygand", start = { npc = "Executor Zygand", area = 85, x = 60.6, y = 51.8 }, finish = { npc = "Executor Zygand", area = 85, x = 60.6, y = 51.8 }, objective = "Obtain reports from Deathguard Dillinger, Deathguard Kristof, and Gordo for Executor Zygand.", desc = "Make no mistake, <class>--the Dark Lady demands the perfect execution of her will. As an Executor, it is my duty to see that this happens.\n\nReports from several of my Deathguards are overdue. Needless to say, my patience has run out. Obtain their reports and bring them to me in the Dark Lady's name.\n\nYou will find Deathguard Dillinger just west of here, by the graveyard. Deathguard Kristof is stationed at the waystation to the east. And check on the abomination Gordo; he wanders west near Stillwater Pond." },
    { id = 99142, name = "Tomb Weed", level = 11, minLevel = 5, faction = "Horde", giver = "Junior Apothecary Holland", start = { npc = "Junior Apothecary Holland", area = 85, x = 57.6, y = 49 }, finish = { npc = "Junior Apothecary Holland", area = 85, x = 57.6, y = 49 }, objective = "Collect 5 Tomb Weed and deliver them back to Junior Apothecary Holland.", desc = "If you're heading east, towards the Balnir Farmstead, I have more you might do for me. Good help is ever so hard to find these days, as your run-in with Gordo illuminates ever so clearly.\n\nAs I acquire doom weed I perform some minor alchemical alterations and replant them on that farmstead to cultivate my ultimate creation. I call it tomb weed, and it shall be the herald of my glorious destiny.\n\nDo keep an eye on the Scourge in the area while you're there. They seem... drawn... to the weed. Curious." },
    { id = 99144, name = "Seeking Refuge", level = 7, minLevel = 5, faction = "Horde", giver = "Bareth Dawnstone", start = { npc = "Bareth Dawnstone", area = 85, x = 32, y = 46.2 }, finish = { npc = "Shari Stilwell", area = 85, x = 60.2, y = 52.6 }, objective = "Help Bareth Dawnstone escape Crusader's Outpost, and report his safety to Shari Stilwell in Brill.", desc = "Light bless you for finding me. I was on my way from Bandarion Keep to deliver a message to Shari Stilwell in Brill when these monsters captured me. They wield the Light with a hatred in their hearts that makes what's left of my blood seethe. It goes against all I meditate for... all I strive to protect!\n\n<Bareth Dawnstone steadies himself.>\n\nI know some still take issue with my kind, but I assure you our intentions are pure. If you would aid me in escaping this place, I would be forever grateful." },
    { id = 99152, name = "As Above, So Below", level = 10, minLevel = 7, faction = "Horde", giver = "Hilda the Breaker", start = { npc = "Hilda the Breaker", area = 85, x = 22, y = 47.2 }, finish = { npc = "Hilda the Breaker", area = 85, x = 22, y = 47.2 }, steps = { { name = "Faintly Glowing Bone", area = 85, x = 9.9, y = 66.4 } }, objective = "Collect 6 Faintly Glowing Bones for Hilda the Breaker.", desc = "While the Tarnished in Shadowvale to the southwest are definitely a problem, we cannot allow the cellars below the town to fester into a full-blown Scourge uprising on Bandarion Keep.\n\nI need to get these trainees up to snuff in case that happens. You, however, are going to receive what I like to call a crash course.\n\nTravel beneath Shadowvale and retrieve some of their wretched bones so we can study them further. I need ones that still retain some of the initial reanimation magic--that's glowing ones." },
    { id = 99153, name = "The One That Got Away", level = 10, minLevel = 7, faction = "Horde", giver = "Ephram Barbaro", start = { npc = "Ephram Barbaro", area = 85, x = 20.2, y = 46.4 }, finish = { npc = "Ephram Barbaro", area = 85, x = 20.2, y = 46.4 }, objective = "Find the Hidden Crystal Fragment beneath Shadowvale for Ephram Barbaro.", desc = "Oi, you! Word travels quickly among our ranks. I heard about the work you did with the cultists around the remnants of the battle with Naxxramas.\n\nProblem is, one of them cultists got away with a piece of the focusing crystal. Seems to still have some juice in it. Best guess we have is it's somewhere beneath Shadowvale. It's either raising 'em or making 'em stronger, and you don't want either one.\n\nFind that crystal before this gets out of hand." },
    { id = 99156, name = "Rear Guard Patrol (2/2)", level = 13, minLevel = 6, requires = { 356 }, faction = "Horde", giver = "Deathguard Linnea", start = { npc = "Deathguard Linnea", area = 85, x = 65.4, y = 60.2 }, finish = { npc = "Deathguard Linnea", area = 85, x = 65.4, y = 60.2 }, steps = { { name = "Riptear's Heart", area = 85, x = 82.5, y = 44.7 } }, objective = "Bring Riptear's Heart to Deathguard Linnea.", desc = "Damn it all! A new report came in while you were on patrol. There has been a sighting of a rogue abomination wandering Eastern Tirisfal Glades, near Venomweb Vale.\n\nSomething is wrong. Abominations don't just slip through the Bulwark unnoticed.\n\nKeep this matter on a strictly need-to-know basis. That said, such a creature will not fall easily; you will need allies if you wish to be more than its next meal.\n\nSee this through, and you will be duly rewarded. Bring me its heart as proof of the deed." },
})
